import type { ApiRequest } from "../../shared/api/httpClient";
import type { BasicInfo, IntradayTicker, SnapshotItem, StockCategoryGroup, StockSearchItem } from "./types";
import { normalizeStockCode } from "./utils/stockUtils";

/** 封裝股票查詢相關 API。 */
export function createStocksApi(request: ApiRequest) {
    /** 依關鍵字搜尋股票。 */
    async function searchStocks(keyword: string, limit = 20): Promise<StockSearchItem[]> {
        return request<StockSearchItem[]>(`/api/stocks/search?keyword=${encodeURIComponent(keyword)}&limit=${limit}`);
    }

    /** 一次取得全部即時快照，並轉為以股票代碼為 key 的 Map。 */
    async function fetchAllSnapshots(): Promise<Map<string, SnapshotItem>> {
        const data = await request<Record<string, SnapshotItem>>("/api/stocks/snapshots");
        const map = new Map<string, SnapshotItem>();
        for (const [key, value] of Object.entries(data)) {
            map.set(normalizeStockCode(key), value);
        }
        return map;
    }

    /** 取得指定股票的日內 Ticker。 */
    async function fetchTicker(stockCode: string): Promise<IntradayTicker> {
        return request<IntradayTicker>(`/api/stocks/${encodeURIComponent(stockCode)}/ticker`);
    }

    /** 取得指定股票的分類資訊。 */
    async function fetchCategoryGroups(stockCode: string): Promise<StockCategoryGroup[]> {
        return request<StockCategoryGroup[]>(`/api/stocks/${encodeURIComponent(stockCode)}/categories`);
    }

    /** 取得指定股票的基本資訊。 */
    async function fetchBasicInfo(stockCode: string): Promise<BasicInfo> {
        return request<BasicInfo>(`/api/stocks/${encodeURIComponent(stockCode)}/basic-info`);
    }

    return {
        searchStocks,
        fetchAllSnapshots,
        fetchTicker,
        fetchCategoryGroups,
        fetchBasicInfo,
    };
}
