<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from "vue";
import { getToken } from "../utils/auth";
import { usePagination } from "../composables/usePagination";
import TablePagination from "./TablePagination.vue";
import { createApiClient } from "../shared/api/httpClient";
import { apiBaseUrl } from "../shared/config/env";

type ScheduleItem = {
    id: string;
    name: string;
    cronExpression: string;
    isEnabled: boolean;
    symbolsCsv: string;
    maxCallsPerMinute: number;
    lastRunAtUtc: string | null;
    lastRunStatus: string | null;
    lastError: string | null;
};

type RunLog = {
    id: number;
    startedAtUtc: string;
    finishedAtUtc: string | null;
    status: string;
    message: string | null;
};

type ApiOption = {
    key: string;
    label: string;
    defaultEnabled?: boolean;
};

const apiOptions = ref<ApiOption[]>([]);
const defaultApiKeys = computed(() => {
    const enabled = apiOptions.value.filter((x) => x.defaultEnabled !== false).map((x) => x.key);

    if (enabled.length > 0) {
        return enabled;
    }

    return apiOptions.value.map((x) => x.key);
});
const selectedApiKeys = ref<string[]>([...defaultApiKeys.value]);

const emit = defineEmits<{
    back: [];
}>();

const { request } = createApiClient({ getToken, baseUrl: apiBaseUrl });
const items = ref<ScheduleItem[]>([]);
const selectedId = ref<string>("");
const runs = ref<RunLog[]>([]);
const loading = ref(false);
const saving = ref(false);
const triggering = ref(false);
const canceling = ref(false);
const refreshingRuns = ref(false);
const error = ref<string | null>(null);
const autoRefreshRunsEnabled = ref(false);
const autoRefreshRunsSeconds = ref(10);
const runsRefreshCountdown = ref(0);
let runsRefreshTimer: number | undefined;

const form = ref({
    id: "",
    name: "",
    cronExpression: "0 */5 * ? * MON-FRI *",
    isEnabled: true,
    symbolsText: "2330,2317",
    maxCallsPerMinute: 0,
});
const cronExpressions = ref<string[]>(["0 */5 * ? * MON-FRI *"]);

type ScheduleMode = "interval" | "daily" | "weekly" | "advanced";

type BuilderState = {
    intervalValue: number;
    intervalUnit: "seconds" | "minutes";
    intervalWeekdaysOnly: boolean;
    dailyTime: string;
    dailyWeekdaysOnly: boolean;
    weeklyDay: "MON" | "TUE" | "WED" | "THU" | "FRI" | "SAT" | "SUN";
    weeklyTime: string;
};

const scheduleMode = ref<ScheduleMode>("interval");
const builder = ref<BuilderState>({
    intervalValue: 5,
    intervalUnit: "minutes",
    intervalWeekdaysOnly: true,
    dailyTime: "09:00",
    dailyWeekdaysOnly: true,
    weeklyDay: "MON",
    weeklyTime: "09:00",
});

const weekDayOptions: Array<{ label: string; value: BuilderState["weeklyDay"] }> = [
    { label: "週一", value: "MON" },
    { label: "週二", value: "TUE" },
    { label: "週三", value: "WED" },
    { label: "週四", value: "THU" },
    { label: "週五", value: "FRI" },
    { label: "週六", value: "SAT" },
    { label: "週日", value: "SUN" },
];

const cronPreview = computed(() => {
    if (scheduleMode.value === "advanced") {
        return cronExpressions.value.join(" | ");
    }
    return buildCronFromBuilder(scheduleMode.value, builder.value);
});

const isEditing = computed(() => !!form.value.id);

/** 將兩位數字左補零，例如 9 -> "09"，用於 Cron 時間格式化。 */
function pad2(value: number): string {
    return value.toString().padStart(2, "0");
}

/** 解析 "HH:MM" 格式的時間字串，回傳 { hour, minute }；格式不合法時回傳預設值 { hour: 9, minute: 0 }。 */
function parseTime(value: string): { hour: number; minute: number } {
    const match = /^(\d{2}):(\d{2})$/.exec(value);
    if (!match) {
        return { hour: 9, minute: 0 };
    }

    const hour = Number(match[1]);
    const minute = Number(match[2]);
    if (hour < 0 || hour > 23 || minute < 0 || minute > 59) {
        return { hour: 9, minute: 0 };
    }

    return { hour, minute };
}

/** 將 UTC 時間字串格式化為台灣在地化時間（yyyy/MM/dd HH:mm:ss）；null 或無效值回傳 "尚未執行"。 */
function formatUtcDateTime(value: string | null): string {
    if (!value) {
        return "尚未執行";
    }

    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
        return value;
    }

    return date.toLocaleString("zh-TW", {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        hour12: false,
    });
}

/**
 * 依排程模式（interval/daily/weekly）從 builder 狀態產生 Quartz Cron 字串。
 * - interval: 每 N 秒/分鐘，可限週一至週五。
 * - daily: 每日固定時間，可限週一至週五。
 * - weekly: 每週特定星期幾的固定時間。
 * - advanced: 直接使用 form.cronExpression（不轉換）。
 */
function buildCronFromBuilder(mode: ScheduleMode, state: BuilderState): string {
    if (mode === "interval") {
        const safeValue = Math.min(59, Math.max(1, Math.floor(state.intervalValue || 5)));
        const dow = state.intervalWeekdaysOnly ? "MON-FRI" : "*";
        if (state.intervalUnit === "seconds") {
            return `0/${safeValue} * * ? * ${dow} *`;
        }
        return `0 */${safeValue} * ? * ${dow} *`;
    }

    if (mode === "daily") {
        const { hour, minute } = parseTime(state.dailyTime);
        if (state.dailyWeekdaysOnly) {
            return `0 ${minute} ${hour} ? * MON-FRI *`;
        }
        return `0 ${minute} ${hour} * * ? *`;
    }

    if (mode === "weekly") {
        const { hour, minute } = parseTime(state.weeklyTime);
        return `0 ${minute} ${hour} ? * ${state.weeklyDay} *`;
    }

    return form.value.cronExpression;
}

/**
 * 嘗試從現有 Cron 字串逆向推導 builder 狀態，以便在進入編輯時還原視覺化設定介面。
 * 若 Cron 字串無法對應任何已知模式，則切換為 advanced 模式（手動輸入）。
 */
function syncBuilderFromCron(cronExpression: string) {
    const cron = cronExpression.trim().toUpperCase();

    const intervalSeconds = /^(?:\*|\d{1,2})\/(\d{1,2}) \* \* \? \* (MON-FRI|\*) \*$/.exec(cron);
    if (intervalSeconds) {
        builder.value.intervalValue = Math.min(59, Math.max(1, Number(intervalSeconds[1]) || 5));
        builder.value.intervalUnit = "seconds";
        builder.value.intervalWeekdaysOnly = intervalSeconds[2] === "MON-FRI";
        scheduleMode.value = "interval";
        form.value.cronExpression = buildCronFromBuilder("interval", builder.value);
        return;
    }

    const interval = /^0 (?:\*\/|0\/)?(\d{1,2}) \* \? \* (MON-FRI|\*) \*$/.exec(cron);
    if (interval) {
        builder.value.intervalValue = Math.min(59, Math.max(1, Number(interval[1]) || 5));
        builder.value.intervalUnit = "minutes";
        builder.value.intervalWeekdaysOnly = interval[2] === "MON-FRI";
        scheduleMode.value = "interval";
        form.value.cronExpression = buildCronFromBuilder("interval", builder.value);
        return;
    }

    const dailyWeekdays = /^0 (\d{1,2}) (\d{1,2}) \? \* MON-FRI \*$/.exec(cron);
    if (dailyWeekdays) {
        builder.value.dailyTime = `${pad2(Number(dailyWeekdays[2]))}:${pad2(Number(dailyWeekdays[1]))}`;
        builder.value.dailyWeekdaysOnly = true;
        scheduleMode.value = "daily";
        form.value.cronExpression = buildCronFromBuilder("daily", builder.value);
        return;
    }

    const dailyAll = /^0 (\d{1,2}) (\d{1,2}) \* \* \? \*$/.exec(cron);
    if (dailyAll) {
        builder.value.dailyTime = `${pad2(Number(dailyAll[2]))}:${pad2(Number(dailyAll[1]))}`;
        builder.value.dailyWeekdaysOnly = false;
        scheduleMode.value = "daily";
        form.value.cronExpression = buildCronFromBuilder("daily", builder.value);
        return;
    }

    const weekly = /^0 (\d{1,2}) (\d{1,2}) \? \* (MON|TUE|WED|THU|FRI|SAT|SUN) \*$/.exec(cron);
    if (weekly) {
        builder.value.weeklyTime = `${pad2(Number(weekly[2]))}:${pad2(Number(weekly[1]))}`;
        builder.value.weeklyDay = weekly[3] as BuilderState["weeklyDay"];
        scheduleMode.value = "weekly";
        form.value.cronExpression = buildCronFromBuilder("weekly", builder.value);
        return;
    }

    scheduleMode.value = "advanced";
}

/** 將 builder 狀態轉換為 Cron 字串並寫回 form.cronExpression（advanced 模式時略過）。 */
function applyBuilderToCron() {
    if (scheduleMode.value === "advanced") {
        return;
    }
    const generated = buildCronFromBuilder(scheduleMode.value, builder.value);
    form.value.cronExpression = generated;
}

/** 解析多行/分號分隔的 Cron 字串，回傳去除空白後的陣列；若結果為空則回傳預設值。 */
function parseCronExpressions(raw: string): string[] {
    const values = raw
        .split(/[\r\n;]/)
        .map((x) => x.trim())
        .filter((x) => !!x);

    if (values.length === 0) {
        return ["0 */5 * ? * MON-FRI *"];
    }

    return values;
}

/** 將 cronExpressions 陣列第一個有效字串同步回 form.cronExpression（供 builder 預覽用）。 */
function syncCronExpressionFromRules() {
    const firstValid = cronExpressions.value.find((x) => x.trim().length > 0);
    if (firstValid) {
        form.value.cronExpression = firstValid.trim();
    }
}

/** 將 form.cronExpression 中的 Cron 字串新增至 cronExpressions 陣列（若已存在則顯示錯誤）。 */
function addCronRule() {
    const next = form.value.cronExpression.trim();
    if (!next) {
        error.value = "請先輸入一條 CRON 再新增。";
        return;
    }

    if (cronExpressions.value.includes(next)) {
        error.value = "這條 CRON 已存在。";
        return;
    }

    cronExpressions.value.push(next);
    error.value = null;
}

/** 從 cronExpressions 陣列移除指定索引的 Cron 規則；若只剩一條則重設為預設值。 */
function removeCronRule(index: number) {
    if (cronExpressions.value.length <= 1) {
        cronExpressions.value = ["0 */5 * ? * MON-FRI *"];
        form.value.cronExpression = cronExpressions.value[0];
        return;
    }

    cronExpressions.value.splice(index, 1);
    syncCronExpressionFromRules();
}

/**
 * 套用「盤中每秒更新」預設 Cron 組合（共兩條 Cron）：
 * - 08:30-08:59 每秒（開盤前）
 * - 09:00-13:59 每秒（盤中）
 * 套用後自動切換為 advanced 模式。
 */
function applyTradingSessionPerSecondPreset() {
    const preset = ["*/1 30-59 8 ? * MON-FRI *", "*/1 * 9-13 ? * MON-FRI *"];
    const merged = [...cronExpressions.value, ...preset].map((x) => x.trim()).filter((x) => !!x);

    cronExpressions.value = [...new Set(merged)];
    form.value.cronExpression = preset[0];
    scheduleMode.value = "advanced";
}

const sortedRuns = computed(() => [...runs.value].sort((a, b) => (a.startedAtUtc < b.startedAtUtc ? 1 : -1)));
const runPagination = usePagination(sortedRuns, 20);

/** 載入可用的 API 選項（candles/revenue/...），並設定 selectedApiKeys 的初始值。 */
async function loadApiOptions() {
    try {
        const data = await request<ApiOption[]>("/api/admin/schedules/api-options");
        const normalized = data
            .map((x) => ({
                key: (x.key ?? "").trim().toLowerCase(),
                label: (x.label ?? "").trim(),
                defaultEnabled: x.defaultEnabled !== false,
            }))
            .filter((x) => x.key.length > 0 && x.label.length > 0);

        if (normalized.length > 0) {
            apiOptions.value = normalized;
        }
    } catch {
        apiOptions.value = [];
    }

    if (!isEditing.value) {
        selectedApiKeys.value = [...defaultApiKeys.value];
    }
}

/** 載入所有排程設定清單；若無選中排程則自動選擇第一筆。 */
async function loadSchedules() {
    loading.value = true;
    error.value = null;
    try {
        items.value = await request<ScheduleItem[]>("/api/admin/schedules");
        if (!selectedId.value && items.value.length > 0) {
            await selectSchedule(items.value[0]);
        }
    } catch (err) {
        error.value = err instanceof Error ? err.message : "載入排程失敗";
    } finally {
        loading.value = false;
    }
}

/**
 * 選取指定排程，解析其 SymbolsCsv（含 @api: 指令）並填充表單，
 * 同時逆向還原 builder 狀態，並刷新執行記錄。
 */
async function selectSchedule(item: ScheduleItem) {
    const rawTokens = item.symbolsCsv
        .split(",")
        .map((x) => x.trim())
        .filter((x) => !!x);

    const availableKeys = new Set(apiOptions.value.map((x) => x.key));
    const apiDirective = rawTokens.find((x) => x.toLowerCase().startsWith("@api:"));
    if (apiDirective) {
        const values = apiDirective
            .slice(5)
            .split("|")
            .map((x) => x.trim().toLowerCase())
            .filter((x) => availableKeys.has(x));
        selectedApiKeys.value = values.length > 0 ? values : [...defaultApiKeys.value];
    } else {
        selectedApiKeys.value = [...defaultApiKeys.value];
    }

    const symbolsOnly = rawTokens.filter((x) => !x.toLowerCase().startsWith("@api:"));

    selectedId.value = item.id;
    form.value = {
        id: item.id,
        name: item.name,
        cronExpression: item.cronExpression,
        isEnabled: item.isEnabled,
        symbolsText: symbolsOnly.join(","),
        maxCallsPerMinute: item.maxCallsPerMinute ?? 0,
    };

    cronExpressions.value = parseCronExpressions(item.cronExpression);
    form.value.cronExpression = cronExpressions.value[0];
    syncBuilderFromCron(cronExpressions.value[0]);

    await refreshRuns(item.id, true);
}

/** 重新從 API 取得執行記錄。silent=true 時不更新 refreshingRuns loading 狀態（靜默背景刷新）。 */
async function refreshRuns(id?: string, silent = false) {
    const targetId = id ?? selectedId.value;
    if (!targetId) {
        runs.value = [];
        return;
    }

    if (!silent) {
        refreshingRuns.value = true;
    }

    try {
        runs.value = await request<RunLog[]>(`/api/admin/schedules/${targetId}/runs?take=0`);
    } catch (err) {
        if (!silent) {
            error.value = err instanceof Error ? err.message : "刷新執行紀錄失敗";
        }
    } finally {
        if (!silent) {
            refreshingRuns.value = false;
        }
    }
}

/** 手動刷新執行記錄，若自動刷新已啟用則同步重設倒數計時器。 */
async function manualRefreshRuns() {
    await refreshRuns();
    if (autoRefreshRunsEnabled.value) {
        runsRefreshCountdown.value = Math.max(1, Math.floor(autoRefreshRunsSeconds.value || 10));
    }
}

/** 停止自動刷新計時器並重設倒數計時器。 */
function stopRunsAutoRefresh() {
    if (runsRefreshTimer !== undefined) {
        globalThis.clearInterval(runsRefreshTimer);
        runsRefreshTimer = undefined;
    }
    runsRefreshCountdown.value = 0;
}

/** 啟動自動刷新計時器（每秒倒數，到 0 時靜默更新執行記錄）。 */
function startRunsAutoRefresh() {
    stopRunsAutoRefresh();

    if (!autoRefreshRunsEnabled.value || !selectedId.value) {
        return;
    }

    const seconds = Math.max(1, Math.floor(autoRefreshRunsSeconds.value || 10));
    autoRefreshRunsSeconds.value = seconds;
    runsRefreshCountdown.value = seconds;

    runsRefreshTimer = globalThis.setInterval(() => {
        runsRefreshCountdown.value -= 1;
        if (runsRefreshCountdown.value <= 0) {
            runsRefreshCountdown.value = seconds;
            void refreshRuns(selectedId.value, true);
        }
    }, 1000);
}

/** 清空表單，重設為建立新排程的初始狀態，並停止自動刷新。 */
function resetForm() {
    selectedId.value = "";
    runs.value = [];
    form.value = {
        id: "",
        name: "",
        cronExpression: "0 */5 * ? * MON-FRI *",
        isEnabled: true,
        symbolsText: "",
        maxCallsPerMinute: 0,
    };
    cronExpressions.value = ["0 */5 * ? * MON-FRI *"];
    selectedApiKeys.value = [...defaultApiKeys.value];
    builder.value = {
        intervalValue: 5,
        intervalUnit: "minutes",
        intervalWeekdaysOnly: true,
        dailyTime: "09:00",
        dailyWeekdaysOnly: true,
        weeklyDay: "MON",
        weeklyTime: "09:00",
    };
    scheduleMode.value = "interval";
    stopRunsAutoRefresh();
}

/** 複製目前已選排程的表單內容為新排程草稿（名稱加上「（複製）」後綴，清除 ID）。 */
function copyCurrentSchedule() {
    if (!isEditing.value) {
        return;
    }

    selectedId.value = "";
    runs.value = [];
    form.value = {
        ...form.value,
        id: "",
        name: form.value.name ? `${form.value.name}（複製）` : "",
    };
    cronExpressions.value = [...cronExpressions.value];
    selectedApiKeys.value = [...selectedApiKeys.value];
    error.value = null;
}

async function save() {
    saving.value = true;
    error.value = null;
    try {
        const normalizedCronExpressions = cronExpressions.value.map((x) => x.trim()).filter((x) => !!x);
        if (normalizedCronExpressions.length === 0) {
            throw new Error("至少需要一條 CRON 規則。");
        }

        const body = {
            name: form.value.name,
            cronExpression: normalizedCronExpressions.join("\n"),
            isEnabled: form.value.isEnabled,
            maxCallsPerMinute: Math.max(0, Math.floor(form.value.maxCallsPerMinute || 0)),
            symbols: [
                ...form.value.symbolsText
                    .split(",")
                    .map((x) => x.trim())
                    .filter((x) => !!x),
                `@api:${(selectedApiKeys.value.length > 0 ? selectedApiKeys.value : defaultApiKeys.value).join("|")}`,
            ],
        };

        if (isEditing.value) {
            await request(`/api/admin/schedules/${form.value.id}`, {
                method: "PUT",
                body: JSON.stringify(body),
            });
        } else {
            await request("/api/admin/schedules", {
                method: "POST",
                body: JSON.stringify(body),
            });
        }

        await loadSchedules();
        if (!isEditing.value) {
            resetForm();
        }
    } catch (err) {
        error.value = err instanceof Error ? err.message : "儲存失敗";
    } finally {
        saving.value = false;
    }
}

/** 刪除排程（須使用者確認），若已選中則清空选單後重新載入清單。 */
async function remove(id: string) {
    if (!confirm("確定要刪除此排程？")) return;

    await request(`/api/admin/schedules/${id}`, { method: "DELETE" });
    if (selectedId.value === id) {
        selectedId.value = "";
        runs.value = [];
        resetForm();
    }
    await loadSchedules();
}

/** 立即觸發指定排程執行一次（呼叫 POST /trigger 端點）。 */
async function triggerNow(id: string) {
    await request(`/api/admin/schedules/${id}/trigger`, { method: "POST" });
    await loadSchedules();
    const selected = items.value.find((x) => x.id === id);
    if (selected) {
        await selectSchedule(selected);
    }
}

/** 手動執行目前選中的排程（需先選取排程才能呼叫）。 */
async function triggerCurrentSchedule() {
    if (!isEditing.value || !form.value.id) {
        error.value = "請先選擇既有排程再手動執行。";
        return;
    }

    triggering.value = true;
    error.value = null;
    try {
        await triggerNow(form.value.id);
    } catch (err) {
        error.value = err instanceof Error ? err.message : "手動執行失敗";
    } finally {
        triggering.value = false;
    }
}

/** 強制取消目前選中排程的執行中任務；若無執行中實例，API 會回傳提示。 */
async function cancelCurrentSchedule() {
    if (!isEditing.value || !form.value.id) {
        error.value = "請先選擇既有排程再執行取消。";
        return;
    }

    if (!confirm("確定要強制取消目前執行中的排程嗎？")) {
        return;
    }

    canceling.value = true;
    error.value = null;
    try {
        await request(`/api/admin/schedules/${form.value.id}/cancel`, { method: "POST" });
        await loadSchedules();
        const selected = items.value.find((x) => x.id === form.value.id);
        if (selected) {
            await selectSchedule(selected);
        }
    } catch (err) {
        error.value = err instanceof Error ? err.message : "取消執行失敗";
    } finally {
        canceling.value = false;
    }
}

/** 暫停指定排程（設為停用並從 Quartz 移除 Job）。 */
async function pauseSchedule(id: string) {
    await request(`/api/admin/schedules/${id}/pause`, { method: "POST" });
    await loadSchedules();
    const selected = items.value.find((x) => x.id === id);
    if (selected) {
        await selectSchedule(selected);
    }
}

/** 恢復指定排程（重新啟用並加入 Quartz）。 */
async function resumeSchedule(id: string) {
    await request(`/api/admin/schedules/${id}/resume`, { method: "POST" });
    await loadSchedules();
    const selected = items.value.find((x) => x.id === id);
    if (selected) {
        await selectSchedule(selected);
    }
}

onMounted(async () => {
    await loadApiOptions();
    await loadSchedules();
});

onUnmounted(() => {
    stopRunsAutoRefresh();
});

watch(
    [scheduleMode, builder],
    () => {
        applyBuilderToCron();
    },
    { deep: true },
);

watch(
    cronExpressions,
    () => {
        syncCronExpressionFromRules();
    },
    { deep: true },
);

watch([selectedId, autoRefreshRunsEnabled, autoRefreshRunsSeconds], () => {
    startRunsAutoRefresh();
});
</script>

<template>
    <div class="mx-auto grid h-[calc(100vh-111px)] w-full max-w-7xl grid-cols-1 gap-4 overflow-hidden p-4 lg:grid-cols-[360px_1fr]">
        <aside class="rounded-2xl border border-slate-200 bg-slate-50/80 p-4 shadow-lg">
            <div class="mb-3 flex items-center justify-between">
                <h2 class="text-lg font-black text-slate-900">排程監看</h2>
                <button class="rounded bg-slate-200 px-2 py-1 text-xs font-semibold text-slate-700 hover:bg-slate-300" @click="emit('back')">返回主畫面</button>
            </div>

            <p v-if="loading" class="text-xs text-slate-500">載入中...</p>
            <p v-if="error" class="mb-2 rounded bg-rose-50 px-2 py-1 text-xs text-rose-700">{{ error }}</p>

            <ul class="space-y-2 overflow-y-auto pr-1">
                <li v-for="item in items" :key="item.id" class="rounded border p-2" :class="selectedId === item.id ? 'border-cyan-400 bg-cyan-50' : 'border-slate-200 bg-white'">
                    <button class="w-full text-left" @click="selectSchedule(item)">
                        <p class="text-sm font-semibold text-slate-900">
                            {{ item.name }}
                            <span v-if="!item.isEnabled" class="ml-1 rounded bg-amber-100 px-1.5 py-0.5 text-[10px] font-bold text-amber-700">已暫停</span>
                        </p>
                        <p class="text-xs text-slate-500">
                            {{
                                item.cronExpression
                                    .split(/[\r\n;]/)
                                    .map((x) => x.trim())
                                    .filter((x) => !!x)[0] ?? item.cronExpression
                            }}
                        </p>
                        <p
                            v-if="
                                item.cronExpression
                                    .split(/[\r\n;]/)
                                    .map((x) => x.trim())
                                    .filter((x) => !!x).length > 1
                            "
                            class="text-[11px] text-slate-400"
                        >
                            +
                            {{
                                item.cronExpression
                                    .split(/[\r\n;]/)
                                    .map((x) => x.trim())
                                    .filter((x) => !!x).length - 1
                            }}
                            條 CRON
                        </p>
                        <p class="mt-0.5 text-xs text-slate-500">最後結束：{{ formatUtcDateTime(item.lastRunAtUtc) }}</p>
                        <p class="mt-1 text-xs" :class="item.lastRunStatus === 'Success' ? 'text-emerald-600' : item.lastRunStatus === 'Failed' ? 'text-rose-600' : item.lastRunStatus === 'Canceled' ? 'text-amber-600' : 'text-slate-500'">最後執行：{{ item.lastRunStatus ?? "尚未執行" }}</p>
                    </button>
                    <div class="mt-2 flex gap-2">
                        <button v-if="item.isEnabled" class="rounded bg-amber-500 px-2 py-1 text-xs font-semibold text-white hover:bg-amber-400" @click="pauseSchedule(item.id)">暫停使用</button>
                        <button v-else class="rounded bg-emerald-600 px-2 py-1 text-xs font-semibold text-white hover:bg-emerald-500" @click="resumeSchedule(item.id)">恢復使用</button>
                        <button class="rounded bg-cyan-600 px-2 py-1 text-xs font-semibold text-white hover:bg-cyan-500" @click="triggerNow(item.id)">立即執行</button>
                        <button class="rounded bg-rose-600 px-2 py-1 text-xs font-semibold text-white hover:bg-rose-500" @click="remove(item.id)">刪除</button>
                    </div>
                </li>
            </ul>
        </aside>

        <section class="overflow-y-auto rounded-2xl border border-slate-200 bg-white p-4 shadow-lg">
            <div class="flex items-center justify-between gap-2">
                <h3 class="text-base font-black text-slate-900">{{ isEditing ? "編輯排程" : "建立排程" }}</h3>
                <div v-if="isEditing" class="flex items-center gap-2">
                    <button class="rounded border border-emerald-300 bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-700 hover:bg-emerald-100" @click="copyCurrentSchedule">複製排程</button>
                    <button class="rounded border border-slate-300 bg-white px-3 py-2 text-xs font-semibold text-slate-700 hover:bg-slate-50" @click="resetForm">新增排程</button>
                </div>
            </div>
            <div class="mt-3 grid gap-3 md:grid-cols-2">
                <label class="text-xs font-semibold text-slate-600">
                    名稱
                    <input v-model="form.name" class="mt-1 w-full rounded border border-slate-300 px-2 py-2 text-sm" type="text" />
                </label>
                <div class="text-xs font-semibold text-slate-600">
                    排程模式
                    <div class="mt-1 grid grid-cols-2 gap-2 lg:grid-cols-4">
                        <button class="rounded border px-2 py-2 text-xs font-semibold" :class="scheduleMode === 'interval' ? 'border-cyan-500 bg-cyan-50 text-cyan-700' : 'border-slate-300 bg-white text-slate-700 hover:bg-slate-50'" @click="scheduleMode = 'interval'">每 N 分鐘</button>
                        <button class="rounded border px-2 py-2 text-xs font-semibold" :class="scheduleMode === 'daily' ? 'border-cyan-500 bg-cyan-50 text-cyan-700' : 'border-slate-300 bg-white text-slate-700 hover:bg-slate-50'" @click="scheduleMode = 'daily'">每日</button>
                        <button class="rounded border px-2 py-2 text-xs font-semibold" :class="scheduleMode === 'weekly' ? 'border-cyan-500 bg-cyan-50 text-cyan-700' : 'border-slate-300 bg-white text-slate-700 hover:bg-slate-50'" @click="scheduleMode = 'weekly'">每週</button>
                        <button class="rounded border px-2 py-2 text-xs font-semibold" :class="scheduleMode === 'advanced' ? 'border-amber-500 bg-amber-50 text-amber-700' : 'border-slate-300 bg-white text-slate-700 hover:bg-slate-50'" @click="scheduleMode = 'advanced'">進階 CRON</button>
                    </div>
                </div>

                <div v-if="scheduleMode === 'interval'" class="rounded border border-cyan-100 bg-cyan-50/40 p-3 text-xs text-slate-700 md:col-span-2">
                    <div class="grid gap-3 md:grid-cols-3">
                        <label class="font-semibold text-slate-600">
                            每隔
                            <input v-model.number="builder.intervalValue" class="mt-1 w-full rounded border border-slate-300 px-2 py-2 text-sm" type="number" min="1" max="59" />
                        </label>
                        <label class="font-semibold text-slate-600">
                            單位
                            <select v-model="builder.intervalUnit" class="mt-1 w-full rounded border border-slate-300 bg-white px-2 py-2 text-sm">
                                <option value="seconds">秒</option>
                                <option value="minutes">分鐘</option>
                            </select>
                        </label>
                        <label class="inline-flex items-center gap-2 self-end font-semibold text-slate-600">
                            <input v-model="builder.intervalWeekdaysOnly" type="checkbox" />
                            僅平日（MON-FRI）
                        </label>
                    </div>
                </div>

                <div v-if="scheduleMode === 'daily'" class="rounded border border-cyan-100 bg-cyan-50/40 p-3 text-xs text-slate-700 md:col-span-2">
                    <div class="grid gap-3 md:grid-cols-2">
                        <label class="font-semibold text-slate-600">
                            每日執行時間
                            <input v-model="builder.dailyTime" class="mt-1 w-full rounded border border-slate-300 px-2 py-2 text-sm" type="time" />
                        </label>
                        <label class="inline-flex items-center gap-2 self-end font-semibold text-slate-600">
                            <input v-model="builder.dailyWeekdaysOnly" type="checkbox" />
                            僅平日（MON-FRI）
                        </label>
                    </div>
                </div>

                <div v-if="scheduleMode === 'weekly'" class="rounded border border-cyan-100 bg-cyan-50/40 p-3 text-xs text-slate-700 md:col-span-2">
                    <div class="grid gap-3 md:grid-cols-2">
                        <label class="font-semibold text-slate-600">
                            星期
                            <select v-model="builder.weeklyDay" class="mt-1 w-full rounded border border-slate-300 bg-white px-2 py-2 text-sm">
                                <option v-for="option in weekDayOptions" :key="option.value" :value="option.value">
                                    {{ option.label }}
                                </option>
                            </select>
                        </label>
                        <label class="font-semibold text-slate-600">
                            執行時間
                            <input v-model="builder.weeklyTime" class="mt-1 w-full rounded border border-slate-300 px-2 py-2 text-sm" type="time" />
                        </label>
                    </div>
                </div>

                <label class="text-xs font-semibold text-slate-600 md:col-span-2">
                    CRON（Quartz）
                    <input v-model="form.cronExpression" class="mt-1 w-full rounded border px-2 py-2 text-sm" :class="scheduleMode === 'advanced' ? 'border-amber-300 bg-white' : 'border-slate-200 bg-slate-100 text-slate-600'" :readonly="scheduleMode !== 'advanced'" type="text" />
                    <p class="mt-1 text-[11px] text-slate-500">{{ scheduleMode === "advanced" ? "進階模式可直接編輯 CRON。" : "已由上方設定自動產生。" }}</p>
                    <p class="mt-1 rounded bg-slate-100 px-2 py-1 text-[11px] text-slate-700">預覽：{{ cronPreview }}</p>
                </label>

                <div class="md:col-span-2 rounded border border-slate-200 bg-slate-50 p-3">
                    <div class="mb-2 flex flex-wrap items-center justify-between gap-2">
                        <p class="text-xs font-semibold text-slate-700">多條 CRON 規則（同一個排程）</p>
                        <div class="flex gap-2">
                            <button type="button" class="rounded border border-emerald-300 bg-emerald-50 px-2 py-1 text-xs font-semibold text-emerald-700 hover:bg-emerald-100" @click="applyTradingSessionPerSecondPreset">套用：平日 08:30-14:00 每秒（兩段）</button>
                            <button type="button" class="rounded border border-slate-300 bg-white px-2 py-1 text-xs font-semibold text-slate-700 hover:bg-slate-100" @click="addCronRule">新增目前 CRON</button>
                        </div>
                    </div>
                    <div class="space-y-2">
                        <div v-for="index in cronExpressions.length" :key="index - 1" class="flex items-center gap-2">
                            <input :value="cronExpressions[index - 1]" readonly class="w-full rounded border border-slate-300 bg-slate-100 px-2 py-1.5 text-xs text-slate-700" type="text" :placeholder="`CRON #${index}`" />
                            <button type="button" class="rounded border border-rose-300 bg-rose-50 px-2 py-1 text-xs font-semibold text-rose-700 hover:bg-rose-100" @click="removeCronRule(index - 1)">刪除</button>
                        </div>
                    </div>
                    <p class="mt-2 text-[11px] text-slate-500">既有規則不可直接編輯；若要修改請刪除後再用上方 CRON 新增。多條規則會同時生效。</p>
                </div>

                <label class="text-xs font-semibold text-slate-600 md:col-span-2">
                    股票代碼（逗號分隔）
                    <input v-model="form.symbolsText" class="mt-1 w-full rounded border border-slate-300 px-2 py-2 text-sm" type="text" />
                    <p class="mt-1 text-[11px] text-slate-500">留空表示全部股票。</p>
                </label>

                <label class="text-xs font-semibold text-slate-600 md:col-span-2">
                    每分鐘最大 API 呼叫次數
                    <input v-model.number="form.maxCallsPerMinute" class="mt-1 w-full rounded border border-slate-300 px-2 py-2 text-sm" type="number" min="0" placeholder="0（不限制）" />
                    <p class="mt-1 text-[11px] text-slate-500">設為 0 表示不限速。建議依外部 API 文件設定上限，例如 FinMind 免費方案每分鐘 60 次。</p>
                </label>

                <label class="text-xs font-semibold text-slate-600 md:col-span-2">
                    排程執行 API
                    <div class="mt-1 grid grid-cols-2 gap-2 rounded border border-slate-200 bg-slate-50 p-2 md:grid-cols-3">
                        <label v-for="option in apiOptions" :key="option.key" class="inline-flex items-center gap-2 rounded bg-white px-2 py-1 text-xs text-slate-700">
                            <input v-model="selectedApiKeys" :value="option.key" type="checkbox" />
                            {{ option.label }}
                        </label>
                    </div>
                    <p class="mt-1 text-[11px] text-slate-500">未勾選任何項目時，儲存會自動套用全部 API。</p>
                </label>
                <label class="inline-flex items-center gap-2 text-xs font-semibold text-slate-600">
                    <input v-model="form.isEnabled" type="checkbox" />
                    啟用排程
                </label>
            </div>
            <div class="mt-3 flex flex-wrap items-center gap-2">
                <button class="rounded bg-slate-900 px-3 py-2 text-xs font-semibold text-white hover:bg-slate-700" :disabled="saving" @click="save">{{ saving ? "儲存中..." : "儲存" }}</button>
                <button class="rounded border border-cyan-300 bg-cyan-50 px-3 py-2 text-xs font-semibold text-cyan-700 hover:bg-cyan-100 disabled:cursor-not-allowed disabled:border-slate-200 disabled:bg-slate-100 disabled:text-slate-400" :disabled="!isEditing || triggering" @click="triggerCurrentSchedule">{{ triggering ? "執行中..." : "手動執行一次" }}</button>
                <button class="rounded border border-amber-300 bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-700 hover:bg-amber-100 disabled:cursor-not-allowed disabled:border-slate-200 disabled:bg-slate-100 disabled:text-slate-400" :disabled="!isEditing || canceling" @click="cancelCurrentSchedule">{{ canceling ? "取消中..." : "強制取消執行中任務" }}</button>
            </div>

            <div v-if="isEditing" class="mt-6 flex flex-wrap items-center justify-between gap-2">
                <h3 class="text-base font-black text-slate-900">執行紀錄</h3>
                <div class="flex flex-wrap items-center gap-2">
                    <button type="button" class="inline-flex h-7 w-7 items-center justify-center rounded border border-slate-300 bg-white text-sm text-slate-700 hover:bg-slate-100 disabled:cursor-not-allowed disabled:border-slate-200 disabled:bg-slate-100 disabled:text-slate-400" :disabled="!selectedId || refreshingRuns" title="刷新執行紀錄" @click="manualRefreshRuns()">
                        {{ refreshingRuns ? "…" : "↻" }}
                    </button>
                    <label class="inline-flex items-center gap-1 text-xs text-slate-600">
                        <input v-model="autoRefreshRunsEnabled" type="checkbox" />
                        自動更新
                    </label>
                    <label class="inline-flex items-center gap-1 text-xs text-slate-600">
                        每
                        <input v-model.number="autoRefreshRunsSeconds" class="w-14 rounded border border-slate-300 px-1 py-0.5 text-right text-xs" type="number" min="1" />
                        秒
                    </label>
                    <span v-if="autoRefreshRunsEnabled && selectedId" class="text-xs text-cyan-700"> {{ runsRefreshCountdown }} 秒後刷新 </span>
                </div>
            </div>
            <p v-if="isEditing" class="mt-1 text-xs text-slate-500">已載入該排程全部執行紀錄，可手動刷新或啟用自動更新。</p>
            <p v-else class="mt-6 text-xs text-slate-500">建立模式不顯示執行紀錄；儲存後可於編輯模式查看。</p>
            <div v-if="isEditing" class="mt-2 overflow-hidden rounded border border-slate-200">
                <table class="w-full text-left text-xs">
                    <thead class="bg-slate-100 text-slate-700">
                        <tr>
                            <th class="px-2 py-2">開始時間</th>
                            <th class="px-2 py-2">結束時間</th>
                            <th class="px-2 py-2">狀態</th>
                            <th class="px-2 py-2">訊息</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr v-for="run in runPagination.pagedRows.value" :key="run.id" class="border-t border-slate-200">
                            <td class="px-2 py-2 text-slate-600">{{ run.startedAtUtc }}</td>
                            <td class="px-2 py-2 text-slate-600">{{ run.finishedAtUtc ?? "-" }}</td>
                            <td class="px-2 py-2" :class="run.status === 'Success' ? 'text-emerald-600' : run.status === 'Failed' ? 'text-rose-600' : run.status === 'Canceled' ? 'text-amber-600' : 'text-slate-500'">
                                {{ run.status }}
                            </td>
                            <td class="px-2 py-2 text-slate-600">{{ run.message ?? "-" }}</td>
                        </tr>
                        <tr v-if="runPagination.totalCount.value === 0">
                            <td colspan="4" class="px-2 py-3 text-center text-slate-500">尚無執行紀錄</td>
                        </tr>
                    </tbody>
                </table>
            </div>
            <div v-if="isEditing" class="mt-2">
                <TablePagination :pg="runPagination" />
            </div>
        </section>
    </div>
</template>
