<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useToast } from "vue-toastification";
import Sortable from "sortablejs";
import IndexTicker from "./components/IndexTicker.vue";
import LoginPage from "./components/LoginPage.vue";
import AdminSchedulePanel from "./components/AdminSchedulePanel.vue";
import { getToken } from "./utils/auth";
import { createApiClient } from "./shared/api/httpClient";
import { apiBaseUrl } from "./shared/config/env";
import type { GroupMember } from "./features/groups/types";
import type { StockSearchItem } from "./features/stocks/types";
import GroupSidebarPanel from "./features/groups/components/GroupSidebarPanel.vue";
import GroupMemberPanel from "./features/groups/components/GroupMemberPanel.vue";
import StockDetailPanel from "./features/stocks/components/StockDetailPanel.vue";
import { useAuthSession } from "./features/auth/composables/useAuthSession";
import { useGroupWorkspace } from "./features/groups/composables/useGroupWorkspace";
import { useStockDetails } from "./features/stocks/composables/useStockDetails";
import { createStocksApi } from "./features/stocks/api";
import { appRouteNames } from "./router";

const toast = useToast();
const router = useRouter();
const route = useRoute();
const { request } = createApiClient({ getToken });
const stocksApi = createStocksApi(request);
const { currentUser, authChecked, initializeAuthSession, logout: clearAuthSession } = useAuthSession();
const {
    groups,
    members,
    searchKeyword,
    searchResults,
    groupSearchKeyword,
    selectedGroupId,
    membersByGroup,
    memberSnapshots,
    memberSortKey,
    memberSortDir,
    newGroupName,
    newGroupDescription,
    isLoadingGroups,
    isLoadingMembers,
    isSearching,
    isShowingCreateForm,
    isSystemGroupsCollapsed,
    isSidebarCollapsed,
    editingGroupId,
    editingGroupName,
    editingGroupDescription,
    selectedGroup,
    isSelectedSystemTemplate,
    systemGroups,
    customGroups,
    groupByName,
    isCustomGroupDragDisabled,
    isMemberDragDisabled,
    filteredMembers,
    createGroup,
    addStockToGroup,
    removeStock,
    setStockInCustomGroup,
    copySelectedTemplate,
    deleteGroup,
    startRenameGroup,
    cancelRenameGroup,
    submitRenameGroup,
    handleSearchEnter,
    toggleMemberSort,
    initializeGroupWorkspace,
    resetGroupWorkspace,
    onCustomGroupsSortEnd,
    onMembersSortEnd,
} = useGroupWorkspace({ request, notify: toast });
const { selectedStock, safeDetailTab, selectedStockCode, detailContentKey, snapshot, isLoadingSnapshot, snapshotError, ticker, isLoadingTicker, tickerError, categoryGroups, isLoadingCategories, basicInfo, isLoadingBasicInfo, isAtLimitUp, isAtLimitDown, kBarData, setDetailTab, selectStock, resetStockDetails } = useStockDetails({ request });

const isSchedulePageOpen = computed(() => route.name === appRouteNames.adminSchedules);

// ─── Header 全域快速搜尋狀態 ──────────────────────────────────
const quickSearchKeyword = ref("");
const quickSearchResults = ref<StockSearchItem[]>([]);
const isQuickSearching = ref(false);
const showQuickSearchDropdown = ref(false);
const quickSearchFocused = ref(false);
type MobileSearchOverlayKind = "quick" | "group" | "member" | null;
const activeMobileSearchOverlay = ref<MobileSearchOverlayKind>(null);
let quickSearchTimer: number | undefined;
/** 搜尋輸入框的 DOM ref，用於計算下拉定位。 */
const quickSearchInputRef = ref<HTMLInputElement | null>(null);
/** 下拉選單的 fixed 定位樣式。 */
const dropdownStyle = ref({ top: "0px", left: "0px", width: "0px" });
const isMobileView = ref(false);
const isMobileHeaderCollapsed = ref(false);
type MobileSectionKey = "groups" | "members" | "detail";
type GroupSidebarPanelExpose = {
    getMobileGroupSectionEl: () => HTMLElement | null;
    getCustomGroupsListEl: () => HTMLElement | null;
};
type GroupMemberPanelExpose = {
    getMobileMemberSectionEl: () => HTMLElement | null;
    getMembersListEl: () => HTMLElement | null;
};
type StockDetailPanelExpose = {
    getMobileDetailSectionEl: () => HTMLElement | null;
    getDetailScrollTop: () => number;
    setDetailScrollTop: (value: number) => void;
};
const activeMobileSection = ref<MobileSectionKey>("groups");
const appLayoutRef = ref<HTMLElement | null>(null);
const groupSidebarPanelRef = ref<GroupSidebarPanelExpose | null>(null);
const groupMemberPanelRef = ref<GroupMemberPanelExpose | null>(null);
const stockDetailPanelRef = ref<StockDetailPanelExpose | null>(null);
let mobileNavSyncTimer: number | undefined;

function getMobileSectionLeft(section: MobileSectionKey): number {
    let target: HTMLElement | null;
    if (section === "groups") {
        target = groupSidebarPanelRef.value?.getMobileGroupSectionEl() ?? null;
    } else if (section === "members") {
        target = groupMemberPanelRef.value?.getMobileMemberSectionEl() ?? null;
    } else {
        target = stockDetailPanelRef.value?.getMobileDetailSectionEl() ?? null;
    }

    return target?.offsetLeft ?? 0;
}

/** 同步目前視窗是否為手機寬度，並避免手機版側欄被收合到不可操作。 */
function syncMobileViewState() {
    const previous = isMobileView.value;
    const isMobile = globalThis.innerWidth <= 1024;
    isMobileView.value = isMobile;
    if (isMobile && !previous) {
        isMobileHeaderCollapsed.value = true;
    }
    if (!isMobile) {
        isMobileHeaderCollapsed.value = false;
    }
    if (isMobile && isSidebarCollapsed.value) {
        isSidebarCollapsed.value = false;
    }
    if (previous !== isMobile) {
        void syncSortables();
    }
}

/** 手機版 Header 展開/收合切換。 */
function toggleMobileHeader() {
    isMobileHeaderCollapsed.value = !isMobileHeaderCollapsed.value;
}

/** 手機快速查詢：開啟全螢幕搜尋覆蓋層。 */
function openMobileSearchOverlay(kind: Exclude<MobileSearchOverlayKind, null>) {
    if (!isMobileView.value) return;
    activeMobileSearchOverlay.value = kind;
    showQuickSearchDropdown.value = kind === "quick";
}

/** 手機快速查詢：關閉全螢幕搜尋覆蓋層。 */
function closeMobileSearchOverlay() {
    activeMobileSearchOverlay.value = null;
    showQuickSearchDropdown.value = false;
}

/** 手機群組查詢覆蓋層點選群組後：關閉覆蓋層並切到第二頁。 */
function selectGroupFromMobileOverlay(groupId: string) {
    closeMobileSearchOverlay();
    selectGroup(groupId);
}

/** 手機第二頁搜尋覆蓋層：加入股票後關閉覆蓋層回到第二頁。 */
async function addStockFromMobileOverlay(stockCode: string) {
    await addStockToGroup(stockCode);
    closeMobileSearchOverlay();
    switchMobileSection("members");
}

/** 手機版點擊快捷按鈕時，平滑切換到指定模組區塊。 */
function switchMobileSection(section: MobileSectionKey) {
    activeMobileSection.value = section;
    if (!isMobileView.value || !appLayoutRef.value) {
        return;
    }

    const left = getMobileSectionLeft(section);
    appLayoutRef.value.scrollTo({ left, behavior: "smooth" });

    if (mobileNavSyncTimer !== undefined) {
        globalThis.clearTimeout(mobileNavSyncTimer);
    }
    mobileNavSyncTimer = globalThis.setTimeout(() => {
        activeMobileSection.value = section;
    }, 260);
}

/** 手機版橫向滑動時，同步目前所在模組給快捷按鈕高亮。 */
function onAppLayoutScroll() {
    if (!isMobileView.value || !appLayoutRef.value) {
        return;
    }

    const currentLeft = appLayoutRef.value.scrollLeft;
    const entries: Array<{ key: MobileSectionKey; left: number }> = [
        { key: "groups", left: getMobileSectionLeft("groups") },
        { key: "members", left: getMobileSectionLeft("members") },
        { key: "detail", left: getMobileSectionLeft("detail") },
    ];

    let closest = entries[0];
    let minDistance = Math.abs(currentLeft - entries[0].left);
    for (let index = 1; index < entries.length; index++) {
        const distance = Math.abs(currentLeft - entries[index].left);
        if (distance < minDistance) {
            minDistance = distance;
            closest = entries[index];
        }
    }

    activeMobileSection.value = closest.key;
}

/** 計算並更新全域搜尋下拉選單的畫面定位（fixed 定位，依損入框 getBoundingClientRect 計算）。 */
function updateDropdownPos() {
    const el = quickSearchInputRef.value;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    dropdownStyle.value = {
        top: `${rect.bottom + 4}px`,
        left: `${rect.left}px`,
        width: `${rect.width}px`,
    };
}

// ─── 拖放排序狀態（SortableJS）─────────────────────────────────
/** 自訂群組排序實例。 */
let customGroupsSortable: Sortable | null = null;
/** 群組成員排序實例。 */
let membersSortable: Sortable | null = null;

// ─── 計算屬性 ─────────────────────────────────────────────────
const isAdmin = computed(() => currentUser.value?.isAdmin ?? false);

/** 當前已選股票所屬的自訂群組清單（用於分類資訊顯示）。 */
const stockInCustomGroups = computed(() => {
    const code = selectedStock.value?.stockCode;
    if (!code || customGroups.value.length === 0) return [];
    // 由 membersByGroup map 查找，若無快取則從 members (當前群組) 推斷
    return customGroups.value.filter((g) => membersByGroup.value.get(g.id)?.has(code));
});

/** 初始化或更新「自訂群組」的 Sortable 設定。 */
function initOrUpdateCustomGroupsSortable() {
    const customGroupsListEl = groupSidebarPanelRef.value?.getCustomGroupsListEl();
    if (!customGroupsListEl) return;
    const dragDelayMs = isMobileView.value ? 400 : 0;
    const useMobileFallback = isMobileView.value;
    if (!customGroupsSortable) {
        customGroupsSortable = Sortable.create(customGroupsListEl, {
            handle: ".cursor-grab",
            animation: 150,
            delay: dragDelayMs,
            delayOnTouchOnly: true,
            touchStartThreshold: 8,
            forceFallback: useMobileFallback,
            fallbackOnBody: useMobileFallback,
            fallbackTolerance: 6,
            ghostClass: "ghost",
            chosenClass: "sortable-chosen",
            dragClass: "sortable-drag",
            disabled: isCustomGroupDragDisabled.value,
            onEnd: (evt) => {
                if (evt.oldIndex == null || evt.newIndex == null) return;
                void onCustomGroupsSortEnd(evt.oldIndex, evt.newIndex);
            },
        });
        return;
    }
    customGroupsSortable.option("disabled", isCustomGroupDragDisabled.value);
    customGroupsSortable.option("delay", dragDelayMs);
    customGroupsSortable.option("forceFallback", useMobileFallback);
    customGroupsSortable.option("fallbackOnBody", useMobileFallback);
}

/** 初始化或更新「群組成員」的 Sortable 設定。 */
function initOrUpdateMembersSortable() {
    const membersListEl = groupMemberPanelRef.value?.getMembersListEl();
    if (!membersListEl) return;
    const dragDelayMs = isMobileView.value ? 400 : 0;
    const useMobileFallback = isMobileView.value;
    if (!membersSortable) {
        membersSortable = Sortable.create(membersListEl, {
            handle: ".cursor-grab",
            animation: 150,
            delay: dragDelayMs,
            delayOnTouchOnly: true,
            touchStartThreshold: 8,
            forceFallback: useMobileFallback,
            fallbackOnBody: useMobileFallback,
            fallbackTolerance: 6,
            ghostClass: "ghost",
            chosenClass: "sortable-chosen",
            dragClass: "sortable-drag",
            disabled: isMemberDragDisabled.value,
            onEnd: (evt) => {
                if (evt.oldIndex == null || evt.newIndex == null) return;
                void onMembersSortEnd(evt.oldIndex, evt.newIndex);
            },
        });
        return;
    }
    membersSortable.option("disabled", isMemberDragDisabled.value);
    membersSortable.option("delay", dragDelayMs);
    membersSortable.option("forceFallback", useMobileFallback);
    membersSortable.option("fallbackOnBody", useMobileFallback);
}

/**
 * 等待 DOM 完成更新後同步 Sortable 狀態。
 * 用於切頁、收合、資料重刷後重新綁定/更新 disabled。
 */
async function syncSortables() {
    await nextTick();
    initOrUpdateCustomGroupsSortable();
    initOrUpdateMembersSortable();
}

// ─── 監聽器 ───────────────────────────────────────────────────

// 全域快速搜尋防抖（200ms）
watch(quickSearchKeyword, (keyword) => {
    if (quickSearchTimer) globalThis.clearTimeout(quickSearchTimer);
    const trimmed = keyword.trim();
    if (!trimmed) {
        quickSearchResults.value = [];
        showQuickSearchDropdown.value = false;
        return;
    }
    quickSearchTimer = globalThis.setTimeout(async () => {
        isQuickSearching.value = true;
        try {
            quickSearchResults.value = await stocksApi.searchStocks(trimmed, 10);
            if (quickSearchResults.value.length > 0) {
                updateDropdownPos();
                showQuickSearchDropdown.value = true;
            } else {
                showQuickSearchDropdown.value = false;
            }
        } finally {
            isQuickSearching.value = false;
        }
    }, 200);
});

/** 從全域搜尋下拉選取一筆股票，將其設為已選股票並清空搜尋狀態。 */
function selectQuickSearchResult(item: StockSearchItem) {
    const previousScrollTop = stockDetailPanelRef.value?.getDetailScrollTop() ?? 0;
    selectStock({ stockCode: item.stockCode, stockName: item.stockName });
    void nextTick(() => {
        stockDetailPanelRef.value?.setDetailScrollTop(previousScrollTop);
    });
    quickSearchKeyword.value = "";
    quickSearchResults.value = [];
    showQuickSearchDropdown.value = false;
    closeMobileSearchOverlay();
    if (isMobileView.value) {
        switchMobileSection("detail");
    }
}

/** 全域搜尋框按下 Enter 時自動選取第一筆搜尋結果。 */
function onQuickSearchEnter() {
    const first = quickSearchResults.value[0];
    if (first) {
        selectQuickSearchResult(first);
    }
}

/** 全域搜尋框失焦時，延遲 150ms 後關閉下拉（不能立即關閉，否則點擊下拉項目的 click 事件會被消滅）。 */
function onQuickSearchBlur() {
    // 延遲關閉，讓點擊下拉項目的事件能先觸發
    globalThis.setTimeout(() => {
        showQuickSearchDropdown.value = false;
        quickSearchFocused.value = false;
    }, 150);
}

watch([isCustomGroupDragDisabled, isMemberDragDisabled], () => {
    void syncSortables();
});

watch([isSidebarCollapsed, isSchedulePageOpen, customGroups, filteredMembers], () => {
    void syncSortables();
});

onUnmounted(() => {
    customGroupsSortable?.destroy();
    membersSortable?.destroy();
    customGroupsSortable = null;
    membersSortable = null;
    if (mobileNavSyncTimer !== undefined) {
        globalThis.clearTimeout(mobileNavSyncTimer);
        mobileNavSyncTimer = undefined;
    }
    globalThis.removeEventListener("resize", syncMobileViewState);
    globalThis.removeEventListener("resize", updateDropdownPos);
});

onMounted(async () => {
    syncMobileViewState();
    globalThis.addEventListener("resize", syncMobileViewState);
    globalThis.addEventListener("resize", updateDropdownPos);

    const user = initializeAuthSession();
    if (!user) {
        return;
    }

    try {
        await initializeGroupWorkspace();
        await syncSortables();
    } catch (error) {
        toast.error(error instanceof Error ? error.message : "初始化失敗");
    }
});

/** 登出：清除 Token、清空狀態、停止輪詢並導向首頁。 */
function logout() {
    clearAuthSession();
    navigateToMainPage();
    resetGroupWorkspace();
    resetStockDetails();
}

/** 導向排程管理頁面。 */
function navigateToSchedulePage() {
    if (isSchedulePageOpen.value) {
        return;
    }

    router.push({ name: appRouteNames.adminSchedules });
}

/** 回到主頁面。 */
function navigateToMainPage() {
    if (route.name === appRouteNames.watchlist) {
        return;
    }

    router.push({ name: appRouteNames.watchlist });
}

/** 切換排程管理頁面與主頁面。 */
function toggleSchedulePage() {
    if (isSchedulePageOpen.value) {
        navigateToMainPage();
        return;
    }

    navigateToSchedulePage();
}

/**
 * 選取群組；手機版會自動切到股票搜尋與群組成員區塊。
 */
function selectGroup(groupId: string) {
    selectedGroupId.value = groupId;
    if (isMobileView.value) {
        switchMobileSection("members");
    }
}

/** 從右側分類資訊切換群組：桌機展開側欄、手機切到第二頁（成員頁）。 */
function selectGroupFromCategory(groupId: string) {
    selectGroup(groupId);
    if (!isMobileView.value) {
        isSidebarCollapsed.value = false;
    }
}

/** 從右側星號下拉快速加入/移除指定自訂群組。 */
async function onToggleCustomGroupMembership(payload: { groupId: string; stockCode: string; shouldInclude: boolean }) {
    await setStockInCustomGroup(payload.groupId, payload.stockCode, payload.shouldInclude);
}

/**
 * 選取群組成員股票，明確設定 selectedStock.value。
 */
function selectMember(member: GroupMember) {
    const previousScrollTop = stockDetailPanelRef.value?.getDetailScrollTop() ?? 0;
    selectStock(member);
    void nextTick(() => {
        stockDetailPanelRef.value?.setDetailScrollTop(previousScrollTop);
    });
    if (isMobileView.value) {
        switchMobileSection("detail");
    }
}
</script>

<template>
    <LoginPage v-if="authChecked && !currentUser" />
    <main v-else-if="authChecked && currentUser" class="min-h-screen bg-gradient-to-br from-slate-50 via-cyan-50 to-blue-50 text-slate-800">
        <header class="border-b border-slate-200 bg-white/95 p-2 backdrop-blur">
            <div class="mx-auto max-w-full px-4">
                <div class="mobile-header-toggle">
                    <button type="button" class="mobile-header-logout-button" @click="logout" aria-label="登出">登出</button>
                    <button type="button" class="mobile-header-toggle-button" @click="toggleMobileHeader" :aria-expanded="!isMobileHeaderCollapsed" aria-controls="mobile-header-collapsible" :aria-label="isMobileHeaderCollapsed ? '展開 Header' : '收合 Header'">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" class="h-4 w-4" :class="isMobileHeaderCollapsed ? '' : 'rotate-180'">
                            <path fill-rule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.51a.75.75 0 01-1.08 0l-4.25-4.51a.75.75 0 01.02-1.06z" clip-rule="evenodd" />
                        </svg>
                        <span>{{ isMobileHeaderCollapsed ? "展開" : "收合" }}</span>
                    </button>
                </div>

                <div v-if="isMobileView && isMobileHeaderCollapsed && !isSchedulePageOpen" class="mobile-header-compact-row">
                    <div class="mobile-header-compact-search relative">
                        <svg class="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                            <path fill-rule="evenodd" d="M9 3.5a5.5 5.5 0 100 11 5.5 5.5 0 000-11zM2 9a7 7 0 1112.452 4.391l3.328 3.329a.75.75 0 11-1.06 1.06l-3.329-3.328A7 7 0 012 9z" clip-rule="evenodd" />
                        </svg>
                        <input
                            id="quick-search-compact"
                            ref="quickSearchInputRef"
                            v-model="quickSearchKeyword"
                            @focus="
                                quickSearchFocused = true;
                                updateDropdownPos();
                                if (quickSearchResults.length > 0) showQuickSearchDropdown = true;
                            "
                            @blur="onQuickSearchBlur"
                            @keydown.enter.prevent="onQuickSearchEnter"
                            @keydown.escape="
                                quickSearchKeyword = '';
                                showQuickSearchDropdown = false;
                            "
                            @click="openMobileSearchOverlay('quick')"
                            type="text"
                            placeholder="快速查詢股票"
                            autocomplete="off"
                            class="mobile-search-input w-full rounded-xl border border-slate-300 bg-slate-50 py-2 pl-9 pr-8 text-sm text-slate-800 outline-none transition focus:border-cyan-500 focus:bg-white focus:ring-2 focus:ring-cyan-200"
                        />
                        <button
                            v-if="quickSearchKeyword"
                            type="button"
                            @click="
                                quickSearchKeyword = '';
                                showQuickSearchDropdown = false;
                            "
                            class="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                            tabindex="-1"
                            aria-label="清除搜尋"
                        >
                            ✕
                        </button>
                        <span v-else-if="isQuickSearching" class="absolute right-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 animate-spin rounded-full border-2 border-cyan-400 border-t-transparent"></span>

                        <Teleport to="body">
                            <ul v-if="activeMobileSearchOverlay !== 'quick' && showQuickSearchDropdown && quickSearchResults.length > 0" :style="{ position: 'fixed', top: dropdownStyle.top, left: dropdownStyle.left, width: dropdownStyle.width, zIndex: 9999 }" class="quick-search-dropdown rounded-xl border border-slate-200 bg-white shadow-2xl overflow-hidden">
                                <li v-for="(item, idx) in quickSearchResults" :key="`compact-${item.stockCode}`" @mousedown.prevent="selectQuickSearchResult(item)" class="flex cursor-pointer items-center gap-3 px-4 py-2.5 hover:bg-cyan-50 transition" :class="{ 'bg-cyan-50': idx === 0 }">
                                    <span class="qs-code w-14 shrink-0 rounded-md bg-slate-100 px-1.5 py-0.5 text-center text-xs font-bold tabular-nums text-slate-700">{{ item.stockCode }}</span>
                                    <span class="qs-name flex-1 text-sm font-medium text-slate-800">{{ item.stockName }}</span>
                                    <span v-if="item.categories.length > 0" class="qs-cat max-w-32 truncate text-xs text-slate-400">{{ item.categories[0]?.split(":")[1] }}</span>
                                    <span v-if="idx === 0" class="qs-enter shrink-0 rounded bg-cyan-100 px-1 py-0.5 text-[10px] font-semibold text-cyan-600">Enter</span>
                                </li>
                            </ul>
                        </Teleport>
                    </div>

                    <div class="mobile-module-switch mobile-module-switch-compact">
                        <button type="button" class="mobile-module-button" :class="activeMobileSection === 'groups' ? 'mobile-module-button-active' : ''" @click="switchMobileSection('groups')" aria-label="切換到群組">
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" class="h-3.5 w-3.5">
                                <path d="M3 4a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm0 6a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm1 5a1 1 0 100 2h12a1 1 0 100-2H4z" />
                            </svg>
                            <span>群組</span>
                        </button>
                        <button type="button" class="mobile-module-button" :class="activeMobileSection === 'members' ? 'mobile-module-button-active' : ''" @click="switchMobileSection('members')" aria-label="切換到股票搜尋與群組成員">
                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" class="h-3.5 w-3.5">
                                <path fill-rule="evenodd" d="M9 3.5a5.5 5.5 0 100 11 5.5 5.5 0 000-11zM2 9a7 7 0 1112.452 4.391l3.328 3.329a.75.75 0 11-1.06 1.06l-3.329-3.328A7 7 0 012 9z" clip-rule="evenodd" />
                            </svg>
                            <span>股票</span>
                        </button>
                        <button type="button" class="mobile-module-button" :class="activeMobileSection === 'detail' ? 'mobile-module-button-active' : ''" @click="switchMobileSection('detail')" aria-label="切換到右側資訊">
