<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from "vue";
import StockCandleChart from "../../../components/StockCandleChart.vue";
import StockRevenueChart from "../../../components/StockRevenueChart.vue";
import StockInstitutionalChart from "../../../components/StockInstitutionalChart.vue";
import type { GroupMember, StockGroup } from "../../groups/types";
import type { BasicInfo, IntradayTicker, SnapshotItem, StockCategoryGroup } from "../types";
import type { DetailTabKey, KBarData } from "../utils/stockUtils";
import { formatTradeValue } from "../utils/stockUtils";

const props = defineProps<{
    selectedStock: GroupMember | null;
    ticker: IntradayTicker | null;
    isLoadingSnapshot: boolean;
    snapshot: SnapshotItem | null;
    snapshotError: string | null;
    basicInfo: BasicInfo | null;
    isLoadingBasicInfo: boolean;
    isAtLimitUp: boolean;
    isAtLimitDown: boolean;
    kBarData: KBarData | null;
    safeDetailTab: DetailTabKey;
    detailContentKey: string;
    isLoadingTicker: boolean;
    tickerError: string | null;
    categoryGroups: StockCategoryGroup[];
    isLoadingCategories: boolean;
    groupByName: Map<string, StockGroup>;
    selectedGroupId: string;
    customGroups: StockGroup[];
    stockInCustomGroups: StockGroup[];
    apiBaseUrl: string;
    getToken: () => string | null;
}>();

const emit = defineEmits<{
    "set-detail-tab": [tab: DetailTabKey];
    "select-group-from-category": [groupId: string];
    "toggle-custom-group-membership": [payload: { groupId: string; stockCode: string; shouldInclude: boolean }];
}>();

const mobileDetailSectionEl = ref<HTMLElement | null>(null);
const quickGroupMenuEl = ref<HTMLElement | null>(null);
const isQuickGroupMenuOpen = ref(false);

const customGroupIdSet = computed(() => new Set(props.stockInCustomGroups.map((group) => group.id)));
const hasAnyCustomGroupMembership = computed(() => {
    // console.log('Checking membership for:', props.selectedStock?.stockCode, 'Groups count:', props.stockInCustomGroups.length);
    return props.stockInCustomGroups.length > 0;
});

/**
 * 切換股票時保留右側資訊面板捲動位置。
 * 讓群組成員點選與快速查詢選股維持一致體驗。
 */
watch(
    () => props.selectedStock?.stockCode,
    async (nextCode, prevCode) => {
        isQuickGroupMenuOpen.value = false;

        const panel = mobileDetailSectionEl.value;
        if (!panel || !nextCode || !prevCode || nextCode === prevCode) {
            return;
        }

        const previousScrollTop = panel.scrollTop;
        await nextTick();
        if (mobileDetailSectionEl.value) {
            mobileDetailSectionEl.value.scrollTop = previousScrollTop;
        }
    },
);

function isInCustomGroup(groupId: string): boolean {
    return customGroupIdSet.value.has(groupId);
}

function toggleQuickGroupMenu(): void {
    isQuickGroupMenuOpen.value = !isQuickGroupMenuOpen.value;
}

function onClickOutsideQuickGroupMenu(event: MouseEvent): void {
    if (!isQuickGroupMenuOpen.value) {
        return;
    }

    const root = quickGroupMenuEl.value;
    const target = event.target;
    if (!root || !(target instanceof Node)) {
        return;
    }

    if (!root.contains(target)) {
        isQuickGroupMenuOpen.value = false;
    }
}

function onToggleCustomGroup(groupId: string, checked: boolean): void {
    const stockCode = props.selectedStock?.stockCode;
    if (!stockCode) {
        return;
    }

    emit("toggle-custom-group-membership", {
        groupId,
        stockCode,
        shouldInclude: checked,
    });
}

function onCustomGroupInputChange(groupId: string, event: Event): void {
    const target = event.target;
    if (!(target instanceof HTMLInputElement)) {
        return;
    }

    onToggleCustomGroup(groupId, target.checked);
}

onMounted(() => {
    document.addEventListener("click", onClickOutsideQuickGroupMenu);
});

onUnmounted(() => {
    document.removeEventListener("click", onClickOutsideQuickGroupMenu);
});

/** 回傳資訊面板 DOM 節點，供父層進行手機滑動定位。 */
function getMobileDetailSectionEl(): HTMLElement | null {
    return mobileDetailSectionEl.value;
}

/** 取得右側資訊面板目前捲動位置。 */
function getDetailScrollTop(): number {
    return mobileDetailSectionEl.value?.scrollTop ?? 0;
}

/** 設定右側資訊面板捲動位置。 */
function setDetailScrollTop(value: number): void {
    if (!mobileDetailSectionEl.value) return;
    mobileDetailSectionEl.value.scrollTop = value;
}

/** 解析分類名稱對應的群組 ID。 */
function getLinkedGroupId(categoryType: string, name: string): string | null {
    return props.groupByName.get(`${categoryType} - ${name}`)?.id ?? null;
}

/** 判斷目前分類是否已連到可切換的群組。 */
function hasLinkedGroup(categoryType: string, name: string): boolean {
    return getLinkedGroupId(categoryType, name) !== null;
}

/** 將上市日期的 yyyyMMdd 格式轉成 yyyy/MM/dd。 */
function formatListingDate(value: string | null): string {
    if (!value || value.length !== 8) {
        return "—";
    }

    return `${value.substring(0, 4)}/${value.substring(4, 6)}/${value.substring(6, 8)}`;
}

/** 將證券狀態代碼轉成可讀文字。 */
function formatSecurityStatus(value: string | null): string {
    if (value === "NORMAL") {
        return "正常";
    }
    if (value === "SUSPENDED") {
        return "暫停";
    }
    if (value === "TERMINATED") {
        return "終止";
    }
    return value ?? "—";
}

defineExpose({
    getMobileDetailSectionEl,
    getDetailScrollTop,
    setDetailScrollTop,
});
</script>

