                            <div v-else-if="props.tickerError" class="rounded-lg bg-rose-50 border border-rose-200 p-3 text-base text-rose-700">{{ props.tickerError }}</div>

                            <template v-else-if="props.ticker">
                                <div class="grid grid-cols-3 gap-1.5 mb-3">
                                    <div class="rounded-lg px-2 py-2.5 text-center transition-all" :class="props.isAtLimitUp ? 'bg-rose-600 ring-2 ring-rose-400 shadow-lg shadow-rose-200' : 'bg-rose-50'">
                                        <p class="text-[11px] font-medium" :class="props.isAtLimitUp ? 'text-rose-100' : 'text-rose-500'">漲停價</p>
                                        <p class="mt-0.5 text-base font-black tabular-nums" :class="props.isAtLimitUp ? 'text-white' : 'text-rose-700'">{{ props.ticker.limitUpPrice?.toFixed(2) ?? "—" }}</p>
                                        <p v-if="props.isAtLimitUp" class="mt-0.5 text-[10px] font-bold text-rose-200 animate-pulse">▲ 已觸及</p>
                                    </div>
                                    <div class="rounded-lg bg-slate-50 px-2 py-2.5 text-center">
                                        <p class="text-[11px] text-slate-500 font-medium">參考價</p>
                                        <p class="mt-0.5 text-base font-black tabular-nums text-slate-800">{{ props.ticker.referencePrice?.toFixed(2) ?? "—" }}</p>
                                    </div>
                                    <div class="rounded-lg px-2 py-2.5 text-center transition-all" :class="props.isAtLimitDown ? 'bg-emerald-600 ring-2 ring-emerald-400 shadow-lg shadow-emerald-200' : 'bg-emerald-50'">
                                        <p class="text-[11px] font-medium" :class="props.isAtLimitDown ? 'text-emerald-100' : 'text-emerald-600'">跌停價</p>
                                        <p class="mt-0.5 text-base font-black tabular-nums" :class="props.isAtLimitDown ? 'text-white' : 'text-emerald-700'">{{ props.ticker.limitDownPrice?.toFixed(2) ?? "—" }}</p>
                                        <p v-if="props.isAtLimitDown" class="mt-0.5 text-[10px] font-bold text-emerald-200 animate-pulse">▼ 已觸及</p>
                                    </div>
                                </div>

                                <div class="grid grid-cols-3 gap-1.5 mb-3">
                                    <div class="rounded-lg bg-slate-50 px-2 py-2">
                                        <p class="text-[11px] text-slate-500 font-medium">前日收盤</p>
                                        <p class="mt-0.5 text-base font-black tabular-nums text-slate-800">{{ props.ticker.previousClose?.toFixed(2) ?? "—" }}</p>
                                    </div>
                                    <div class="rounded-lg bg-slate-50 px-2 py-2">
                                        <p class="text-[11px] text-slate-500 font-medium">交易單位</p>
                                        <p class="mt-0.5 text-base font-black tabular-nums text-slate-800">{{ props.ticker.boardLot?.toLocaleString() ?? "—" }}</p>
                                    </div>
                                    <div class="rounded-lg bg-slate-50 px-2 py-2">
                                        <p class="text-[11px] text-slate-500 font-medium">交易所</p>
                                        <p class="mt-0.5 text-sm font-black text-slate-800">
                                            {{ props.ticker.exchange ?? "—" }}<span v-if="props.ticker.market" class="text-slate-400">/ {{ props.ticker.market }}</span>
                                        </p>
                                    </div>
                                    <div class="rounded-lg bg-slate-50 px-2 py-2">
                                        <p class="text-[11px] text-slate-500 font-medium">交易幣別</p>
                                        <p class="mt-0.5 text-base font-black text-slate-800">{{ props.ticker.tradingCurrency ?? "—" }}</p>
                                    </div>
                                    <div class="rounded-lg bg-slate-50 px-2 py-2">
                                        <p class="text-[11px] text-slate-500 font-medium">撮合循環(秒)</p>
                                        <p class="mt-0.5 text-base font-black tabular-nums text-slate-800">{{ props.ticker.matchingInterval ?? "—" }}</p>
                                    </div>
                                    <div class="rounded-lg px-2 py-2" :class="props.ticker.securityStatus === 'NORMAL' ? 'bg-emerald-50' : 'bg-amber-50'">
                                        <p class="text-[11px] font-medium" :class="props.ticker.securityStatus === 'NORMAL' ? 'text-emerald-600' : 'text-amber-600'">證券狀態</p>
                                        <p class="mt-0.5 text-sm font-black" :class="props.ticker.securityStatus === 'NORMAL' ? 'text-emerald-700' : 'text-amber-700'">{{ formatSecurityStatus(props.ticker.securityStatus) }}</p>
                                    </div>
                                </div>
                                <p class="mt-2 text-right text-sm text-slate-400">資料日期：{{ props.ticker.date }}</p>
                            </template>

                            <div v-else-if="!props.isLoadingTicker" class="text-base text-slate-400">—</div>
                        </div>

                        <div class="mt-4 border-t border-slate-100 pt-3">
                            <p class="mb-2 text-sm font-bold uppercase tracking-widest text-slate-400">分類資訊</p>
                            <div v-if="props.isLoadingCategories" class="text-sm text-slate-400">載入中...</div>
                            <template v-else>
                                <template v-if="props.categoryGroups.length > 0">
                                    <div v-for="group in props.categoryGroups" :key="group.categoryType" class="mb-3">
                                        <p class="mb-1.5 text-sm font-bold uppercase tracking-wide text-slate-500">{{ group.categoryType }}</p>
                                        <div class="flex flex-wrap gap-1.5">
                                            <button
                                                v-for="name in group.names"
                                                :key="name"
                                                @click="hasLinkedGroup(group.categoryType, name) && emit('select-group-from-category', getLinkedGroupId(group.categoryType, name)!)"
                                                class="rounded-full px-2.5 py-1 text-sm font-semibold transition"
                                                :class="
                                                    hasLinkedGroup(group.categoryType, name)
                                                        ? props.selectedGroupId === getLinkedGroupId(group.categoryType, name)
                                                            ? group.categoryType === '概念'
                                                                ? 'bg-cyan-500 text-white shadow-sm'
                                                                : group.categoryType === '集團'
                                                                  ? 'bg-violet-500 text-white shadow-sm'
                                                                  : group.categoryType === '產業'
                                                                    ? 'bg-amber-500 text-white shadow-sm'
                                                                    : 'bg-slate-500 text-white shadow-sm'
                                                            : group.categoryType === '概念'
                                                              ? 'bg-cyan-100 text-cyan-800 hover:bg-cyan-200 cursor-pointer'
                                                              : group.categoryType === '集團'
                                                                ? 'bg-violet-100 text-violet-800 hover:bg-violet-200 cursor-pointer'
                                                                : group.categoryType === '產業'
                                                                  ? 'bg-amber-100 text-amber-800 hover:bg-amber-200 cursor-pointer'
                                                                  : 'bg-slate-100 text-slate-700 hover:bg-slate-200 cursor-pointer'
                                                        : group.categoryType === '概念'
                                                          ? 'bg-cyan-100 text-cyan-800 cursor-default'
                                                          : group.categoryType === '集團'
                                                            ? 'bg-violet-100 text-violet-800 cursor-default'
                                                            : group.categoryType === '產業'
                                                              ? 'bg-amber-100 text-amber-800 cursor-default'
                                                              : 'bg-slate-100 text-slate-700 cursor-default'
                                                "
                                                :title="hasLinkedGroup(group.categoryType, name) ? `切換至群組：${group.categoryType} - ${name}` : name"
                                            >
                                                {{ name }}
                                            </button>
                                        </div>
                                    </div>
                                </template>
                                <div v-else class="mb-3 text-base text-slate-400">無分類資料</div>

                                <div v-if="props.stockInCustomGroups.length > 0" class="mb-1">
                                    <p class="mb-1.5 text-sm font-bold uppercase tracking-wide text-slate-500">自訂群組</p>
                                    <div class="flex flex-wrap gap-1.5">
                                        <button v-for="group in props.stockInCustomGroups" :key="group.id" @click="emit('select-group-from-category', group.id)" class="rounded-full px-2.5 py-1 text-sm font-semibold transition" :class="props.selectedGroupId === group.id ? 'bg-amber-500 text-white shadow-sm' : 'bg-amber-100 text-amber-800 hover:bg-amber-200'" :title="`切換至群組：${group.name}`">
                                            {{ group.name }}
                                        </button>
                                    </div>
                                </div>
                            </template>
                        </div>
                    </template>

                    <div v-else-if="props.safeDetailTab === 'history'" class="mt-4 border-t border-slate-100 pt-3">
                        <p class="mb-2 text-sm font-bold uppercase tracking-widest text-slate-400">歷史行情</p>
                        <StockCandleChart :stockCode="props.selectedStock.stockCode" :stockName="props.selectedStock.stockName" :apiBaseUrl="props.apiBaseUrl" :getToken="props.getToken" :snapshot="props.snapshot" />
                    </div>

                    <div v-else-if="props.safeDetailTab === 'revenue'" class="mt-4 border-t border-slate-100 pt-3">
                        <p class="mb-2 text-sm font-bold uppercase tracking-widest text-slate-400">月營收</p>
                        <StockRevenueChart :stockCode="props.selectedStock.stockCode" :apiBaseUrl="props.apiBaseUrl" :getToken="props.getToken" />
                    </div>

                    <div v-else-if="props.safeDetailTab === 'institutional'" class="mt-4 border-t border-slate-100 pt-3">
                        <p class="mb-2 text-sm font-bold uppercase tracking-widest text-slate-400">三大法人買賣超</p>
                        <StockInstitutionalChart :stockCode="props.selectedStock.stockCode" :apiBaseUrl="props.apiBaseUrl" :getToken="props.getToken" />
                    </div>
                </div>
            </article>
            <article v-else class="rounded-2xl border border-slate-200 bg-white/90 p-4 shadow-lg text-center">
                <p class="text-slate-500">請從左邊選擇群組成員中的股票</p>
            </article>
        </div>
    </section>
</template>
