<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import * as echarts from "echarts/core";
import { BarChart } from "echarts/charts";
import { GridComponent, TooltipComponent, LegendComponent, DataZoomComponent } from "echarts/components";
import { CanvasRenderer } from "echarts/renderers";
import { usePagination } from "../composables/usePagination";
import TablePagination from "./TablePagination.vue";

echarts.use([TooltipComponent, GridComponent, LegendComponent, DataZoomComponent, BarChart, CanvasRenderer]);

// ─── 型別定義 ─────────────────────────────────────────────────

type InstitutionalRow = {
    date: string;
    foreignInvestorNet: number;
    foreignDealerSelfNet: number;
    investmentTrustNet: number;
    dealerSelfNet: number;
    dealerHedgingNet: number;
    totalNet: number;
};

// ─── Props ────────────────────────────────────────────────────

const props = defineProps<{
    stockCode: string;
    apiBaseUrl: string;
    getToken: () => string | null;
}>();

// ─── 狀態 ─────────────────────────────────────────────────────

const rawData = ref<InstitutionalRow[]>([]);
const loading = ref(false);
const errorMsg = ref<string | null>(null);
const chartContainer = ref<HTMLDivElement | null>(null);
let chartInstance: echarts.ECharts | null = null;
const MOBILE_BREAKPOINT = 1024;
const isMobileView = ref(false);

// 系列設定
const SERIES = [
    { key: "foreignInvestorNet" as keyof InstitutionalRow, label: "外資", color: "#2563eb" },
    { key: "foreignDealerSelfNet" as keyof InstitutionalRow, label: "外資自營", color: "#60a5fa" },
    { key: "investmentTrustNet" as keyof InstitutionalRow, label: "投信", color: "#16a34a" },
    { key: "dealerSelfNet" as keyof InstitutionalRow, label: "自營商", color: "#d97706" },
    { key: "dealerHedgingNet" as keyof InstitutionalRow, label: "自營（避險）", color: "#f59e0b" },
];

// ─── 資料載入 ─────────────────────────────────────────────────

/**
 * 從 API 頂取三大法人資料，預設取近一年資料。
 * 請求 GET /api/stocks/{code}/institutional-investors?startDate=...
 */
async function fetchData() {
    if (!props.stockCode) return;
    loading.value = true;
    errorMsg.value = null;
    rawData.value = [];

    const startDate = new Date();
    startDate.setFullYear(startDate.getFullYear() - 1);
    const startDateStr = startDate.toISOString().slice(0, 10);

    try {
        const token = props.getToken();
        const headers: Record<string, string> = { "Content-Type": "application/json" };
        if (token) headers["Authorization"] = `Bearer ${token}`;

        const res = await fetch(`${props.apiBaseUrl}/api/stocks/${encodeURIComponent(props.stockCode)}/institutional-investors?startDate=${startDateStr}`, { headers });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        rawData.value = await res.json();
    } catch (err) {
        errorMsg.value = err instanceof Error ? err.message : "載入失敗";
    } finally {
        loading.value = false;
        setTimeout(() => chartInstance?.resize(), 10);
    }
}

// ─── 圖表 ─────────────────────────────────────────────────────

/** 初始化 ECharts 實例，若已存在則先釋放舊實例。 */
function initChart() {
    if (!chartContainer.value) return;
    if (chartInstance) {
        chartInstance.dispose();
        chartInstance = null;
    }
    chartInstance = echarts.init(chartContainer.value, undefined, { renderer: "canvas" });
}

/**
 * 依 rawData 繪製堆疊柱狀圖，分別蚩展會影: 展印全部法人類型 格式如下:
 * X軸: 日期，Y軸: 淨買賣（張），桚疊柱表示合計法人負負。
 */
function renderChart() {
    if (!chartInstance || rawData.value.length === 0) return;

    const dates = rawData.value.map((r) => r.date);

    const series = SERIES.map((s) => ({
        name: s.label,
        type: "bar" as const,
        stack: "net",
        emphasis: { focus: "series" as const },
        data: rawData.value.map((r) => r[s.key] as number),
        itemStyle: { color: s.color },
    }));

    const startPct = dates.length > 60 ? Math.max(0, Math.round((1 - 60 / dates.length) * 100)) : 0;

    const option: echarts.EChartsCoreOption = {
        tooltip: {
            trigger: "axis",
            triggerOn: isMobileView.value ? "click" : "mousemove|click",
            axisPointer: { type: "shadow" },
            formatter: (params: unknown) => {
                const items = params as Array<{ seriesName: string; value: number; color: string }>;
                if (!items || items.length === 0) return "";
                const date = (params as Array<{ axisValue: string }>)[0].axisValue;
                let html = `<div class="font-semibold mb-1">${date}</div>`;
                let total = 0;
                for (const item of items) {
                    if (item.seriesName === "合計") continue;
                    const val = item.value;
                    total += val;
                    const color = val >= 0 ? "#ef4444" : "#22c55e";
                    const sign = val >= 0 ? "+" : "";
                    html += `<div style="display:flex;justify-content:space-between;gap:16px">
                        <span><span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:${item.color};margin-right:4px"></span>${item.seriesName}</span>
                        <span style="color:${color};font-weight:600">${sign}${val.toLocaleString()} 張</span>
                    </div>`;
                }
                const totalColor = total >= 0 ? "#ef4444" : "#22c55e";
                const totalSign = total >= 0 ? "+" : "";
                html += `<div style="border-top:1px solid #e5e7eb;margin-top:4px;padding-top:4px;display:flex;justify-content:space-between;gap:16px;font-weight:700">
                    <span>合計</span>
                    <span style="color:${totalColor}">${totalSign}${total.toLocaleString()} 張</span>
                </div>`;
                return html;
            },
        },
        legend: {
            data: SERIES.map((s) => s.label),
            bottom: 32,
            itemWidth: 12,
            itemHeight: 12,
            textStyle: { fontSize: 12 },
        },
        grid: { left: 60, right: 16, top: 12, bottom: 88 },
        xAxis: {
            type: "category",
            data: dates,
            axisLabel: { fontSize: 11, rotate: 30 },
            axisTick: { alignWithLabel: true },
        },
        yAxis: {
            type: "value",
            name: "張",
            nameTextStyle: { fontSize: 11 },
            axisLabel: {
                fontSize: 11,
                formatter: (v: number) => {
                    if (Math.abs(v) >= 10000) return `${(v / 10000).toFixed(1)}萬`;
                    return v.toLocaleString();
                },
            },
            splitLine: { lineStyle: { type: "dashed", color: "#e5e7eb" } },
        },
        dataZoom: [
            {
                type: "inside",
                start: startPct,
                end: 100,
                zoomOnMouseWheel: !isMobileView.value,
                moveOnMouseMove: !isMobileView.value,
                moveOnMouseWheel: false,
                preventDefaultMouseMove: isMobileView.value,
                throttle: isMobileView.value ? 24 : 80,
            },
            { type: "slider", show: !isMobileView.value, start: startPct, end: 100, height: 20, bottom: 8 },
        ],
        series: [...series],
    };

    chartInstance.setOption(option, true);
}

function handleResize() {
    syncMobileView();
    chartInstance?.resize();
}

function syncMobileView() {
    isMobileView.value = window.innerWidth <= MOBILE_BREAKPOINT;
}

// ─── 生命週期 ──────────────────────────────────────────────────

onMounted(async () => {
    syncMobileView();
    window.addEventListener("resize", handleResize);
    await fetchData();
});

onBeforeUnmount(() => {
    window.removeEventListener("resize", handleResize);
    chartInstance?.dispose();
    chartInstance = null;
});

watch(rawData, async () => {
    await nextTick();
    initChart();
    renderChart();
});

watch(
    () => props.stockCode,
    async () => {
        await fetchData();
    },
);

// ─── 分頁 ─────────────────────────────────────────────────────

const pg = usePagination(computed(() => [...rawData.value].reverse()));
</script>

<template>
    <div class="flex flex-col gap-4">
        <!-- 錯誤 -->
        <div v-if="errorMsg" class="rounded-lg bg-red-50 px-4 py-3 text-sm text-red-600">{{ errorMsg }}</div>

        <!-- Loading -->
        <div v-else-if="loading" class="flex h-64 items-center justify-center text-slate-400">載入中…</div>

        <template v-else-if="rawData.length > 0">
            <!-- 圖表 -->
            <div ref="chartContainer" class="chart-touch-surface h-72 w-full rounded-xl border border-slate-100 bg-white shadow-sm"></div>

            <!-- 表格 -->
            <div class="overflow-x-auto rounded-xl border border-slate-100 shadow-sm">
                <table class="w-full min-w-[640px] text-right text-xs">
                    <thead>
                        <tr class="border-b border-slate-200 bg-slate-50 text-slate-500">
                            <th class="px-3 py-2 text-left font-semibold">日期</th>
                            <th class="px-3 py-2 font-semibold text-blue-600">外資</th>
                            <th class="px-3 py-2 font-semibold text-blue-400">外資自營</th>
                            <th class="px-3 py-2 font-semibold text-green-600">投信</th>
                            <th class="px-3 py-2 font-semibold text-amber-600">自營商</th>
                            <th class="px-3 py-2 font-semibold text-amber-500">自營（避險）</th>
                            <th class="px-3 py-2 font-semibold text-slate-700">合計</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr v-for="row in pg.pagedRows.value" :key="row.date" class="border-b border-slate-100 transition hover:bg-slate-50">
                            <td class="px-3 py-2 text-left font-medium text-slate-600">{{ row.date }}</td>
                            <td class="px-3 py-2" :class="row.foreignInvestorNet >= 0 ? 'text-red-600' : 'text-green-600'">{{ row.foreignInvestorNet >= 0 ? "+" : "" }}{{ row.foreignInvestorNet.toLocaleString() }}</td>
                            <td class="px-3 py-2" :class="row.foreignDealerSelfNet >= 0 ? 'text-red-600' : 'text-green-600'">{{ row.foreignDealerSelfNet >= 0 ? "+" : "" }}{{ row.foreignDealerSelfNet.toLocaleString() }}</td>
                            <td class="px-3 py-2" :class="row.investmentTrustNet >= 0 ? 'text-red-600' : 'text-green-600'">{{ row.investmentTrustNet >= 0 ? "+" : "" }}{{ row.investmentTrustNet.toLocaleString() }}</td>
                            <td class="px-3 py-2" :class="row.dealerSelfNet >= 0 ? 'text-red-600' : 'text-green-600'">{{ row.dealerSelfNet >= 0 ? "+" : "" }}{{ row.dealerSelfNet.toLocaleString() }}</td>
                            <td class="px-3 py-2" :class="row.dealerHedgingNet >= 0 ? 'text-red-600' : 'text-green-600'">{{ row.dealerHedgingNet >= 0 ? "+" : "" }}{{ row.dealerHedgingNet.toLocaleString() }}</td>
                            <td class="px-3 py-2 font-bold" :class="row.totalNet >= 0 ? 'text-red-700' : 'text-green-700'">{{ row.totalNet >= 0 ? "+" : "" }}{{ row.totalNet.toLocaleString() }}</td>
                        </tr>
                    </tbody>
                </table>
            </div>

            <!-- 分頁控制列 -->
            <TablePagination :pg="pg" />
        </template>

        <div v-else class="rounded-lg bg-slate-50 px-4 py-8 text-center text-sm text-slate-400">無可顯示的資料</div>
    </div>
</template>

<style scoped>
.chart-touch-surface {
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
}
</style>
