import type { SnapshotItem } from "../types";

/** 股票明細頁籤識別值。 */
export type DetailTabKey = "overview" | "history" | "revenue" | "institutional";

/** 單日 K 棒 SVG 所需座標資料。 */
export type KBarData = {
    wickX: number;
    wickTop: number;
    wickBottom: number;
    bodyX: number;
    bodyW: number;
    bodyTop: number;
    bodyHeight: number;
    isUp: boolean;
    svgW: number;
    svgH: number;
};

/** 將股票代碼正規化為大寫且無前後空白。 */
export function normalizeStockCode(code: string | null | undefined): string {
    return String(code ?? "")
        .trim()
        .toUpperCase();
}

/** 判斷目前是否位於台股開盤時段（週一至週五 08:30-14:00）。 */
export function isMarketOpen(): boolean {
    const now = new Date();
    const day = now.getDay();
    if (day === 0 || day === 6) {
        return false;
    }

    const totalMinutes = now.getHours() * 60 + now.getMinutes();
    return totalMinutes >= 8 * 60 + 30 && totalMinutes < 14 * 60;
}

/** 將成交金額格式化為億、百萬或原始數值。 */
export function formatTradeValue(value: number): string {
    if (value >= 1_000_000_000) {
        return `${(value / 1_000_000_000).toFixed(2)} 億`;
    }
    if (value >= 1_000_000) {
        return `${(value / 1_000_000).toFixed(2)} 百萬`;
    }
    return value.toLocaleString();
}

/**
 * 將即時快照轉成單日 K 棒 SVG 所需座標。
 * 若缺乏有效價格資訊，回傳 null。
 */
export function createKBarData(snapshot: SnapshotItem | null): KBarData | null {
    if (!snapshot) {
        return null;
    }

    const high = snapshot.highPrice ?? 0;
    const low = snapshot.lowPrice ?? 0;
    const open = snapshot.openPrice ?? 0;
    const close = snapshot.lastPrice ?? snapshot.closePrice ?? 0;
    const range = high - low;
    if (high === 0 && low === 0 && open === 0 && close === 0) {
        return null;
    }

    const svgH = 80;
    const svgW = 36;
    const pad = 4;
    const innerH = svgH - pad * 2;
    const wickX = svgW / 2;
    const bodyW = 16;
    const bodyX = (svgW - bodyW) / 2;
    const isUp = close >= open;

    if (range === 0) {
        const midY = pad + innerH / 2;
        return { wickX, wickTop: midY, wickBottom: midY, bodyX, bodyW, bodyTop: midY - 1, bodyHeight: 2, isUp, svgW, svgH };
    }

    const priceToY = (price: number) => pad + innerH - ((price - low) / range) * innerH;
    const wickTop = priceToY(high);
    const wickBottom = priceToY(low);
    const bodyTop = priceToY(Math.max(open, close));
    const bodyHeight = Math.max(Math.abs(priceToY(Math.min(open, close)) - bodyTop), 2);

    return { wickX, wickTop, wickBottom, bodyX, bodyW, bodyTop, bodyHeight, isUp, svgW, svgH };
}
