<script setup lang="ts">
import { computed, ref } from "vue";
import type { StockGroup } from "../types";

const props = defineProps<{
    isMobileView: boolean;
    isShowingCreateForm: boolean;
    groupSearchKeyword: string;
    newGroupName: string;
    newGroupDescription: string;
    customGroups: StockGroup[];
    systemGroups: StockGroup[];
    selectedGroupId: string;
    editingGroupId: string | null;
    editingGroupName: string;
    editingGroupDescription: string;
    isLoadingGroups: boolean;
    isSystemGroupsCollapsed: boolean;
}>();

const emit = defineEmits<{
    "set-sidebar-collapsed": [value: boolean];
    "update:isShowingCreateForm": [value: boolean];
    "update:groupSearchKeyword": [value: string];
    "update:newGroupName": [value: string];
    "update:newGroupDescription": [value: string];
    "update:isSystemGroupsCollapsed": [value: boolean];
    "update:editingGroupName": [value: string];
    "update:editingGroupDescription": [value: string];
    "select-group": [groupId: string];
    "open-mobile-group-search": [];
    "create-group": [];
    "start-rename-group": [group: StockGroup];
    "cancel-rename-group": [];
    "submit-rename-group": [groupId: string];
    "delete-group": [groupId: string, groupName: string];
}>();

const mobileGroupSectionEl = ref<HTMLElement | null>(null);
const customGroupsListEl = ref<HTMLElement | null>(null);

const groupSearchKeywordModel = computed({
    get: () => props.groupSearchKeyword,
    set: (value: string) => emit("update:groupSearchKeyword", value),
});

const newGroupNameModel = computed({
    get: () => props.newGroupName,
    set: (value: string) => emit("update:newGroupName", value),
});

const newGroupDescriptionModel = computed({
    get: () => props.newGroupDescription,
    set: (value: string) => emit("update:newGroupDescription", value),
});

const editingGroupNameModel = computed({
    get: () => props.editingGroupName,
    set: (value: string) => emit("update:editingGroupName", value),
});

const editingGroupDescriptionModel = computed({
    get: () => props.editingGroupDescription,
    set: (value: string) => emit("update:editingGroupDescription", value),
});

/** 回傳群組面板的 DOM 節點，供父層進行手機滑動定位。 */
function getMobileGroupSectionEl(): HTMLElement | null {
    return mobileGroupSectionEl.value;
}

/** 回傳自訂群組清單容器，供父層掛載 Sortable。 */
function getCustomGroupsListEl(): HTMLElement | null {
    return customGroupsListEl.value;
}

defineExpose({
    getMobileGroupSectionEl,
    getCustomGroupsListEl,
});
</script>

<template>
    <aside ref="mobileGroupSectionEl" class="group-sidebar w-72 border-r border-slate-200 bg-white/95 backdrop-blur flex flex-col">
        <div class="border-b border-slate-200 px-4 py-3">
            <div class="flex items-center justify-between gap-2">
                <h2 class="font-bold text-slate-900">群組</h2>
                <div class="flex items-center gap-1">
                    <button @click="emit('update:isShowingCreateForm', !props.isShowingCreateForm)" class="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-800 text-white hover:bg-slate-700 transition">
                        {{ props.isShowingCreateForm ? "−" : "+" }}
                    </button>
                    <button @click="emit('set-sidebar-collapsed', props.isMobileView ? false : true)" class="collapse-sidebar-button flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-400 hover:bg-slate-100 hover:text-slate-700 transition" title="收合側欄">
                        <svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                            <path fill-rule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clip-rule="evenodd" />
                        </svg>
                    </button>
                </div>
            </div>
            <div class="relative mt-2">
                <input v-model="groupSearchKeywordModel" @click="emit('open-mobile-group-search')" class="mobile-search-input w-full rounded-lg border border-slate-300 bg-slate-50 px-3 py-2 pr-8 text-sm outline-none transition focus:border-cyan-500 focus:ring-2 focus:ring-cyan-200" type="text" placeholder="搜尋群組或股票" />
                <button v-if="props.groupSearchKeyword" type="button" class="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600" tabindex="-1" @click="emit('update:groupSearchKeyword', '')">✕</button>
            </div>
        </div>

        <div v-if="props.isShowingCreateForm" class="border-b border-slate-200 bg-slate-50 px-4 py-3">
            <form class="space-y-2" @submit.prevent="emit('create-group')">
                <div class="relative">
                    <input v-model="newGroupNameModel" class="w-full rounded-lg border border-slate-300 px-3 py-2 pr-8 text-sm outline-none transition focus:border-cyan-500 focus:ring-2 focus:ring-cyan-200" type="text" placeholder="群組名稱" />
                    <button v-if="props.newGroupName" type="button" class="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600" tabindex="-1" @click="emit('update:newGroupName', '')">✕</button>
                </div>
                <div class="relative">
                    <input v-model="newGroupDescriptionModel" class="w-full rounded-lg border border-slate-300 px-3 py-2 pr-8 text-sm outline-none transition focus:border-cyan-500 focus:ring-2 focus:ring-cyan-200" type="text" placeholder="描述 (選填)" />
                    <button v-if="props.newGroupDescription" type="button" class="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600" tabindex="-1" @click="emit('update:newGroupDescription', '')">✕</button>
                </div>
                <div class="flex gap-2">
                    <button class="flex-1 rounded-lg bg-slate-900 px-2 py-2 text-sm font-semibold text-white hover:bg-slate-700 transition" type="submit">建立</button>
                    <button class="flex-1 rounded-lg border border-slate-300 bg-white px-2 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50 transition" type="button" @click="emit('update:isShowingCreateForm', false)">取消</button>
                </div>
            </form>
        </div>

        <nav class="flex-1 overflow-y-auto px-2 py-2">
            <div v-if="props.customGroups.length > 0">
                <p class="px-2 py-1.5 text-xs font-bold uppercase tracking-wider text-amber-600 mb-1">自訂群組</p>
                <div ref="customGroupsListEl" class="space-y-0.5">
                    <div v-for="group in props.customGroups" :key="group.id" class="drag-row group/item">
                        <form v-if="props.editingGroupId === group.id" class="flex flex-col gap-1 px-1 py-1" @submit.prevent="emit('submit-rename-group', group.id)">
                            <div class="flex items-center gap-1">
                                <div class="relative min-w-0 flex-1">
                                    <input v-model="editingGroupNameModel" class="w-full rounded border border-amber-400 px-2 py-1 pr-7 text-sm outline-none focus:ring-2 focus:ring-amber-300" type="text" placeholder="群組名稱" autofocus @keydown.esc.prevent="emit('cancel-rename-group')" />
                                    <button v-if="props.editingGroupName" type="button" class="absolute right-1.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600" tabindex="-1" @click="emit('update:editingGroupName', '')">✕</button>
                                </div>
                                <button type="submit" class="shrink-0 rounded bg-amber-500 px-2 py-1 text-xs font-semibold text-white hover:bg-amber-400" title="確認">✓</button>
                                <button type="button" class="shrink-0 rounded border border-slate-300 bg-white px-2 py-1 text-xs font-semibold text-slate-600 hover:bg-slate-50" @click.stop="emit('cancel-rename-group')" title="取消">✕</button>
                            </div>
                            <div class="relative">
                                <input v-model="editingGroupDescriptionModel" class="w-full rounded border border-slate-300 px-2 py-1 pr-7 text-xs outline-none focus:border-amber-400 focus:ring-1 focus:ring-amber-300" type="text" placeholder="描述（選填）" @keydown.esc.prevent="emit('cancel-rename-group')" />
                                <button v-if="props.editingGroupDescription" type="button" class="absolute right-1.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600" tabindex="-1" @click="emit('update:editingGroupDescription', '')">✕</button>
                            </div>
                        </form>
                        <div v-else class="relative flex items-center">
                            <button @click="emit('select-group', group.id)" class="flex w-full cursor-pointer select-none items-center justify-between rounded-lg px-2.5 py-2 pr-14 text-left text-sm transition" :class="[props.selectedGroupId === group.id ? 'bg-amber-500 text-white font-semibold shadow-md' : 'bg-slate-100 text-slate-900 hover:bg-slate-200']">
                                <span class="mr-2 shrink-0 text-base leading-none opacity-25 select-none" :class="!props.groupSearchKeyword.trim() && !props.editingGroupId ? 'cursor-grab' : 'cursor-default opacity-15'" title="拖曳排序"> ⠿ </span>
                                <span class="line-clamp-1 flex-1">{{ group.name }}</span>
                                <span class="ml-2 shrink-0 rounded px-1.5 py-0.5 text-xs font-semibold" :class="props.selectedGroupId === group.id ? 'bg-white/20 text-white' : 'bg-slate-200 text-slate-600'">{{ group.memberCount }}</span>
                            </button>
                            <button
                                @click.stop="emit('start-rename-group', group)"
                                class="absolute right-7 top-1/2 -translate-y-1/2 flex h-5 w-5 items-center justify-center rounded opacity-0 transition group-hover/item:opacity-100"
                                :class="props.selectedGroupId === group.id ? 'text-white/70 hover:bg-white/20 hover:text-white' : 'text-slate-400 hover:bg-slate-200 hover:text-slate-600'"
                                title="重新命名"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" class="h-3.5 w-3.5" viewBox="0 0 20 20" fill="currentColor">
                                    <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
                                </svg>
                            </button>
                            <button
                                @click.stop="emit('delete-group', group.id, group.name)"
                                class="absolute right-1.5 top-1/2 -translate-y-1/2 flex h-5 w-5 items-center justify-center rounded opacity-0 transition group-hover/item:opacity-100 hover:bg-red-100 hover:text-red-600"
                                :class="props.selectedGroupId === group.id ? 'text-white/70 hover:bg-white/20 hover:text-white' : 'text-slate-400'"
                                title="刪除群組"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" class="h-3.5 w-3.5" viewBox="0 0 20 20" fill="currentColor">
                                    <path fill-rule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clip-rule="evenodd" />
                                </svg>
                            </button>
                        </div>
                    </div>
                </div>
            </div>
            <div v-if="props.systemGroups.length > 0" class="mb-3">
                <button type="button" class="mb-1 flex w-full items-center justify-between rounded-lg px-2 py-1.5 text-xs font-bold uppercase tracking-wider text-cyan-600 hover:bg-cyan-50" :aria-expanded="!props.isSystemGroupsCollapsed" @click="emit('update:isSystemGroupsCollapsed', !props.isSystemGroupsCollapsed)">
                    <span>系統範本 ({{ props.systemGroups.length }})</span>
                    <span>{{ props.isSystemGroupsCollapsed ? "展開" : "收合" }}</span>
                </button>
                <div v-if="!props.isSystemGroupsCollapsed" class="space-y-1">
                    <button v-for="group in props.systemGroups" :key="group.id" @click="emit('select-group', group.id)" class="flex w-full items-center justify-between rounded-lg px-2.5 py-2 text-left text-sm transition" :class="props.selectedGroupId === group.id ? 'bg-cyan-500 text-white font-semibold shadow-md' : 'bg-slate-100 text-slate-900 hover:bg-slate-200'">
                        <span class="line-clamp-1 flex-1">{{ group.name }}</span>
                        <span class="ml-2 shrink-0 text-xs font-semibold">{{ group.memberCount }}</span>
                    </button>
                </div>
            </div>

            <p v-if="props.isLoadingGroups && props.systemGroups.length === 0 && props.customGroups.length === 0" class="px-2 py-4 text-center text-sm text-slate-500">載入中...</p>
        </nav>
    </aside>
</template>
