import { apiBaseUrl as defaultApiBaseUrl } from "../config/env";

/** 提供 JWT Bearer Token 的函式。 */
export type TokenProvider = () => string | null;

/** 通用 API request 函式簽章。 */
export type ApiRequest = <T>(path: string, init?: RequestInit) => Promise<T>;

/** 共用 API client 的建構選項。 */
export interface ApiClientOptions {
    /** 覆寫預設 API base URL。 */
    baseUrl?: string;
    /** 每次請求前動態取得 Bearer Token。 */
    getToken?: TokenProvider;
}

/**
 * 建立通用 HTTP client。
 * 自動附帶 JSON Content-Type、Bearer Token，並統一處理錯誤訊息與 204 回應。
 */
export function createApiClient(options: ApiClientOptions = {}) {
    const baseUrl = options.baseUrl ?? defaultApiBaseUrl;

    /**
     * 建立單次請求所需的標頭，保留呼叫端覆寫權限。
     * @param initHeaders 呼叫端傳入的 Request headers。
     * @param body 本次請求主體，用於判斷是否應自動補上 Content-Type。
     */
    function createHeaders(initHeaders?: HeadersInit, body?: BodyInit | null): Headers {
        const headers = new Headers(initHeaders);
        const token = options.getToken?.();

        if (!(body instanceof FormData) && !headers.has("Content-Type")) {
            headers.set("Content-Type", "application/json");
        }

        if (token && !headers.has("Authorization")) {
            headers.set("Authorization", `Bearer ${token}`);
        }

        return headers;
    }

    /**
     * 解析非 2xx 回應的錯誤訊息，盡量從 JSON/message 中抽出可讀文字。
     * @param response fetch 回傳的 Response。
     */
    async function toErrorMessage(response: Response): Promise<string> {
        const errorText = await response.text();
        let message = `Request failed: ${response.status}`;

        try {
            const parsed = JSON.parse(errorText) as { message?: string } | string;
            if (typeof parsed === "string" && parsed) {
                message = parsed;
            } else if (typeof parsed === "object" && parsed?.message) {
                message = parsed.message;
            } else if (errorText) {
                message = errorText;
            }
        } catch {
            if (errorText) {
                message = errorText;
            }
        }

        return message;
    }

    /**
     * 發送 HTTP 請求並將成功回應解析為 JSON。
     * @param path 以 `/` 開頭的 API 相對路徑。
     * @param init 原生 fetch RequestInit 選項。
     */
    const request: ApiRequest = async <T>(path: string, init?: RequestInit): Promise<T> => {
        const response = await fetch(`${baseUrl}${path}`, {
            ...init,
            headers: createHeaders(init?.headers, init?.body),
        });

        if (!response.ok) {
            throw new Error(await toErrorMessage(response));
        }

        if (response.status === 204) {
            return undefined as T;
        }

        return (await response.json()) as T;
    };

    return { request };
}
