<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import * as echarts from "echarts/core";
import { BarChart, LineChart } from "echarts/charts";
import { GridComponent, TooltipComponent, LegendComponent, DataZoomComponent } from "echarts/components";
import { CanvasRenderer } from "echarts/renderers";
import { usePagination } from "../composables/usePagination";
import TablePagination from "./TablePagination.vue";

echarts.use([TooltipComponent, GridComponent, LegendComponent, DataZoomComponent, BarChart, LineChart, CanvasRenderer]);

// ─── 型別定義 ─────────────────────────────────────────────────

type RevenueItem = {
    date: string;
    stockId: string;
    revenue: number;
    revenueMonth: number;
    revenueYear: number;
    monthOverMonthRate: number | null;
};

type MonthRow = RevenueItem & { yoyRate: number | null; isAllTimeHigh: boolean };

type AnnualRow = {
    year: number;
    revenue: number;
    yoyRate: number | null;
    isAllTimeHigh: boolean;
};

type QuarterRow = {
    label: string;
    year: number;
    quarter: number;
    revenue: number;
    qoqRate: number | null;
    yoyRate: number | null;
    isAllTimeHigh: boolean;
};

// ECharts bar 資料項目（支援 per-item 顏色與自訂屬性）
type BarDataItem = { value: number; itemStyle: { color: string }; isAllTimeHigh: boolean };

type ViewMode = "monthly" | "annual" | "quarterly";

// ─── Props ────────────────────────────────────────────────────

const props = defineProps<{
    stockCode: string;
    apiBaseUrl: string;
    getToken: () => string | null;
}>();

// ─── 狀態 ─────────────────────────────────────────────────────

const viewMode = ref<ViewMode>("monthly");
const chartContainer = ref<HTMLDivElement>();
let chart: ReturnType<typeof echarts.init> | null = null;
const MOBILE_BREAKPOINT = 1024;
const isMobileView = ref(false);

const isLoading = ref(false);
const errorMsg = ref<string | null>(null);
const rawData = ref<RevenueItem[]>([]);

// ─── 月資料（含月增率、年增率、歷史新高） ─────────────────────

const monthlyRows = computed<MonthRow[]>(() => {
    const sorted = [...rawData.value].sort((a, b) => a.date.localeCompare(b.date));
    const revenueMap = new Map<string, number>();
    for (const item of sorted) {
        revenueMap.set(`${item.revenueYear}-${item.revenueMonth}`, item.revenue);
    }
    const globalMax = sorted.length > 0 ? Math.max(...sorted.map((i) => i.revenue)) : 0;
    return sorted.map((item) => {
        const prevRev = revenueMap.get(`${item.revenueYear - 1}-${item.revenueMonth}`);
        const yoyRate = prevRev !== undefined && prevRev !== 0 ? parseFloat((((item.revenue - prevRev) / prevRev) * 100).toFixed(2)) : null;
        const isAllTimeHigh = globalMax > 0 && item.revenue >= globalMax;
        return { ...item, yoyRate, isAllTimeHigh };
    });
});

// ─── 年資料（含年增率、歷史新高） ────────────────────────────

const annualRows = computed<AnnualRow[]>(() => {
    const byYear = new Map<number, number>();
    for (const item of rawData.value) {
        byYear.set(item.revenueYear, (byYear.get(item.revenueYear) ?? 0) + item.revenue);
    }
    const years = [...byYear.keys()].sort((a, b) => a - b);
    const allRevenues = years.map((y) => byYear.get(y)!);
    const globalMax = allRevenues.length > 0 ? Math.max(...allRevenues) : 0;
    return years.map((year, i) => {
        const revenue = byYear.get(year)!;
        const prevRevenue = i > 0 ? byYear.get(years[i - 1]) : undefined;
        const yoyRate = prevRevenue !== undefined && prevRevenue !== 0 ? parseFloat((((revenue - prevRevenue) / prevRevenue) * 100).toFixed(2)) : null;
        const isAllTimeHigh = globalMax > 0 && revenue >= globalMax;
        return { year, revenue, yoyRate, isAllTimeHigh };
    });
});

// ─── 季資料（含季增率、同期比、歷史新高） ─────────────────────

const quarterlyRows = computed<QuarterRow[]>(() => {
    const getQ = (month: number) => Math.ceil(month / 3);
    const byKey = new Map<string, { year: number; quarter: number; revenue: number }>();
    for (const item of rawData.value) {
        const q = getQ(item.revenueMonth);
        const key = `${item.revenueYear}-Q${q}`;
        const existing = byKey.get(key);
        if (existing) {
            existing.revenue += item.revenue;
        } else {
            byKey.set(key, { year: item.revenueYear, quarter: q, revenue: item.revenue });
        }
    }
    const sorted = [...byKey.values()].sort((a, b) => (a.year !== b.year ? a.year - b.year : a.quarter - b.quarter));
    const globalMax = sorted.length > 0 ? Math.max(...sorted.map((s) => s.revenue)) : 0;
    return sorted.map((item, i) => {
        const prev = i > 0 ? sorted[i - 1] : null;
        const prevYear = sorted.find((x) => x.year === item.year - 1 && x.quarter === item.quarter);
        const qoqRate = prev && prev.revenue !== 0 ? parseFloat((((item.revenue - prev.revenue) / prev.revenue) * 100).toFixed(2)) : null;
        const yoyRate = prevYear && prevYear.revenue !== 0 ? parseFloat((((item.revenue - prevYear.revenue) / prevYear.revenue) * 100).toFixed(2)) : null;
        const isAllTimeHigh = globalMax > 0 && item.revenue >= globalMax;
        return { label: `${item.year} Q${item.quarter}`, year: item.year, quarter: item.quarter, revenue: item.revenue, qoqRate, yoyRate, isAllTimeHigh };
    });
});

// ─── 分頁 ─────────────────────────────────────────────────────

const monthlyPg = usePagination(computed(() => [...monthlyRows.value].reverse()));
const annualPg = usePagination(computed(() => [...annualRows.value].reverse()));
const quarterPg = usePagination(computed(() => [...quarterlyRows.value].reverse()));

// ─── 工具函式 ─────────────────────────────────────────────────

/** 側欄標籤 "年/月"  序號，例如 "2025/01"  。 */
function monthLabel(item: RevenueItem): string {
    return `${item.revenueYear}/${String(item.revenueMonth).padStart(2, "0")}`;
}

/** 將營收元轉換為亿元字串，保留兩位小數。 */
function fmtRevenue(val: number): string {
    return (val / 1e8).toFixed(2);
}

function fmtRate(val: number | null): string {
    if (val === null) return "—";
    return `${val >= 0 ? "+" : ""}${val.toFixed(2)}%`;
}

/** 為價格變動率選擇顨色類別（正數為漲傅色、負數為綠色，循台灣詣市美學）。 */
function rateClass(val: number | null): string {
    if (val === null) return "text-slate-400";
    return val >= 0 ? "text-rose-600" : "text-emerald-600";
}

/** 將含 isAllTimeHigh 的 row 轉為 ECharts bar 資料項目 */
function toBarItem(revenue: number, isHigh: boolean, defaultColor: string): BarDataItem {
    return {
        value: parseFloat(fmtRevenue(revenue)),
        itemStyle: { color: isHigh ? "#ef4444" : defaultColor },
        isAllTimeHigh: isHigh,
    };
}

// ─── API 取得 ─────────────────────────────────────────────────

/**
 * 從 API 頂取營收資料並寫入 rawData。
 * 請求 GET /api/stocks/{code}/revenue，不設定日期範圍（從 Redis 取得全所有月歷史）。
 */
async function fetchRevenue() {
    isLoading.value = true;
    errorMsg.value = null;
    try {
        const token = props.getToken();
        const resp = await fetch(`${props.apiBaseUrl}/api/stocks/${encodeURIComponent(props.stockCode)}/revenue`, {
            headers: {
                "Content-Type": "application/json",
                ...(token ? { Authorization: `Bearer ${token}` } : {}),
            },
        });
        if (!resp.ok) {
            const text = await resp.text();
            let msg = `HTTP ${resp.status}`;
            try {
                const parsed = JSON.parse(text);
                if (parsed?.message) msg = parsed.message;
            } catch {
                /* ignore */
            }
            throw new Error(msg);
        }
        rawData.value = await resp.json();
    } catch (e: unknown) {
        errorMsg.value = e instanceof Error ? e.message : String(e);
    } finally {
        isLoading.value = false;
        setTimeout(() => chart?.resize(), 10);
    }
}

// ─── ECharts ─────────────────────────────────────────────────

function initChart() {
    if (!chartContainer.value || chart) return;
    chart = echarts.init(chartContainer.value);
    window.addEventListener("resize", handleResize);
}

function handleResize() {
    syncMobileView();
    chart?.resize();
}

function syncMobileView() {
    isMobileView.value = window.innerWidth <= MOBILE_BREAKPOINT;
}

function buildOption(labels: string[], barData: BarDataItem[], barName: string, lines: { name: string; data: (number | null)[]; color: string }[], defaultShowCount = 24) {
    const total = labels.length;
    const startPct = total > defaultShowCount ? Math.round((1 - defaultShowCount / total) * 100) : 0;

    return {
        tooltip: {
            trigger: "axis",
            triggerOn: isMobileView.value ? "click" : "mousemove|click",
            axisPointer: { type: "cross" },
            formatter(params: unknown) {
                const items = params as Array<{ seriesName: string; value: number | null; axisValue: string; color: string; data: BarDataItem }>;
                if (!items?.length) return "";
                let html = `<strong>${items[0].axisValue}</strong><br/>`;
                for (const p of items) {
                    const isBar = p.seriesName === barName;
                    const v = p.value;
                    const fmtd = v === null || v === undefined ? "—" : isBar ? `${v.toFixed(2)} 億` : `${v >= 0 ? "+" : ""}${v.toFixed(2)}%`;
                    const highTag = isBar && typeof p.data === "object" && p.data?.isAllTimeHigh ? ' <span style="background:#fee2e2;color:#dc2626;border-radius:3px;padding:0 3px;font-size:10px;font-weight:700">歷史新高</span>' : "";
                    html += `<span style="color:${p.color}">●</span> ${p.seriesName}：${fmtd}${highTag}<br/>`;
                }
                return html;
            },
        },
        legend: { data: [barName, ...lines.map((l) => l.name)], top: 4, textStyle: { fontSize: 12 } },
        grid: { left: 64, right: 64, bottom: 56, top: 48 },
        dataZoom: [
            {
                type: "inside",
                start: startPct,
                end: 100,
                zoomOnMouseWheel: !isMobileView.value,
                moveOnMouseMove: !isMobileView.value,
                moveOnMouseWheel: false,
                preventDefaultMouseMove: isMobileView.value,
                throttle: isMobileView.value ? 24 : 80,
            },
            { type: "slider", show: !isMobileView.value, start: startPct, end: 100, height: 18, bottom: 6 },
        ],
        xAxis: {
            type: "category",
            data: labels,
            axisLabel: { rotate: 45, fontSize: 11 },
        },
        yAxis: [
            {
                type: "value",
                name: "億元",
                position: "left",
                axisLabel: { formatter: (v: number) => v.toFixed(0) },
            },
            {
                type: "value",
                name: "%",
                position: "right",
                axisLabel: { formatter: (v: number) => `${v}%` },
                splitLine: { show: false },
            },
        ],
        series: [
            {
                name: barName,
                type: "bar",
                yAxisIndex: 0,
                data: barData,
                barMaxWidth: 28,
            },
            ...lines.map((l) => ({
                name: l.name,
                type: "line",
                yAxisIndex: 1,
                data: l.data,
                connectNulls: false,
                smooth: true,
                lineStyle: { color: l.color, width: 2 },
                itemStyle: { color: l.color },
                symbol: "circle",
                symbolSize: 5,
            })),
        ],
    };
}

function renderChart() {
    if (!chart) return;

    if (viewMode.value === "monthly") {
        const rows = monthlyRows.value;
        if (!rows.length) return;
        chart.setOption(
            buildOption(
                rows.map(monthLabel),
                rows.map((d) => toBarItem(d.revenue, d.isAllTimeHigh, "#38bdf8")),
                "月營收（億元）",
                [
                    { name: "月增率", data: rows.map((d) => d.monthOverMonthRate), color: "#f97316" },
                    { name: "年增率（同期比）", data: rows.map((d) => d.yoyRate), color: "#8b5cf6" },
                ],
                24,
            ),
            true,
        );
    } else if (viewMode.value === "annual") {
        const rows = annualRows.value;
        if (!rows.length) return;
        chart.setOption(
            buildOption(
                rows.map((r) => String(r.year)),
                rows.map((r) => toBarItem(r.revenue, r.isAllTimeHigh, "#34d399")),
                "年營收（億元）",
                [{ name: "年增率", data: rows.map((r) => r.yoyRate), color: "#8b5cf6" }],
                20,
            ),
            true,
        );
    } else {
        const rows = quarterlyRows.value;
        if (!rows.length) return;
        chart.setOption(
            buildOption(
                rows.map((r) => r.label),
                rows.map((r) => toBarItem(r.revenue, r.isAllTimeHigh, "#fb923c")),
                "季營收（億元）",
                [
                    { name: "季增率", data: rows.map((r) => r.qoqRate), color: "#f97316" },
                    { name: "年增率（同期比）", data: rows.map((r) => r.yoyRate), color: "#8b5cf6" },
                ],
                12,
            ),
            true,
        );
    }
}

// ─── 生命週期 ─────────────────────────────────────────────────

onMounted(async () => {
    syncMobileView();
    await fetchRevenue();
});

onBeforeUnmount(() => {
    window.removeEventListener("resize", handleResize);
    chart?.dispose();
    chart = null;
});

watch(
    () => props.stockCode,
    async () => {
        chart?.dispose();
        chart = null;
        rawData.value = [];
        await fetchRevenue();
    },
);

watch([rawData, viewMode], async () => {
    await nextTick();
    initChart();
    renderChart();
});
</script>

<template>
    <div>
        <div v-if="isLoading" class="py-8 text-center text-sm text-slate-400">載入中...</div>
        <div v-else-if="errorMsg" class="rounded-lg border border-rose-200 bg-rose-50 p-3 text-sm text-rose-700">{{ errorMsg }}</div>
        <template v-else-if="rawData.length > 0">
            <!-- 檢視模式切換 -->
            <div class="mb-3 inline-flex rounded-xl border border-slate-200 bg-slate-50 p-1 gap-0.5">
                <button type="button" class="rounded-lg px-3 py-1 text-xs font-semibold transition" :class="viewMode === 'monthly' ? 'bg-white text-cyan-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'" @click="viewMode = 'monthly'">月營收</button>
                <button type="button" class="rounded-lg px-3 py-1 text-xs font-semibold transition" :class="viewMode === 'annual' ? 'bg-white text-cyan-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'" @click="viewMode = 'annual'">年累計</button>
                <button type="button" class="rounded-lg px-3 py-1 text-xs font-semibold transition" :class="viewMode === 'quarterly' ? 'bg-white text-cyan-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'" @click="viewMode = 'quarterly'">季營收</button>
            </div>

            <!-- 圖例說明 -->
            <div class="mb-2 flex items-center gap-3 text-[11px] text-slate-500">
                <span class="flex items-center gap-1"><span class="inline-block w-3 h-3 rounded-sm bg-rose-500"></span>歷史新高</span>
            </div>

            <!-- ECharts 圖表 -->
            <div ref="chartContainer" class="chart-touch-surface w-full" style="height: 340px" />

            <!-- 月營收表格 -->
            <template v-if="viewMode === 'monthly'">
                <div class="mt-4 overflow-x-auto">
                    <table class="w-full text-sm">
                        <thead>
                            <tr class="border-b border-slate-200 text-left text-xs text-slate-500">
                                <th class="pb-2 pr-3 font-medium whitespace-nowrap">年/月</th>
                                <th class="pb-2 pr-3 text-right font-medium whitespace-nowrap">月營收（元）</th>
                                <th class="pb-2 pr-3 text-right font-medium whitespace-nowrap">月增率</th>
                                <th class="pb-2 text-right font-medium whitespace-nowrap">年增率（同期比）</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr v-for="item in monthlyPg.pagedRows.value" :key="item.date" class="border-b transition-colors" :class="item.isAllTimeHigh ? 'border-rose-100 bg-rose-50/60 hover:bg-rose-50' : 'border-slate-100 hover:bg-slate-50'">
                                <td class="py-1.5 pr-3 tabular-nums font-medium whitespace-nowrap" :class="item.isAllTimeHigh ? 'text-rose-700' : 'text-slate-700'">
                                    {{ monthLabel(item) }}
                                    <span v-if="item.isAllTimeHigh" class="ml-1 inline-flex items-center rounded px-1 py-0.5 text-[10px] font-bold bg-rose-100 text-rose-600">新高</span>
                                </td>
                                <td class="py-1.5 pr-3 text-right tabular-nums whitespace-nowrap font-semibold" :class="item.isAllTimeHigh ? 'text-rose-700' : 'text-slate-800'">{{ item.revenue.toLocaleString() }}</td>
                                <td class="py-1.5 pr-3 text-right tabular-nums font-semibold whitespace-nowrap" :class="rateClass(item.monthOverMonthRate)">{{ fmtRate(item.monthOverMonthRate) }}</td>
                                <td class="py-1.5 text-right tabular-nums font-semibold whitespace-nowrap" :class="rateClass(item.yoyRate)">{{ fmtRate(item.yoyRate) }}</td>
                            </tr>
                        </tbody>
                    </table>
                </div>
                <TablePagination :pg="monthlyPg" class="mt-2" />
            </template>

            <!-- 年累計表格 -->
            <template v-else-if="viewMode === 'annual'">
                <div class="mt-4 overflow-x-auto">
                    <table class="w-full text-sm">
                        <thead>
                            <tr class="border-b border-slate-200 text-left text-xs text-slate-500">
                                <th class="pb-2 pr-3 font-medium whitespace-nowrap">年度</th>
                                <th class="pb-2 pr-3 text-right font-medium whitespace-nowrap">年營收（元）</th>
                                <th class="pb-2 text-right font-medium whitespace-nowrap">年增率</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr v-for="row in annualPg.pagedRows.value" :key="row.year" class="border-b transition-colors" :class="row.isAllTimeHigh ? 'border-rose-100 bg-rose-50/60 hover:bg-rose-50' : 'border-slate-100 hover:bg-slate-50'">
                                <td class="py-1.5 pr-3 tabular-nums font-medium whitespace-nowrap" :class="row.isAllTimeHigh ? 'text-rose-700' : 'text-slate-700'">
                                    {{ row.year }}
                                    <span v-if="row.isAllTimeHigh" class="ml-1 inline-flex items-center rounded px-1 py-0.5 text-[10px] font-bold bg-rose-100 text-rose-600">新高</span>
                                </td>
                                <td class="py-1.5 pr-3 text-right tabular-nums whitespace-nowrap font-semibold" :class="row.isAllTimeHigh ? 'text-rose-700' : 'text-slate-800'">{{ row.revenue.toLocaleString() }}</td>
                                <td class="py-1.5 text-right tabular-nums font-semibold" :class="rateClass(row.yoyRate)">{{ fmtRate(row.yoyRate) }}</td>
                            </tr>
                        </tbody>
                    </table>
                </div>
                <TablePagination :pg="annualPg" class="mt-2" />
            </template>

            <!-- 季營收表格 -->
            <template v-else>
                <div class="mt-4 overflow-x-auto">
                    <table class="w-full text-sm">
                        <thead>
                            <tr class="border-b border-slate-200 text-left text-xs text-slate-500">
                                <th class="pb-2 pr-3 font-medium whitespace-nowrap">季度</th>
                                <th class="pb-2 pr-3 text-right font-medium whitespace-nowrap">季營收（元）</th>
                                <th class="pb-2 pr-3 text-right font-medium whitespace-nowrap">季增率</th>
                                <th class="pb-2 text-right font-medium whitespace-nowrap">年增率（同期比）</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr v-for="row in quarterPg.pagedRows.value" :key="row.label" class="border-b transition-colors" :class="row.isAllTimeHigh ? 'border-rose-100 bg-rose-50/60 hover:bg-rose-50' : 'border-slate-100 hover:bg-slate-50'">
                                <td class="py-1.5 pr-3 tabular-nums font-medium whitespace-nowrap" :class="row.isAllTimeHigh ? 'text-rose-700' : 'text-slate-700'">
                                    {{ row.label }}
                                    <span v-if="row.isAllTimeHigh" class="ml-1 inline-flex items-center rounded px-1 py-0.5 text-[10px] font-bold bg-rose-100 text-rose-600">新高</span>
                                </td>
                                <td class="py-1.5 pr-3 text-right tabular-nums whitespace-nowrap font-semibold" :class="row.isAllTimeHigh ? 'text-rose-700' : 'text-slate-800'">{{ row.revenue.toLocaleString() }}</td>
                                <td class="py-1.5 pr-3 text-right tabular-nums font-semibold whitespace-nowrap" :class="rateClass(row.qoqRate)">{{ fmtRate(row.qoqRate) }}</td>
                                <td class="py-1.5 text-right tabular-nums font-semibold whitespace-nowrap" :class="rateClass(row.yoyRate)">{{ fmtRate(row.yoyRate) }}</td>
                            </tr>
                        </tbody>
                    </table>
                </div>
                <TablePagination :pg="quarterPg" class="mt-2" />
            </template>
        </template>
        <div v-else class="py-8 text-center text-sm text-slate-400">暫無營收資料</div>
    </div>
</template>

<style scoped>
.chart-touch-surface {
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
}
</style>
