import { computed, onUnmounted, ref, watch } from "vue";
import type { ApiRequest } from "../../../shared/api/httpClient";
import { createGroupsApi } from "../api";
import type { GroupMember, StockGroup } from "../types";
import { createStocksApi } from "../../stocks/api";
import { isMarketOpen } from "../../stocks/utils/stockUtils";
import type { SnapshotItem, StockSearchItem } from "../../stocks/types";

/** 通知介面，只取用成功、警告與錯誤三種訊息能力。 */
export interface WorkspaceNotifier {
    success(message: string): void;
    warning(message: string): void;
    error(message: string): void;
}

/** 群組成員排序欄位。 */
export type MemberSortKey = "default" | "price" | "change" | "volume";

/**
 * 封裝群組工作區的狀態、搜尋、CRUD 與成員快照輪詢。
 * 讓 App.vue 只保留畫面組裝與 DOM 互動。
 */
export function useGroupWorkspace(options: { request: ApiRequest; notify: WorkspaceNotifier }) {
    const groupsApi = createGroupsApi(options.request);
    const stocksApi = createStocksApi(options.request);

    const groups = ref<StockGroup[]>([]);
    const members = ref<GroupMember[]>([]);
    const searchKeyword = ref("");
    const searchResults = ref<StockSearchItem[]>([]);
    const groupSearchKeyword = ref("");
    const selectedGroupId = ref("");
    const membersByGroup = ref<Map<string, Set<string>>>(new Map());
    const memberSnapshots = ref<Map<string, SnapshotItem>>(new Map());
    const memberSortKey = ref<MemberSortKey>("default");
    const memberSortDir = ref<"asc" | "desc">("desc");
    const newGroupName = ref("");
    const newGroupDescription = ref("");
    const isLoadingGroups = ref(false);
    const isLoadingMembers = ref(false);
    const isSearching = ref(false);
    const isShowingCreateForm = ref(false);
    const isSystemGroupsCollapsed = ref(false);
    const isSidebarCollapsed = ref(false);
    const editingGroupId = ref<string | null>(null);
    const editingGroupName = ref("");
    const editingGroupDescription = ref("");

    const selectedGroup = computed(() => groups.value.find((group) => group.id === selectedGroupId.value));
    const isSelectedSystemTemplate = computed(() => selectedGroup.value?.isSystemTemplate ?? false);
    const systemGroups = computed(() => groups.value.filter((group) => group.isSystemTemplate));
    const customGroups = computed(() => groups.value.filter((group) => !group.isSystemTemplate));
    const groupByName = computed(() => new Map(groups.value.map((group) => [group.name, group])));
    const isCustomGroupDragDisabled = computed(() => !!groupSearchKeyword.value.trim() || !!editingGroupId.value);
    const isMemberDragDisabled = computed(() => memberSortKey.value !== "default" || !!searchKeyword.value.trim() || isSelectedSystemTemplate.value);
    const filteredMembers = computed(() => {
        const keyword = searchKeyword.value.trim().toLowerCase();
        const list = keyword ? members.value.filter((member) => member.stockCode.toLowerCase().includes(keyword) || member.stockName.toLowerCase().includes(keyword)) : [...members.value];

        if (memberSortKey.value === "default" || memberSnapshots.value.size === 0) {
            return list;
        }

        return [...list].sort((a, b) => {
            const snapshotA = memberSnapshots.value.get(a.stockCode);
            const snapshotB = memberSnapshots.value.get(b.stockCode);
            let valueA = 0;
            let valueB = 0;

            if (memberSortKey.value === "price") {
                valueA = snapshotA?.lastPrice ?? snapshotA?.closePrice ?? 0;
                valueB = snapshotB?.lastPrice ?? snapshotB?.closePrice ?? 0;
            } else if (memberSortKey.value === "change") {
                valueA = snapshotA?.changePercent ?? 0;
                valueB = snapshotB?.changePercent ?? 0;
            } else if (memberSortKey.value === "volume") {
                valueA = snapshotA?.tradeVolume ?? 0;
                valueB = snapshotB?.tradeVolume ?? 0;
            }

            return memberSortDir.value === "desc" ? valueB - valueA : valueA - valueB;
        });
    });

    let searchTimer: number | undefined;
    let groupSearchTimer: number | undefined;
    let memberSnapshotTimer: number | undefined;

    /** 讀取群組清單並同步 membersByGroup 快取。 */
    async function loadGroups(keyword?: string) {
        isLoadingGroups.value = true;
        try {
            const data = await groupsApi.listGroups(keyword);
            groups.value = data;

            const hasSelectedGroup = data.some((group) => group.id === selectedGroupId.value);
            if (!hasSelectedGroup) {
                const customList = data.filter((group) => !group.isSystemTemplate);
                if (customList.length > 0) {
                    selectedGroupId.value = customList[0].id;
                } else if (data.length > 0) {
                    selectedGroupId.value = data[0].id;
                } else {
                    selectedGroupId.value = "";
                }
            }

            const customList = data.filter((group) => !group.isSystemTemplate);
            const results = await Promise.allSettled(customList.map((group) => groupsApi.listGroupMembers(group.id).then((list) => ({ id: group.id, list }))));
            const newMap = new Map<string, Set<string>>(membersByGroup.value);
            for (const result of results) {
                if (result.status === "fulfilled") {
                    newMap.set(result.value.id, new Set(result.value.list.map((member) => member.stockCode)));
                }
            }
            membersByGroup.value = newMap;
        } finally {
            isLoadingGroups.value = false;
        }
    }

    /** 載入指定群組的所有成員。 */
    async function loadMembers(groupId: string) {
        if (!groupId) {
            members.value = [];
            return;
        }

        isLoadingMembers.value = true;
        try {
            const list = await groupsApi.listGroupMembers(groupId);
            members.value = list;
            const newMap = new Map<string, Set<string>>(membersByGroup.value);
            newMap.set(groupId, new Set(list.map((member) => member.stockCode)));
            membersByGroup.value = newMap;
            startMemberSnapshotPolling();
        } finally {
            isLoadingMembers.value = false;
        }
    }

    /** 依關鍵字搜尋股票，供群組成員新增流程使用。 */
    async function searchStocks() {
        const keyword = searchKeyword.value.trim();
        if (!keyword) {
            searchResults.value = [];
            return;
        }

        isSearching.value = true;
        try {
            searchResults.value = await stocksApi.searchStocks(keyword, 20);
        } finally {
            isSearching.value = false;
        }
    }

    /** 建立新的自訂群組。 */
    async function createGroup() {
        const name = newGroupName.value.trim();
        if (!name) {
            options.notify.warning("請輸入群組名稱");
            return;
        }

        const duplicate = customGroups.value.some((group) => group.name === name);
        if (duplicate) {
            options.notify.error(`已存在名稱為「${name}」的自訂群組，請使用不同名稱。`);
            return;
        }

        await groupsApi.createGroup(name, newGroupDescription.value.trim());
        newGroupName.value = "";
        newGroupDescription.value = "";
        isShowingCreateForm.value = false;
        options.notify.success("已建立自訂群組");
        await loadGroups(groupSearchKeyword.value);
    }

    /** 將股票加入目前選取的自訂群組。 */
    async function addStockToGroup(stockCode: string) {
        if (!selectedGroupId.value) {
            options.notify.warning("請先選擇群組");
            return;
        }
        if (isSelectedSystemTemplate.value) {
            options.notify.warning("系統範本不可直接修改，請先複製成自訂群組");
            return;
        }

        await groupsApi.addStockToGroup(selectedGroupId.value, stockCode);
        options.notify.success(`已加入 ${stockCode}`);
        await loadMembers(selectedGroupId.value);
        await loadGroups(groupSearchKeyword.value);
    }

    /** 從目前選取的群組中移除股票。 */
    async function removeStock(stockCode: string) {
        if (!selectedGroupId.value) {
            return;
        }
        if (isSelectedSystemTemplate.value) {
            options.notify.warning("系統範本不可直接修改，請先複製成自訂群組");
            return;
        }

        await groupsApi.removeStockFromGroup(selectedGroupId.value, stockCode);
        options.notify.success(`已移除 ${stockCode}`);
        await loadMembers(selectedGroupId.value);
        await loadGroups(groupSearchKeyword.value);
    }

    /**
     * 將指定股票加入或移出指定自訂群組。
     */
    async function setStockInCustomGroup(groupId: string, stockCode: string, shouldInclude: boolean) {
        const targetGroup = groups.value.find((group) => group.id === groupId);
        if (!targetGroup) {
            options.notify.warning("找不到目標群組");
            return;
        }

        if (targetGroup.isSystemTemplate) {
            options.notify.warning("系統範本不可直接修改，請先複製成自訂群組");
            return;
        }

        const normalizedCode = stockCode.trim();
        if (!normalizedCode) {
            return;
        }

        const memberSet = membersByGroup.value.get(groupId);
        const alreadyInGroup = memberSet?.has(normalizedCode) ?? false;
        if (shouldInclude === alreadyInGroup) {
            return;
        }

        if (shouldInclude) {
            await groupsApi.addStockToGroup(groupId, normalizedCode);
            options.notify.success(`已將 ${normalizedCode} 加入「${targetGroup.name}」`);
        } else {
            await groupsApi.removeStockFromGroup(groupId, normalizedCode);
            options.notify.success(`已將 ${normalizedCode} 從「${targetGroup.name}」移除`);
        }

        if (selectedGroupId.value === groupId) {
            await loadMembers(groupId);
        }

        await loadGroups(groupSearchKeyword.value);
    }

    /** 複製目前選取的系統範本群組。 */
    async function copySelectedTemplate() {
        if (!selectedGroupId.value || !isSelectedSystemTemplate.value) {
            return;
        }

        const copiedGroup = await groupsApi.copyGroup(selectedGroupId.value);
        await loadGroups(groupSearchKeyword.value);
        selectedGroupId.value = copiedGroup.id;
        options.notify.success(`已複製範本為 ${copiedGroup.name}`);
    }

    /** 刪除指定群組。 */
    async function deleteGroup(groupId: string, groupName: string) {
        if (!globalThis.confirm(`確定要刪除「${groupName}」群組嗎？此操作無法復原。`)) {
            return;
        }

        await groupsApi.deleteGroup(groupId);
        options.notify.success(`已刪除「${groupName}」`);
        if (selectedGroupId.value === groupId) {
            selectedGroupId.value = "";
            members.value = [];
        }

        await loadGroups(groupSearchKeyword.value);
    }

    /** 將目前自訂群組排序寫回後端。 */
    async function persistCustomGroupOrder() {
        await groupsApi.updateCustomGroupOrder(customGroups.value.map((group) => group.id));
    }

    /** 將目前成員排序寫回後端。 */
    async function persistMemberOrder() {
        if (!selectedGroupId.value) {
            return;
        }
        await groupsApi.updateMemberOrder(
            selectedGroupId.value,
            members.value.map((member) => member.stockCode),
        );
    }

    /** 進入群組重新命名模式。 */
    function startRenameGroup(group: StockGroup) {
        editingGroupId.value = group.id;
        editingGroupName.value = group.name;
        editingGroupDescription.value = group.description ?? "";
    }

    /** 取消群組重新命名。 */
    function cancelRenameGroup() {
        editingGroupId.value = null;
        editingGroupName.value = "";
        editingGroupDescription.value = "";
    }

    /** 提交群組名稱與描述更新。 */
    async function submitRenameGroup(groupId: string) {
        const name = editingGroupName.value.trim();
        if (!name) {
            options.notify.warning("群組名稱不可為空白");
            return;
        }

        const duplicate = customGroups.value.some((group) => group.id !== groupId && group.name === name);
        if (duplicate) {
            options.notify.error(`已存在名稱為「${name}」的自訂群組，請使用不同名稱。`);
            return;
        }

        const updated = await groupsApi.renameGroup(groupId, name, editingGroupDescription.value.trim() || null);
        options.notify.success(`已更新群組「${updated.name}」`);
        cancelRenameGroup();
        await loadGroups(groupSearchKeyword.value);
    }

    /** 搜尋框按下 Enter 時，搜尋並將第一筆結果加入群組。 */
    async function handleSearchEnter() {
        if (!searchKeyword.value.trim()) {
            return;
        }

        await searchStocks();
        const firstResult = searchResults.value[0];
        if (!firstResult) {
            options.notify.warning("找不到可加入的股票");
            searchKeyword.value = "";
            return;
        }

        await addStockToGroup(firstResult.stockCode);
        searchKeyword.value = "";
    }

    /** 切換成員列表排序欄位。 */
    function toggleMemberSort(key: MemberSortKey) {
        if (memberSortKey.value === key) {
            memberSortDir.value = memberSortDir.value === "desc" ? "asc" : "desc";
            return;
        }

        memberSortKey.value = key;
        memberSortDir.value = "desc";
    }

    /** 取得目前群組成員的批次快照。 */
    async function fetchMemberSnapshots() {
        if (members.value.length === 0) {
            memberSnapshots.value = new Map();
            return;
        }

        try {
            const allSnapshots = await stocksApi.fetchAllSnapshots();
            const filtered = new Map<string, SnapshotItem>();
            for (const member of members.value) {
                const item = allSnapshots.get(member.stockCode.trim().toUpperCase());
                if (item) {
                    filtered.set(member.stockCode, item);
                }
            }
            memberSnapshots.value = filtered;
        } catch {
            // 靜默失敗，避免干擾主流程。
        }
    }

    /** 啟動成員快照輪詢。 */
    function startMemberSnapshotPolling() {
        stopMemberSnapshotPolling();
        void fetchMemberSnapshots();
        memberSnapshotTimer = globalThis.setInterval(() => {
            if (isMarketOpen()) {
                void fetchMemberSnapshots();
            }
        }, 3000);
    }

    /** 停止成員快照輪詢並清空資料。 */
    function stopMemberSnapshotPolling() {
        if (memberSnapshotTimer !== undefined) {
            globalThis.clearInterval(memberSnapshotTimer);
            memberSnapshotTimer = undefined;
        }
        memberSnapshots.value = new Map();
    }

    /** 將陣列中的元素從舊位置移動到新位置。 */
    function moveInArray<T>(list: T[], oldIndex: number, newIndex: number): T[] {
        const next = [...list];
        const [moved] = next.splice(oldIndex, 1);
        if (moved === undefined) {
            return next;
        }
        next.splice(newIndex, 0, moved);
        return next;
    }

    /** 處理自訂群組拖曳排序完成。 */
    async function onCustomGroupsSortEnd(oldIndex: number, newIndex: number) {
        if (oldIndex === newIndex) {
            return;
        }

        const reordered = moveInArray(customGroups.value, oldIndex, newIndex);
        groups.value = [...systemGroups.value, ...reordered];
        try {
            await persistCustomGroupOrder();
        } catch (error) {
            await loadGroups(groupSearchKeyword.value);
            options.notify.error(error instanceof Error ? error.message : "儲存群組排序失敗");
        }
    }

    /** 處理群組成員拖曳排序完成。 */
    async function onMembersSortEnd(oldIndex: number, newIndex: number) {
        if (oldIndex === newIndex) {
            return;
        }

        members.value = moveInArray(members.value, oldIndex, newIndex);
        try {
            await persistMemberOrder();
        } catch (error) {
            if (selectedGroupId.value) {
                await loadMembers(selectedGroupId.value);
            }
            options.notify.error(error instanceof Error ? error.message : "儲存成員排序失敗");
        }
    }

    /** 初始化群組工作區。 */
    async function initializeGroupWorkspace() {
        await loadGroups(groupSearchKeyword.value);
    }

    /** 清空群組工作區狀態，供登出使用。 */
    function resetGroupWorkspace() {
        groups.value = [];
        members.value = [];
        searchResults.value = [];
        selectedGroupId.value = "";
        membersByGroup.value = new Map();
        stopMemberSnapshotPolling();
    }

    watch(searchKeyword, () => {
        if (searchTimer !== undefined) {
            globalThis.clearTimeout(searchTimer);
        }

        searchTimer = globalThis.setTimeout(() => {
            void searchStocks();
        }, 280);
    });

    watch(groupSearchKeyword, (keyword) => {
        if (groupSearchTimer !== undefined) {
            globalThis.clearTimeout(groupSearchTimer);
        }

        groupSearchTimer = globalThis.setTimeout(() => {
            void loadGroups(keyword);
        }, 280);
    });

    watch(selectedGroupId, (groupId) => {
        stopMemberSnapshotPolling();
        void loadMembers(groupId);
    });

    onUnmounted(() => {
        if (searchTimer !== undefined) {
            globalThis.clearTimeout(searchTimer);
        }
        if (groupSearchTimer !== undefined) {
            globalThis.clearTimeout(groupSearchTimer);
        }
        stopMemberSnapshotPolling();
    });

    return {
        groups,
        members,
        searchKeyword,
        searchResults,
        groupSearchKeyword,
        selectedGroupId,
        membersByGroup,
        memberSnapshots,
        memberSortKey,
        memberSortDir,
        newGroupName,
        newGroupDescription,
        isLoadingGroups,
        isLoadingMembers,
        isSearching,
        isShowingCreateForm,
        isSystemGroupsCollapsed,
        isSidebarCollapsed,
        editingGroupId,
        editingGroupName,
        editingGroupDescription,
        selectedGroup,
        isSelectedSystemTemplate,
        systemGroups,
        customGroups,
        groupByName,
        isCustomGroupDragDisabled,
        isMemberDragDisabled,
        filteredMembers,
        loadGroups,
        loadMembers,
        searchStocks,
        createGroup,
        addStockToGroup,
        removeStock,
        setStockInCustomGroup,
        copySelectedTemplate,
        deleteGroup,
        startRenameGroup,
        cancelRenameGroup,
        submitRenameGroup,
        handleSearchEnter,
        toggleMemberSort,
        initializeGroupWorkspace,
        resetGroupWorkspace,
        stopMemberSnapshotPolling,
        onCustomGroupsSortEnd,
        onMembersSortEnd,
    };
}
