import { computed, ref, watch } from "vue";
import type { ComputedRef, Ref } from "vue";

export const PAGE_SIZE_OPTIONS = [20, 50, 100] as const;

/** 傳入 TablePagination 元件的分頁控制介面。 */
export interface PaginationControls {
    pageSizeInput: Ref<string>;
    currentPage: Ref<number>;
    showAll: ComputedRef<boolean>;
    pageSize: ComputedRef<number>;
    totalPages: ComputedRef<number>;
    totalCount: ComputedRef<number>;
}

/**
 * 通用分頁 composable。
 * @param source 已排序的來源資料（Ref 或 ComputedRef）
 * @param defaultSize 預設每頁筆數，預設 20
 */
export function usePagination<T>(source: Ref<T[]> | ComputedRef<T[]>, defaultSize = 20) {
    const pageSizeInput = ref<string>(String(defaultSize));
    const currentPage = ref(1);

    const showAll = computed(() => pageSizeInput.value === "" || Number(pageSizeInput.value) <= 0);

    const pageSize = computed((): number => {
        if (showAll.value) return Infinity;
        const n = Number.parseInt(pageSizeInput.value, 10);
        return Number.isNaN(n) || n <= 0 ? defaultSize : n;
    });

    const totalCount = computed(() => source.value.length);

    const totalPages = computed(() => (Number.isFinite(pageSize.value) ? Math.max(1, Math.ceil(totalCount.value / pageSize.value)) : 1));

    const pagedRows = computed(() => {
        if (Number.isFinite(pageSize.value)) {
            const start = (currentPage.value - 1) * pageSize.value;
            return source.value.slice(start, start + pageSize.value);
        }
        return source.value;
    });

    // 資料筆數變化導致總頁數縮減時，修正頁碼
    watch(totalPages, (n) => {
        if (currentPage.value > n) currentPage.value = n;
    });

    // 每頁筆數變更時重設至第一頁
    watch(pageSize, () => {
        currentPage.value = 1;
    });

    /** 重設至第一頁（切換檢視模式時使用）。 */
    function reset() {
        currentPage.value = 1;
    }

    const controls: PaginationControls = { pageSizeInput, currentPage, showAll, pageSize, totalPages, totalCount };
    return { ...controls, pagedRows, reset };
}
