/** 指標面板排列順序（可拖曳調整）：large/small/main_force 固定在末尾，決定子圖順序 */
const DEFAULT_PANEL_ORDER: IndicatorKey[] = ["bb", "rsi", "macd", "kd", "dmi", "small", "large", "main_force", "inst_dealer", "inst_hedging", "inst_trust", "inst_foreign"];
const DEFAULT_PANEL_ORDER_INDEX = new Map(DEFAULT_PANEL_ORDER.map((key, index) => [key, index] as const));

const panelOrder = ref<IndicatorKey[]>([...DEFAULT_PANEL_ORDER]);

function isIndicatorKey(value: string): value is IndicatorKey {
    return DEFAULT_PANEL_ORDER.includes(value as IndicatorKey);
}

function mergePanelOrder(savedOrder: string[]): IndicatorKey[] {
    const merged: IndicatorKey[] = [];
    const seen = new Set<IndicatorKey>();

    for (const key of savedOrder) {
        if (isIndicatorKey(key) && !seen.has(key)) {
            merged.push(key);
            seen.add(key);
        }
    }

    for (const key of DEFAULT_PANEL_ORDER) {
        if (seen.has(key)) continue;

        const targetIndex = DEFAULT_PANEL_ORDER_INDEX.get(key) ?? DEFAULT_PANEL_ORDER.length;
        let insertAt = merged.length;
        for (let i = 0; i < merged.length; i++) {
            const currentIndex = DEFAULT_PANEL_ORDER_INDEX.get(merged[i]) ?? DEFAULT_PANEL_ORDER.length;
            if (currentIndex > targetIndex) {
                insertAt = i;
                break;
            }
        }

        merged.splice(insertAt, 0, key);
        seen.add(key);
    }

    return merged;
}

