/**
 * 點擊外部時關閉所有下拉（使用元素包含檢測，避免 Teleport 導致的 stopPropagation 失效問題）
 * @param event 鼠標點擊事件
 */
function handleDocumentClick(event: MouseEvent) {
    const target = event.target as Node;
    // 點在觸發按鈕上，由 openIndicatorDropdown 自行處理 toggle
    if (techTriggerRef.value?.contains(target) || holderTriggerRef.value?.contains(target) || instTriggerRef.value?.contains(target)) return;
    // 點在開啟的下拉內容上，不關閉
    if (techDropdownRef.value?.contains(target) || holderDropdownRef.value?.contains(target) || instDropdownRef.value?.contains(target)) return;
    closeAllDropdowns();
}

/**
 * 計算觸發按鈕位置後開啟指標下拉（透過 Teleport 掛到 body，避免 overflow 容器剪裁）。
 * @param triggerEl 觸發按鈕 DOM 元素
 * @param key 下拉選單識別鍵
 */
function openIndicatorDropdown(triggerEl: HTMLElement | null, key: DropdownKey) {
    if (openDropdown.value === key) {
        openDropdown.value = null;
        openParamPanel.value = null;
        return;
    }
    if (triggerEl) {
        const rect = triggerEl.getBoundingClientRect();
        teleportDropdownStyle.value = { top: `${rect.bottom + 4}px`, left: `${rect.left}px` };
    }
    openDropdown.value = key;
    openParamPanel.value = null;
}

