    if (!panel) return; // 沒有開啟任何面板，直接返回
    // 依目前開啟的面板，將草稿值寫回對應的響應式參數物件
    if (panel === "bb") bbParams.value = { period: Number(draftParams.value.period), multiplier: Number(draftParams.value.multiplier) };
    else if (panel === "rsi") rsiParams.value = { period: Number(draftParams.value.period), period2: Number(draftParams.value.period2) };
    else if (panel === "macd") macdParams.value = { lengthMA: Number(draftParams.value.lengthMA), lengthSignal: Number(draftParams.value.lengthSignal) };
    else if (panel === "kd") kdParams.value = { kPeriod: Number(draftParams.value.kPeriod), dPeriod: Number(draftParams.value.dPeriod), slowing: Number(draftParams.value.slowing) };
    else if (panel === "dmi") dmiParams.value = { diLen: Number(draftParams.value.diLen), adxLen: Number(draftParams.value.adxLen) };
    openParamPanel.value = null; // 關閉參數面板
    redraw(); // 以新參數重新計算指標並更新 ECharts 圖表
}

