/**
 * 計算移動平均線（MA - Moving Average）。
 *
 * 功能說明：
 *   - 計算指定天數的簡單移動平均（SMA）
 *   - 用於平滑價格波動，識別趨勢方向
 *   - 常見配置：MA5（短期）、MA10（中期）、MA20（長期）
 *
 * 特殊處理：
 *   - 資料不足 `days` 筆時返回 "-" 字符
 *   - ECharts 會自動跳過這些缺值，不在圖表上顯示
 *   - 遇到 null 值會中止當前計算，返回 "-"
 *
 * @param values 收盤價陣列（可能包含 null 代表缺失數據）
 * @param days 移動平均天數（如 5/10/20）
 * @returns 計算結果陣列，每個值為平均價格或 "-" 表示無法計算
 */
function calculateMA(values: (number | null)[], days: number): (number | "-")[] {
    const result: (number | "-")[] = [];
    for (let i = 0; i < values.length; i++) {
        if (i < days - 1) {
            result.push("-");
            continue;
        }
        let sum = 0;
        let valid = true;
        for (let j = 0; j < days; j++) {
            const v = values[i - j];
            if (v === null || v === undefined) {
                valid = false;
                break;
            }
            sum += v;
        }
        result.push(valid ? sum / days : "-");
    }
    return result;
}

/**
 * 計算布林通道（Bollinger Bands）。
 *
 * 理論說明：
 *   - 布林通道由三條線組成：上軌、中軌、下軌
 *   - 中軌 = MA(period)：指定周期的移動平均
 *   - 上軌 = MA + (multiplier × σ)：均值加上標準差倍數
 *   - 下軌 = MA - (multiplier × σ)：均值減去標準差倍數
 *
 * 應用場景：
 *   - 識別價格波動率（σ 越大越波動）
 *   - 判斷支撐/阻力位置（通常價格會在通道內反彈）
 *   - 檢測極端價格（超出通道表示異常波動）
 *
 * 預設配置：MA20 + 2σ 是最常用的布林通道設定
 *
 * @param values 收盤價陣列（可能含 null 缺值）
 * @param period 計算週期（預設 20 天）
 * @param multiplier 標準差倍數（預設 2，常見值 1-3）
 * @returns 包含上軌、中軌、下軌的計算結果
 */
function calculateBollingerBands(values: (number | null)[], period = 20, multiplier = 2): { upper: (number | "-")[]; middle: (number | "-")[]; lower: (number | "-")[] } {
    const upper: (number | "-")[] = [];
    const middle: (number | "-")[] = [];
    const lower: (number | "-")[] = [];

    for (let i = 0; i < values.length; i++) {
        if (i < period - 1) {
            upper.push("-");
            middle.push("-");
            lower.push("-");
            continue;
        }
        const window: number[] = [];
        let valid = true;
        for (let j = 0; j < period; j++) {
            const v = values[i - j];
            if (v === null || v === undefined) {
                valid = false;
                break;
            }
            window.push(v);
        }
        if (!valid) {
            upper.push("-");
            middle.push("-");
            lower.push("-");
            continue;
        }
        const mean = window.reduce((a, b) => a + b, 0) / period;
        const variance = window.reduce((a, b) => a + (b - mean) ** 2, 0) / period;
        const stddev = Math.sqrt(variance);
        upper.push(Number.parseFloat((mean + multiplier * stddev).toFixed(2)));
        middle.push(Number.parseFloat(mean.toFixed(2)));
        lower.push(Number.parseFloat((mean - multiplier * stddev).toFixed(2)));
    }

    return { upper, middle, lower };
}

/**
 * 計算 RSI 相對強弱指標（Relative Strength Index）。
 *
 * 理論說明：
 *   - RSI 衡量價格上升動能與下降動能的相對強度
 *   - 取值範圍：0-100
 *   - RSI = 100 - (100 / (1 + RS))，其中 RS = 平均上升幅度 / 平均下降幅度
 *   - 使用 Wilder 平滑法（EMA 版本），這是 J. Welles Wilder Jr. 的原始公式
 *
 * 信號解讀：
 *   - RSI > 70：通常表示超買狀態（可能面臨回調）
 *   - RSI < 30：通常表示超賣狀態（可能面臨反彈）
 *   - RSI 50：中性狀態，無明確方向
 *
 * 常見周期：14（標準）、10（敏感）、21（遲鈍）
 *
 * @param values 收盤價陣列
 * @param period RSI 計算周期
 * @returns RSI 值（0-100）或 "-" 表示無法計算
 */
function calculateRSI(values: (number | null)[], period: number): (number | "-")[] {
    const result: (number | "-")[] = [];
    const changes: number[] = [];
    for (let i = 1; i < values.length; i++) {
        const cur = values[i];
        const prev = values[i - 1];
        changes.push(cur !== null && prev !== null ? cur - prev : 0);
    }
    result.push("-"); // 第一筆無法計算
    let avgGain = 0;
    let avgLoss = 0;
    for (let i = 0; i < period && i < changes.length; i++) {
        const c = changes[i];
        if (c > 0) avgGain += c;
        else avgLoss += Math.abs(c);
    }
    avgGain /= period;
    avgLoss /= period;
    for (let i = 1; i <= period && i < changes.length + 1; i++) result.push("-");
    for (let i = period; i < changes.length; i++) {
        const c = changes[i];
        avgGain = (avgGain * (period - 1) + Math.max(c, 0)) / period;
        avgLoss = (avgLoss * (period - 1) + Math.max(-c, 0)) / period;
        const rs = avgLoss === 0 ? 100 : avgGain / avgLoss;
        result.push(Number.parseFloat((100 - 100 / (1 + rs)).toFixed(2)));
    }
    return result;
}

/**
 * 計算 EMA（指數移動平均）。
 */
/**
 * 計算 EMA (Exponential Moving Average) 指數移動平均
 *
 * 算法原理:
 *   EMA[t] = Price[t] * k + EMA[t-1] * (1-k)
 *   其中 k = 2/(period+1) 為平滑係數
 *   期數越小，最新數據的權重越高，反應越快
 *
 * 計算步驟:
 *   1. 計算平滑係數 k
 *   2. 逐個遍歷價格陣列
 *   3. 遇到 null 直接跳過
 *   4. 首個有效值作為初始 EMA
 *   5. 後續值根據公式遞進計算
 *
 * @param values 收盤價陣列
 * @param period 計算週期
 * @return EMA 計算結果陣列
 */
function calculateEMA(values: (number | null)[], period: number): (number | null)[] {
    const k = 2 / (period + 1); // 計算平滑係數
    const result: (number | null)[] = [];
    let ema: number | null = null; // 當前 EMA 值緩存

    for (const v of values) {
        if (v === null) {
            result.push(null); // null 值傳透到結果
            continue;
        }

        if (ema === null) {
            // 首個有效數據點直接賦值
            ema = v;
        } else {
            // 套用 EMA 遞推公式
            ema = v * k + ema * (1 - k);
        }

        result.push(ema);
    }

    return result;
}

/**
 * Smoothed Moving Average (SMMA) - 平滑移動平均
 *
 * Pine Script 公式:
 *   smma[t] = na(smma[t-1]) ? SMA(first len values) : (smma[t-1] * (len-1) + src[t]) / len
 *
 * 特點:
 *   - 比 EMA 更平滑，用 Wilder 平滑法
 *   - 對價格變動反應較EMA稍慢
 *   - 適合識別中長期趨勢
 *
 * 應用:
 *   - Impulse MACD 中計算最高點/最低點追蹤
 *   - 配合 ZLEMA 生成更精確的動量指標
 *
 * @param values 原始價格陣列
 * @param len 計算週期
 * @return SMMA 計算結果
 */
function calculateSMMA(values: (number | null)[], len: number): (number | null)[] {
    const result: (number | null)[] = [];
    let smma: number | null = null; // 當前 SMMA 值快取
    let seedCount = 0; // 用於計算初始 SMA 的計數器
    let seedSum = 0; // 用於計算初始 SMA 的累計和

    for (const v of values) {
        if (v === null) {
            result.push(null); // null 值傳透
            continue;
        }

        if (smma === null) {
            // 累計前 len 個值以計算初始 SMA
            seedCount++;
            seedSum += v;

            if (seedCount < len) {
                // 尚未累計足夠值，返回 null
                result.push(null);
            } else {
                // 初始化 SMMA 為 SMA
                smma = seedSum / len;
                result.push(smma);
            }
        } else {
            // 套用 SMMA 平滑公式: (前期*len + 當前值) / len
            smma = (smma * (len - 1) + v) / len;
            result.push(smma);
        }
    }

    return result;
}

/**
 * Zero-Lag EMA (ZLEMA) - 零滯後指數移動平均
 *
 * Pine Script 公式:
 *   ema1 = EMA(src, length)
 *   ema2 = EMA(ema1, length)
 *   d = ema1 - ema2  (去滯差值)
 *   zlema = ema1 + d  (加回差值消除滯後)
 *
 * 效果:
 *   - 比普通 EMA 提前反應趨勢變化
 *   - 減少指標的滯後效應
 *   - 更快捷取到趨勢反向點
 *
 * 應用:
 *   - Impulse MACD 的核心計算
 *   - 用於更敏銳的動量指標
 *
 * @param values 原始數據
 * @param length 計算週期
 * @return ZLEMA 計算結果
 */
function calculateZLEMA(values: (number | null)[], length: number): (number | null)[] {
    // 先計算第一層 EMA
    const ema1 = calculateEMA(values, length);
    // 再對第一層 EMA 計算第二層 EMA
    const ema2 = calculateEMA(ema1, length);

    // 套用零滯後公式: zlema = ema1 + (ema1 - ema2)
    return ema1.map((e1, i) => {
        const e2 = ema2[i];
        if (e1 === null || e2 === null) return null;
        // 加上滯後差值以消除延遲
        return e1 + (e1 - e2);
    });
}

/**
 * Impulse MACD by LazyBear。
 * src = hlc3 = (H+L+C)/3
 * hi  = SMMA(high, lengthMA)
 * lo  = SMMA(low,  lengthMA)
 * mi  = ZLEMA(src, lengthMA)
 * md  = mi>hi ? mi-hi : mi<lo ? mi-lo : 0   (ImpulseMACD)
 * sb  = SMA(md, lengthSignal)               (Signal)
 * sh  = md - sb                             (ImpulseHisto)
 */
function calculateImpulseMACD(
    highs: (number | null)[],
    lows: (number | null)[],
    closes: (number | null)[],
    lengthMA: number,
    lengthSignal: number,
): {
    md: (number | "-")[];
    sb: (number | "-")[];
    sh: (number | "-")[];
    mdColors: string[];
} {
    const src = closes.map((c, i) => {
        const h = highs[i];
        const l = lows[i];
        return c !== null && h !== null && l !== null ? (h + l + c) / 3 : null;
    });

    const hi = calculateSMMA(highs as (number | null)[], lengthMA);
    const lo = calculateSMMA(lows as (number | null)[], lengthMA);
    const mi = calculateZLEMA(src, lengthMA);

    const mdRaw: (number | null)[] = mi.map((miV, i) => {
        const hiV = hi[i];
        const loV = lo[i];
        if (miV === null || hiV === null || loV === null) return null;
        if (miV > hiV) return miV - hiV;
        if (miV < loV) return miV - loV;
        return 0;
    });

    // SMA(md, lengthSignal)
    const sbRaw: (number | null)[] = mdRaw.map((_, i) => {
        if (i < lengthSignal - 1) return null;
        let sum = 0;
        for (let j = i - lengthSignal + 1; j <= i; j++) {
            const m = mdRaw[j];
            if (m === null) return null;
            sum += m;
        }
        return sum / lengthSignal;
    });

    const shRaw: (number | null)[] = mdRaw.map((m, i) => {
        const s = sbRaw[i];
        return m !== null && s !== null ? m - s : null;
    });

    // md 顏色：src > mi && src > hi → lime、src > mi → green、src < lo → red、else → orange
    const mdColors: string[] = closes.map((c, i) => {
        const miV = mi[i];
        const hiV = hi[i];
        const loV = lo[i];
        if (c === null || miV === null || hiV === null || loV === null) return "#94a3b8";
        if (c > miV && c > hiV) return "#00e676";
        if (c > miV) return "#26a69a";
        if (c < loV) return "#ef5350";
        return "#ffa726";
    });

    const toSeries = (raw: (number | null)[]): (number | "-")[] => raw.map((v) => (v === null ? "-" : Number.parseFloat(v.toFixed(3))));

    return { md: toSeries(mdRaw), sb: toSeries(sbRaw), sh: toSeries(shRaw), mdColors };
}

/**
 * 計算 KD 隨機指標（Stochastic Oscillator）。
 *
 * 理論說明：
 *   1. RSV（原始隨機值）= (Close - LowestLow) / (HighestHigh - LowestLow) × 100
 *      表示收盤價在最近 kPeriod 日內的相對位置（0-100）
 *   2. K = 對 RSV 應用平滑（EMA）
 *   3. D = 對 K 應用進一步平滑（EMA）
 *
 * 參數說明：
 *   - kPeriod：計算 RSV 時的回溯天數（通常 9 或 14）
 *   - slowing：K 值平滑週期（通常 3）
 *   - dPeriod：D 值平滑週期（通常 3）
 *
 * 信號解讀：
 *   - K > D：向上動能（K 線穿過 D 線上方為買入信號）
 *   - K < D：向下動能（K 線穿過 D 線下方為賣出信號）
 *   - K/D > 80：超買區間（可能面臨下跌）
 *   - K/D < 20：超賣區間（可能面臨上漲）
 *
 * @param highs 指定周期最高價陣列
 * @param lows 指定周期最低價陣列
 * @param closes 收盤價陣列
 * @param kPeriod K 值回溯周期
 * @param dPeriod D 值平滑周期
 * @param slowing 平滑週期
 * @returns 包含 K 值與 D 值的計算結果
 */
function calculateKD(highs: (number | null)[], lows: (number | null)[], closes: (number | null)[], kPeriod: number, dPeriod: number, slowing: number): { k: (number | "-")[]; d: (number | "-")[] } {
    const kArr: (number | "-")[] = [];
    const dArr: (number | "-")[] = [];
    let kVal = 50;
    let dVal = 50;
    const kSmooth = 1 / slowing;
    const dSmooth = 1 / dPeriod;

    for (let i = 0; i < closes.length; i++) {
        if (i < kPeriod - 1) {
            kArr.push("-");
            dArr.push("-");
            continue;
        }
        let high = -Infinity;
        let low = Infinity;
        for (let j = i - kPeriod + 1; j <= i; j++) {
            const h = highs[j];
            const l = lows[j];
            if (h !== null) high = Math.max(high, h);
            if (l !== null) low = Math.min(low, l);
        }
        const close = closes[i];
        if (close === null || high === low) {
            kArr.push("-");
            dArr.push("-");
            continue;
        }
        const rsv = ((close - low) / (high - low)) * 100;
        kVal = kVal * (1 - kSmooth) + rsv * kSmooth;
        dVal = dVal * (1 - dSmooth) + kVal * dSmooth;
        kArr.push(Number.parseFloat(kVal.toFixed(2)));
        dArr.push(Number.parseFloat(dVal.toFixed(2)));
    }
    return { k: kArr, d: dArr };
}

/**
 * 計算 KD 背景分段：K > D 時為綠色區段，K < D 時為紅色區段。
 * 用於 ECharts markArea 背景色。
 */
function computeKDMarkAreaData(kArr: (number | "-")[], dArr: (number | "-")[], dates: string[]): [{ xAxis: string; itemStyle: { color: string } }, { xAxis: string }][] {
    const result: [{ xAxis: string; itemStyle: { color: string } }, { xAxis: string }][] = [];
    let curState: "gt" | "lt" | null = null;
    let segStart = 0;

    const flush = (end: number) => {
        if (curState === null) return;
        result.push([{ xAxis: dates[segStart], itemStyle: { color: curState === "gt" ? "rgba(0,218,60,0.12)" : "rgba(236,0,0,0.12)" } }, { xAxis: dates[end] }]);
    };

    for (let i = 0; i < dates.length; i++) {
        const k = kArr[i];
        const d = dArr[i];
        if (k === "-" || d === "-") {
            flush(i - 1);
            curState = null;
            continue;
        }
        const newState: "gt" | "lt" = k >= d ? "gt" : "lt";
        if (newState !== curState) {
            flush(i - 1);
            curState = newState;
            segStart = i;
        }
    }
    if (dates.length > 0) flush(dates.length - 1);
    return result;
}

/**
 * 計算 DMI 方向性移動指標（Directional Movement Index）。
 *
 * 理論說明：
 *   - DMI 由三條線組成：+DI（上升方向）、-DI（下降方向）、ADX（趨勢強度）
 *   - 用於判斷價格移動的方向性和趨勢強度
 *
 * 計算流程：
 *   1. +DM：計算本期高點與上期高點差值（向上移動）
 *   2. -DM：計算上期低點與本期低點差值（向下移動）
 *   3. TR（真實波幅）= max(H-L, H-PC, L-PC)，PC 為前收盤價
 *   4. +DI = 平滑(+DM) / 平滑(TR) × 100
 *   5. -DI = 平滑(-DM) / 平滑(TR) × 100
 *   6. ADX = 平滑(DX)，DX = abs(+DI - -DI) / (+DI + -DI) × 100
 *
 * 平滑方法：使用 Wilder RMA（威爾德相對移動平均）
 * 對應 Pine Script 的 ta.dmi 標準實作
 *
 * 信號解讀：
 *   - +DI > -DI：上升趨勢（+DI 向上穿 -DI 為強買信號）
 *   - +DI < -DI：下降趨勢（-DI 向上穿 +DI 為強賣信號）
 *   - ADX > 25：趨勢強度高（強勢市場）
 *   - ADX < 20：趨勢強度低（盤整市場）
 */

/** Wilder RMA（從 index 1 開始種子 SMA，之後 EMA-style 平滑）。 */
function wilderRMA(arr: number[], period: number): (number | null)[] {
    const n = arr.length;
    const res: (number | null)[] = new Array(n).fill(null);
    if (n < period + 1) return res;
    let seed = 0;
    for (let i = 1; i <= period; i++) seed += arr[i];
    res[period] = seed / period;
    for (let i = period + 1; i < n; i++) {
        res[i] = ((res[i - 1] as number) * (period - 1) + arr[i]) / period;
    }
    return res;
}

/** 從指定起始位置計算 ADX（Wilder RMA of DX，seeded from offset）。 */
function calcADX(dxArr: number[], offset: number, adxLen: number): (number | null)[] {
    const n = dxArr.length;
    const adxRaw: (number | null)[] = new Array(n).fill(null);
    const seedEnd = offset + adxLen;
    if (seedEnd > n) return adxRaw;
    let seed = 0;
    for (let i = offset; i < seedEnd; i++) seed += dxArr[i];
    adxRaw[seedEnd - 1] = seed / adxLen;
    for (let i = seedEnd; i < n; i++) {
        adxRaw[i] = ((adxRaw[i - 1] as number) * (adxLen - 1) + dxArr[i]) / adxLen;
    }
    return adxRaw;
}

function calculateDMI(highs: (number | null)[], lows: (number | null)[], closes: (number | null)[], diLen: number, adxLen: number): { plus: (number | "-")[]; minus: (number | "-")[]; adx: (number | "-")[] } {
    const n = highs.length;
    const trArr: number[] = new Array(n).fill(0);
    const plusDMArr: number[] = new Array(n).fill(0);
    const minusDMArr: number[] = new Array(n).fill(0);

    for (let i = 1; i < n; i++) {
        const h = highs[i];
        const l = lows[i];
        const prevH = highs[i - 1];
        const prevL = lows[i - 1];
        const prevC = closes[i - 1];
        if (h === null || l === null || prevH === null || prevL === null || prevC === null) continue;
        trArr[i] = Math.max(h - l, Math.abs(h - prevC), Math.abs(l - prevC));
        const up = h - prevH;
        const down = prevL - l;
        plusDMArr[i] = up > down && up > 0 ? up : 0;
        minusDMArr[i] = down > up && down > 0 ? down : 0;
    }

    const trRMA = wilderRMA(trArr, diLen);
    const plusRMA = wilderRMA(plusDMArr, diLen);
    const minusRMA = wilderRMA(minusDMArr, diLen);

    const plusDI: (number | "-")[] = new Array(n).fill("-");
    const minusDI: (number | "-")[] = new Array(n).fill("-");
    const dxArr: number[] = new Array(n).fill(0);

    for (let i = diLen; i < n; i++) {
        const tr = trRMA[i];
        const p = plusRMA[i];
        const m = minusRMA[i];
        if (tr === null || p === null || m === null || tr === 0) continue;
        const pdi = (p / tr) * 100;
        const mdi = (m / tr) * 100;
        plusDI[i] = Number.parseFloat(pdi.toFixed(2));
        minusDI[i] = Number.parseFloat(mdi.toFixed(2));
        const s = pdi + mdi;
        dxArr[i] = s > 0 ? (Math.abs(pdi - mdi) / s) * 100 : 0;
    }

    const adxRaw = calcADX(dxArr, diLen, adxLen);
    const adx: (number | "-")[] = adxRaw.map((v) => (v === null ? "-" : Number.parseFloat(v.toFixed(2))));
    return { plus: plusDI, minus: minusDI, adx };
}

/**
 * 計算 DMI 背景分段：+DI > -DI 時為綠色，否則為紅色。
 */
function computeDMIMarkAreaData(plusArr: (number | "-")[], minusArr: (number | "-")[], dates: string[]): [{ xAxis: string; itemStyle: { color: string } }, { xAxis: string }][] {
    const result: [{ xAxis: string; itemStyle: { color: string } }, { xAxis: string }][] = [];
    let curState: "bull" | "bear" | null = null;
    let segStart = 0;

    const flush = (end: number) => {
        if (curState === null || end < 0) return;
        result.push([{ xAxis: dates[segStart], itemStyle: { color: curState === "bull" ? "rgba(0,218,60,0.12)" : "rgba(236,0,0,0.12)" } }, { xAxis: dates[end] }]);
    };

    for (let i = 0; i < dates.length; i++) {
        const p = plusArr[i];
        const m = minusArr[i];
        if (p === "-" || m === "-") {
            flush(i - 1);
            curState = null;
            continue;
        }
        const newState: "bull" | "bear" = p >= m ? "bull" : "bear";
        if (newState !== curState) {
            flush(i - 1);
            curState = newState;
            segStart = i;
        }
    }
    if (dates.length > 0 && curState !== null) flush(dates.length - 1);
    return result;
}

// ─── 持股分級輔助函式 ──────────────────────────────────────────

/** 大戶持股分級：minZhang >= threshold 的分級集合 */
function getLargeHolderLevels(threshold: number): Set<string> {
    return new Set(HOLDING_LEVEL_META.filter((m) => m.minZhang >= threshold).map((m) => m.level));
}

/** 散戶持股分級：maxZhang > 0 && maxZhang <= threshold 的分級集合 */
function getSmallHolderLevels(threshold: number): Set<string> {
    return new Set(HOLDING_LEVEL_META.filter((m) => m.maxZhang > 0 && m.maxZhang <= threshold).map((m) => m.level));
}

/**
 * 以後向填充（backward fill）將持股分級資料對齊 K 線日期。
 * 持股資料為每週一筆，每個交易日使用「當週結算日（含）之後最近一筆」資料。
 * 若當週尚未結束而無後續結算資料，則該日留空不填。
 */
function buildForwardFilledHoldingData(klineDates: string[]): Map<string, Map<string, number>> {
    const holdingByDate = new Map<string, Map<string, number>>();
    for (const item of holdingSharesData.value) {
        if (!holdingByDate.has(item.date)) holdingByDate.set(item.date, new Map());
        holdingByDate.get(item.date)!.set(item.holdingSharesLevel, item.percent);
    }
    const sortedHoldingDates = [...holdingByDate.keys()].sort();
    const result = new Map<string, Map<string, number>>();
    for (const kDate of klineDates) {
        // 找到第一個 >= kDate 的持股結算日（後向填充）
        const hDate = sortedHoldingDates.find((d) => d >= kDate);
        if (hDate) result.set(kDate, holdingByDate.get(hDate)!);
        // 若當週尚未結算，無後續資料則留空
    }
    return result;
}

/** 計算指定分級集合在各 K 線日期的累計持股占比（%），未有資料時回傳 "-" */
function computeHoldingSeriesData(filledData: Map<string, Map<string, number>>, klineDates: string[], levelSet: Set<string>): (number | "-")[] {
    return klineDates.map((date) => {
        const levelMap = filledData.get(date);
        if (!levelMap) return "-";
        let sum = 0;
        for (const [level, pct] of levelMap) {
            if (levelSet.has(level)) sum += pct;
        }
        return Number.parseFloat(sum.toFixed(2));
    });
}

/** 判斷持股占比週增減的線條顏色（台灣慣例：增加=紅、減少=綠） */
function getHoldingChangeColor(curVal: number, prevVal: number): string {
    if (curVal > prevVal) return "#ef4444";
    if (curVal < prevVal) return "#22c55e";
    return "#94a3b8";
}

/** 依線條顏色回傳對應半透明面積填色 */
function getHoldingAreaColor(lineColor: string): string {
    if (lineColor === "#ef4444") return "rgba(239,68,68,0.35)";
    if (lineColor === "#22c55e") return "rgba(34,197,94,0.35)";
    return "rgba(148,163,184,0.2)";
}

/** 加總指定持股日期在 levelSet 分級中的占比 */
function sumHoldingPercent(holdingByDate: Map<string, Map<string, number>>, date: string, levelSet: Set<string>): number {
    const m = holdingByDate.get(date);
    if (!m) return 0;
    let s = 0;
    for (const [lv, pct] of m) if (levelSet.has(lv)) s += pct;
    return s;
}

/** 計算各持股週期的顏色分段（startIdx/endIdx 為 klineDates 索引）
 *  配合後向填充：結算日 Sn 涵蓋 K 線日期為 (S(n-1), Sn]，
 *  顏色依「本週 vs 上週」漲跌決定（增加紅、減少綠、持平灰）。
 */
function computeHoldingSegments(klineDates: string[], levelSet: Set<string>): { startIdx: number; endIdx: number; lineColor: string; areaColor: string }[] {
    const holdingByDate = new Map<string, Map<string, number>>();
    for (const item of holdingSharesData.value) {
        if (!holdingByDate.has(item.date)) holdingByDate.set(item.date, new Map());
        holdingByDate.get(item.date)!.set(item.holdingSharesLevel, item.percent);
    }
    const allHoldingDates = [...holdingByDate.keys()].sort();
    const segments: { startIdx: number; endIdx: number; lineColor: string; areaColor: string }[] = [];

    for (let hi = 0; hi < allHoldingDates.length; hi++) {
        const curDate = allHoldingDates[hi];
        const prevDate = hi > 0 ? allHoldingDates[hi - 1] : null;

        // 後向填充：結算日 curDate 對應的 K 線範圍為 (prevDate, curDate]
        const startIdx = prevDate ? klineDates.findIndex((d) => d > prevDate) : 0;
        if (startIdx < 0) continue;

        // 結束於最後一個 <= curDate 的 K 線
        let endIdx = -1;
        for (let i = klineDates.length - 1; i >= 0; i--) {
            if (klineDates[i] <= curDate) {
                endIdx = i;
                break;
            }
        }
        if (endIdx < 0 || endIdx < startIdx) continue;

        const curVal = sumHoldingPercent(holdingByDate, curDate, levelSet);
        const prevVal = hi > 0 ? sumHoldingPercent(holdingByDate, allHoldingDates[hi - 1], levelSet) : null;
        const lineColor = prevVal === null ? "#94a3b8" : getHoldingChangeColor(curVal, prevVal);
        segments.push({ startIdx, endIdx, lineColor, areaColor: getHoldingAreaColor(lineColor) });
    }
    return segments;
}

/**
 * 以單一柱狀圖系列呈現持股占比，每根 K 線依所在週漲跌著色。
 * 使用逐筆 itemStyle.color 避免多段 series 造成柱寬壓縮。
 */
function buildSegmentedAreaSeries(filledData: Map<string, Map<string, number>>, klineDates: string[], levelSet: Set<string>, seriesName: string, gIdx: number, yAxisIndex: number): { seriesList: object[]; allValues: number[] } {
    const fullData = computeHoldingSeriesData(filledData, klineDates, levelSet);
    const allValues = fullData.filter((v): v is number => v !== "-");
    const segments = computeHoldingSegments(klineDates, levelSet);

    // 建立每個 K 線索引對應的顏色查表
    const colorByIdx = new Map<number, string>();
    for (const seg of segments) {
        for (let i = seg.startIdx; i <= seg.endIdx; i++) {
            colorByIdx.set(i, seg.lineColor);
        }
    }

    // 單一 series，每筆資料附帶 itemStyle.color
    const barData = fullData.map((v, i) => {
        if (v === "-") return { value: null as number | null, itemStyle: { color: "#94a3b8" } };
        return { value: v, itemStyle: { color: colorByIdx.get(i) ?? "#94a3b8", opacity: 0.85 } };
    });

    const seriesList: object[] = [
        {
            name: seriesName,
            type: "bar" as const,
            data: barData,
            xAxisIndex: gIdx,
            yAxisIndex,
            barCategoryGap: "0%",
        },
    ];

    return { seriesList, allValues };
}

