/**
 * 驗證使用者輸入的日期區間是否合法。
 * @returns 錯誤訊息字串（若有問題）；`null` 表示驗證通過。
 */
function validateDateRange(): string | null {
    // 簡單正則驗證格式：必須為 yyyy-MM-dd（Vite date input 保證，但防呆用）
    if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate.value) || !/^\d{4}-\d{2}-\d{2}$/.test(endDate.value)) {
        return "日期格式錯誤，請使用 yyyy-MM-dd。";
    }

    // 起始日不可晚於結束日（字串比較在 ISO 8601 格式下等同日期比較）
    if (startDate.value > endDate.value) {
        return "起始日不可晚於結束日。";
    }

    // 限制查詢範圍不超過可用資料範圍（MIN_CANDLE_DATE ~ 今天）
    const today = getTodayDateInput();
    if (startDate.value < MIN_CANDLE_DATE || endDate.value > today) {
        return `日期區間需介於 ${MIN_CANDLE_DATE} 到 ${today}。`;
    }

    return null; // 驗證通過
}

/**
 * 套用目前使用者選取的日期區間，重新向後端抓取資料並更新所有子圖（含持股、法人）。
 */
async function applyDateRange() {
    // 同時抓取 K 線主圖、持股分級、三大法人、主力買賣超四類資料
    await fetchAndRender();
    await fetchHoldingShares();
    await fetchInstitutional();
    await fetchMainForce();
}

/**
 * 套用快速預設日期區間（1/3/5 年）。
 * 結束日固定為今天，起始日為今天往前 N 年（不早於 MIN_CANDLE_DATE）。
 * @param years 往前推算的年數。
 */
function applyPresetRange(years: number) {
    const today = getTodayDateInput(); // 取得今天的 ISO 日期字串
    endDate.value = today; // 結束日設為今天
    const d = new Date(`${today}T00:00:00`); // 將今天解析為 Date 物件
    d.setFullYear(d.getFullYear() - years); // 往前推算 N 年
    const computedStart = toDateInputValue(d);
    // 取計算出的起始日與最早資料日的較大值（避免超出資料範圍）
    startDate.value = [computedStart, MIN_CANDLE_DATE].sort().at(-1) ?? MIN_CANDLE_DATE;
    void applyDateRange(); // 非同步執行資料抓取（不等待）
}

/**
 * 顯示全部可用 K 線資料（從 MIN_CANDLE_DATE 到今天）。
 */
function applyAllRange() {
    endDate.value = getTodayDateInput(); // 結束日設為今天
    startDate.value = MIN_CANDLE_DATE; // 起始日設為資料最早日
    void applyDateRange(); // 非同步執行資料抓取
}

/**
 * 切換大戶/散戶持股閾值
 *
 * 使用者互動：點擊大戶/散戶持股 UI 時
 *   - 若閾值已啟用 → 移除該閾值（取消勾選）
 *   - 若閾值未啟用 → 清除舊選項並選擇新閾值
 *   - 每種類型（大戶/散戶）只能同時選一個閾值
 *
 * @param type "large" 表示大戶 ≥ N 張、"small" 表示散戶 ≤ N 張
 * @param threshold 張數閾值
 */
function toggleHoldingThreshold(type: "large" | "small", threshold: number) {
    const set = type === "large" ? activeLargeThresholds.value : activeSmallThresholds.value;

    if (set.has(threshold)) {
        set.delete(threshold); // 取消啟用
    } else {
        set.add(threshold); // 啟用新選項
    }

    // 同步狀態並重繪
    if (type === "large") activeLargeThresholds.value = new Set(set);
    else activeSmallThresholds.value = new Set(set);

    redraw();
}

/**
 * 向後端取得 K 線資料並渲染圖表。
 * 查詢範圍由使用者選取，預設為今天往前一年。
 */
async function fetchAndRender() {
    if (!chart) return;

    isLoading.value = true;
    errorMessage.value = "";

    try {
        const validationError = validateDateRange();
        if (validationError) {
            errorMessage.value = validationError;
            return;
        }

        const token = props.getToken();
        const res = await fetch(`${props.apiBaseUrl}/api/stocks/${encodeURIComponent(props.stockCode)}/candles?from=${startDate.value}&to=${endDate.value}&timeframe=${selectedTimeframe.value}`, {
            headers: {
                "Content-Type": "application/json",
                ...(token ? { Authorization: `Bearer ${token}` } : {}),
            },
        });

        if (!res.ok) {
            const body = await res.json().catch(() => ({ message: `HTTP ${res.status}` }));
            errorMessage.value = body.message ?? `HTTP ${res.status}`;
            return;
        }

        const data: CandleResponse = await res.json();
        cachedData = data;
        renderChart(mergeSnapshot(data));
    } catch (e) {
        errorMessage.value = e instanceof Error ? e.message : "載入失敗";
    } finally {
        isLoading.value = false;
        setTimeout(() => chart?.resize(), 10);
    }
}

type TooltipParam = { name: string; seriesName: string; value: unknown; marker: string };
const TOOLTIP_BB_NAMES = new Set(["BB上軌", "BB中軌", "BB下軌"]);
const TOOLTIP_SKIP_REFS = new Set(["RSI-80", "RSI-50", "RSI-20", "KD-80", "KD-50", "KD-20", "DMI-80", "DMI-50", "DMI-20"]);

function normalizeDateKey(dateStr: string): string {
    if (!dateStr) return dateStr;

    const trimmed = dateStr.trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
        return trimmed;
    }

    const parsed = new Date(trimmed);
    if (!Number.isNaN(parsed.getTime())) {
        return parsed.toISOString().slice(0, 10);
    }

    return trimmed.slice(0, 10);
}

function isHoldingSeries(name: string): boolean {
    return name.endsWith("張以上") || name.endsWith("張以下");
}

const INSTITUTIONAL_SERIES_NAMES = new Set(["外資", "投信", "自營商(避險)", "自營商"]);

function isInstitutionalSeries(name: string): boolean {
    return INSTITUTIONAL_SERIES_NAMES.has(name) || name.endsWith("(累計)");
}

function processRegularParam(p: TooltipParam, lines: string[], bbGroup: string[], seen: Set<string>): void {
    if (seen.has(p.seriesName)) return;
    seen.add(p.seriesName);
    const v = p.value;
    if (p.seriesName === "K線" && Array.isArray(v)) {
        lines.push(`<b>${p.name}</b><br/>開：${v[1]} 收：${v[2]}<br/>低：${v[3]} 高：${v[4]}`);
    } else if (TOOLTIP_BB_NAMES.has(p.seriesName) && typeof v === "number") {
        bbGroup.push(`${p.marker}${p.seriesName}：${v.toFixed(2)}`);
    } else if (isInstitutionalSeries(p.seriesName) && typeof v === "number") {
        const sign = v >= 0 ? "+" : "";
        const color = v >= 0 ? "#ef4444" : "#22c55e";
        const bold = INSTITUTIONAL_SERIES_NAMES.has(p.seriesName) ? ";font-weight:600" : "";
        lines.push(`${p.marker}${p.seriesName}\uff1a<span style="color:${color}${bold}">${sign}${v.toLocaleString()} \u5f35</span>`);
    } else if (!TOOLTIP_SKIP_REFS.has(p.seriesName) && typeof v === "number") {
        lines.push(`${p.marker}${p.seriesName}：${v.toFixed(2)}`);
    }
}

function buildTooltipLines(params: TooltipParam[]): string[] {
    const lines: string[] = [];
    const bbGroup: string[] = [];
    const seen = new Set<string>();
    const holdingValues = new Map<string, { marker: string; value: number }>();

    for (const p of params) {
        if (isHoldingSeries(p.seriesName)) {
            if (!holdingValues.has(p.seriesName) && typeof p.value === "number") {
                holdingValues.set(p.seriesName, { marker: p.marker, value: p.value });
            }
        } else {
            processRegularParam(p, lines, bbGroup, seen);
        }
    }
    if (bbGroup.length > 0) lines.push(...bbGroup);

    // 按大戶（張以上）在前、散戶（張以下）在後排序
    const sortedHolding = Array.from(holdingValues.entries()).sort((a, b) => {
        const aIsLarge = a[0].endsWith("張以上");
        const bIsLarge = b[0].endsWith("張以上");
        return aIsLarge === bIsLarge ? 0 : aIsLarge ? -1 : 1;
    });

    for (const [name, { marker, value }] of sortedHolding) {
        lines.push(`${marker}${name}：${value.toFixed(2)}%`);
    }
    return lines;
}

/**
 * 以取得的資料渲染 ECharts 圖表，包含：
 * - 雙 Grid 佈局（上方 K 線 + 下方成交量）
 * - MA5 / MA10 / MA20 均線
 * - DataZoom 滑桿（預設顯示最近 30% 資料）
 * - Tooltip 顯示 OHLC 與成交量
 * @param data 後端回傳的 K 線回應資料。
 */
function renderChart(data: CandleResponse, preserveZoom = false) {
    if (!chart) return;

    const items = data.data ?? [];
    const dates = items.map((d) => d.date);
    const candleValues = items.map((d) => [d.open, d.close, d.low, d.high]);
    const closes = items.map((d) => d.close);
    const highs = items.map((d) => d.high);
    const lows = items.map((d) => d.low);
    const volumes = items.map((d) => Math.round((d.volume ?? 0) / 1000));

    // 計算預設顯示 K 棒的百分比
    const defaultZoomStart = Math.max(0, 100 - (candleCount.value / items.length) * 100);

    // 若需要保留目前拖拉位置，從圖表實例讀取現有 DataZoom 狀態
    let dataZoomStart = defaultZoomStart;
    let dataZoomEnd = 100;
    if (preserveZoom) {
        const currentOption = chart.getOption() as { dataZoom?: Array<{ start?: number; end?: number }> };
        const dz = currentOption?.dataZoom?.[0];
        if (dz != null) {
            dataZoomStart = dz.start ?? defaultZoomStart;
            dataZoomEnd = dz.end ?? 100;
        }
    }

    const ma5 = calculateMA(closes, 5);
    const ma10 = calculateMA(closes, 10);
    const ma20 = calculateMA(closes, 20);
    const bb = calculateBollingerBands(closes, bbParams.value.period, bbParams.value.multiplier);
    const rsi = calculateRSI(closes, rsiParams.value.period);
    const rsi2 = calculateRSI(closes, rsiParams.value.period2);
    const macd = calculateImpulseMACD(highs, lows, closes, macdParams.value.lengthMA, macdParams.value.lengthSignal);
    const kd = calculateKD(highs, lows, closes, kdParams.value.kPeriod, kdParams.value.dPeriod, kdParams.value.slowing);
    const dmi = calculateDMI(highs, lows, closes, dmiParams.value.diLen, dmiParams.value.adxLen);

    // ─── 動態 Grid 佈局 ───────────────────────────────────────
    // 固定子圖高度配置（px）
    const subPanelH = CHART_SUB_PANEL_H;
    const volH = 40; // 成交量高度
    const bottom = CHART_BOTTOM_RESERVE;
    const top = 50; // legend
    const gapBetween = CHART_GAP_BETWEEN;

    const activePanels = panelOrder.value.filter(
        (k): k is "rsi" | "macd" | "kd" | "dmi" | "large" | "small" | "main_force" | "inst_dealer" | "inst_trust" | "inst_hedging" | "inst_foreign" =>
            k !== "bb" &&
            ((k === "rsi" && showRsi.value) ||
                (k === "macd" && showMacd.value) ||
                (k === "kd" && showKd.value) ||
                (k === "dmi" && showDmi.value) ||
                (k === "large" && showLargeHolder.value) ||
                (k === "small" && showSmallHolder.value) ||
                (k === "main_force" && showMainForce.value) ||
                (k === "inst_foreign" && showInstForeign.value) ||
                (k === "inst_trust" && showInstTrust.value) ||
                (k === "inst_hedging" && showInstHedging.value) ||
                (k === "inst_dealer" && showInstDealer.value)),
    );

    // Grid 0: K 線主圖（剩餘空間扣掉子圖）
    const subPanelsH = activePanels.length * (subPanelH + gapBetween);
    // Grid 0 bottom = volH + gapBetween + subPanelsH + bottom + dataZoom
    const mainBottom = volH + gapBetween + subPanelsH + bottom + 60; // 60 for dataZoom slider

    const gridLeft = 60;
    const gridRight = 72;
    const grids: object[] = [
        { left: gridLeft, right: gridRight, top, bottom: mainBottom, containLabel: false },
        { left: gridLeft, right: gridRight, height: volH, bottom: mainBottom - volH - gapBetween, containLabel: false },
    ];
    // 確保 activePanels[0] 在最上方（具有最大的 bottom 值），依序往下疊加
    let curBottom = bottom + 60 + (activePanels.length - 1) * (subPanelH + gapBetween);
    for (let i = 0; i < activePanels.length; i++) {
        grids.push({ left: gridLeft, right: gridRight, height: subPanelH, bottom: curBottom, containLabel: false });
        curBottom -= subPanelH + gapBetween;
    }

    const gridCount = grids.length;
    const allXAxisIndexes = Array.from({ length: gridCount }, (_, i) => i);

    // 對應各 gridIndex 的指標類型（用於 formatter）
    const gridPanelType: (string | null)[] = ["kline", "volume", ...activePanels];

    // 生成對應數量的 xAxis / yAxis
    const xAxes = allXAxisIndexes.map((i) => {
        const panelType = gridPanelType[i];
        return {
            type: "category",
            data: dates,
            boundaryGap: false,
            axisLine: { onZero: false },
            axisTick: { show: i === 0 ? undefined : false },
            axisLabel: { show: i === 0 },
            splitLine: { show: false },
            gridIndex: i,
            axisPointer: {
                label: {
                    formatter: (params: { value: string; seriesData: { seriesName: string; value: unknown }[] }) => {
                        const dateStr = params.value;
                        const seriesData = params.seriesData;

                        if (panelType === "kline") {
                            const candle = seriesData.find((s) => s.seriesName === "K線");
                            let info = dateStr;
                            if (candle && Array.isArray(candle.value)) {
                                const [, open, close, low, high] = candle.value as number[];
                                info += `  開:${open}  收:${close}  低:${low}  高:${high}`;
                            }
                            // 添加布林通道
                            const bbUpper = seriesData.find((s) => s.seriesName === "BB上軌");
                            const bbMiddle = seriesData.find((s) => s.seriesName === "BB中軌");
                            const bbLower = seriesData.find((s) => s.seriesName === "BB下軌");
                            const bbParts = [];
                            if (bbUpper && typeof bbUpper.value === "number") bbParts.push(`上:${bbUpper.value.toFixed(2)}`);
                            if (bbMiddle && typeof bbMiddle.value === "number") bbParts.push(`中:${bbMiddle.value.toFixed(2)}`);
                            if (bbLower && typeof bbLower.value === "number") bbParts.push(`下:${bbLower.value.toFixed(2)}`);
                            if (bbParts.length > 0) info += `  BB(${bbParts.join(", ")})`;
                            // 添加日均線
                            const ma5 = seriesData.find((s) => s.seriesName === "MA5");
                            const ma10 = seriesData.find((s) => s.seriesName === "MA10");
                            const ma20 = seriesData.find((s) => s.seriesName === "MA20");
                            const maParts = [];
                            if (ma5 && typeof ma5.value === "number") maParts.push(`MA5:${ma5.value.toFixed(2)}`);
                            if (ma10 && typeof ma10.value === "number") maParts.push(`MA10:${ma10.value.toFixed(2)}`);
                            if (ma20 && typeof ma20.value === "number") maParts.push(`MA20:${ma20.value.toFixed(2)}`);
                            if (maParts.length > 0) info += `  ${maParts.join("  ")}`;
                            return info;
                        } else if (panelType === "volume") {
                            const vol = seriesData.find((s) => s.seriesName === "成交量");
                            if (vol && typeof vol.value === "number") {
                                return `成交量:${vol.value}`;
                            }
                        } else if (panelType === "rsi") {
                            const vals = seriesData
                                .filter((s) => !s.seriesName.startsWith("RSI-"))
                                .map((s) => `${s.seriesName}:${typeof s.value === "number" ? s.value.toFixed(2) : "-"}`)
                                .join("  ");
                            return vals ? `${vals}` : dateStr;
                        } else if (panelType === "macd") {
                            const vals = seriesData
                                .filter((s) => !s.seriesName.startsWith("Impulse"))
                                .map((s) => `${s.seriesName}:${typeof s.value === "number" ? s.value.toFixed(4) : "-"}`)
                                .join("  ");
                            return vals ? `${vals}` : dateStr;
                        } else if (panelType === "kd") {
                            const vals = seriesData
                                .filter((s) => !s.seriesName.startsWith("KD-"))
                                .map((s) => `${s.seriesName}:${typeof s.value === "number" ? s.value.toFixed(2) : "-"}`)
                                .join("  ");
                            return vals ? `${vals}` : dateStr;
                        } else if (panelType === "dmi") {
                            const vals = seriesData
                                .filter((s) => !s.seriesName.startsWith("DMI-"))
                                .map((s) => `${s.seriesName}:${typeof s.value === "number" ? s.value.toFixed(2) : "-"}`)
                                .join("  ");
                            return vals ? `${vals}` : dateStr;
                        } else if (panelType === "large" || panelType === "small") {
                            const vals = seriesData.map((s) => `${s.seriesName}:${typeof s.value === "number" ? s.value.toFixed(2) : "-"}%`).join("  ");
                            return vals ? `${vals}` : dateStr;
                        } else if (panelType === "main_force") {
                            const vals = seriesData.map((s) => `${s.seriesName}:${typeof s.value === "number" ? s.value.toLocaleString() : "-"}`).join("  ");
                            return vals ? `${vals}` : dateStr;
                        } else if (panelType && panelType.startsWith("inst_")) {
                            const vals = seriesData.map((s) => `${s.seriesName}:${typeof s.value === "number" ? s.value.toLocaleString() : "-"}`).join("  ");
                            return vals ? `${vals}` : dateStr;
                        }

                        return dateStr;
                    },
                },
            },
        };
    });

    const yAxes: object[] = [
        { scale: true, splitArea: { show: true }, gridIndex: 0, position: "left", axisLabel: { width: 45 } },
        { scale: true, gridIndex: 1, splitNumber: 2, axisLabel: { show: false, width: 45 }, axisLine: { show: false }, splitLine: { show: false } },
    ];
    // yAxis for sub-panels is pushed inside activePanels.forEach (allows per-panel customization for large/small dynamic scale)

    // ─── Series ───────────────────────────────────────────────
    const legendNames = ["K線", "MA5", "MA10", "MA20", "BB上軌", "BB中軌", "BB下軌"];
    const legendSelected: Record<string, boolean> = {
        BB上軌: showBollinger.value,
        BB中軌: showBollinger.value,
        BB下軌: showBollinger.value,
    };

    const series: object[] = [
        { name: "K線", type: "candlestick", data: candleValues, xAxisIndex: 0, yAxisIndex: 0, itemStyle: { color: upColor, color0: downColor, borderColor: upBorderColor, borderColor0: downBorderColor } },
        { name: "MA5", type: "line", data: ma5, xAxisIndex: 0, yAxisIndex: 0, smooth: true, showSymbol: false, lineStyle: { opacity: 0.7, width: 1.5 } },
        { name: "MA10", type: "line", data: ma10, xAxisIndex: 0, yAxisIndex: 0, smooth: true, showSymbol: false, lineStyle: { opacity: 0.7, width: 1.5 } },
        { name: "MA20", type: "line", data: ma20, xAxisIndex: 0, yAxisIndex: 0, smooth: true, showSymbol: false, lineStyle: { opacity: 0.7, width: 1.5 } },
        { name: "BB上軌", type: "line", data: bb.upper, xAxisIndex: 0, yAxisIndex: 0, smooth: false, showSymbol: false, color: "#6366f1", lineStyle: { color: "#6366f1", opacity: 0.8, width: 1.2, type: "dashed" }, z: 1 },
        { name: "BB中軌", type: "line", data: bb.middle, xAxisIndex: 0, yAxisIndex: 0, smooth: false, showSymbol: false, color: "#818cf8", lineStyle: { color: "#818cf8", opacity: 0.7, width: 1, type: "dotted" }, z: 1 },
        { name: "BB下軌", type: "line", data: bb.lower, xAxisIndex: 0, yAxisIndex: 0, smooth: false, showSymbol: false, color: "#6366f1", lineStyle: { color: "#6366f1", opacity: 0.8, width: 1.2, type: "dashed" }, z: 1 },
        {
            name: "成交量",
            type: "bar",
            data: volumes,
            xAxisIndex: 1,
            yAxisIndex: 1,
            itemStyle: {
                color(params: { dataIndex: number }) {
                    const item = items[params.dataIndex];
                    return (item.close ?? 0) >= (item.open ?? 0) ? upColor : downColor;
                },
            },
        },
    ];

    // 子圖 series
    activePanels.forEach((panel, i) => {
        const gIdx = 2 + i;
        if (panel === "rsi") {
            const panelYAxisIndex = yAxes.length;
            yAxes.push({ scale: true, gridIndex: gIdx, splitNumber: 3, axisLabel: { show: true, fontSize: 10, width: 45 }, splitLine: { lineStyle: { type: "dashed", opacity: 0.4 } } });
            legendNames.push(`RSI(${rsiParams.value.period})`, `RSI(${rsiParams.value.period2})`);
            legendSelected[`RSI(${rsiParams.value.period})`] = true;
            legendSelected[`RSI(${rsiParams.value.period2})`] = true;
            const ref80 = new Array(dates.length).fill(80) as number[];
            const ref50 = new Array(dates.length).fill(50) as number[];
            const ref20 = new Array(dates.length).fill(20) as number[];
            series.push(
                { name: `RSI(${rsiParams.value.period})`, type: "line", data: rsi, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, smooth: false, showSymbol: false, color: "#f59e0b", lineStyle: { width: 2.5 } },
                { name: `RSI(${rsiParams.value.period2})`, type: "line", data: rsi2, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, smooth: false, showSymbol: false, color: "#a78bfa", lineStyle: { width: 2.5 } },
                { name: "RSI-80", type: "line", data: ref80, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, showSymbol: false, silent: true, lineStyle: { type: "solid", color: "#ef4444", opacity: 0.7, width: 1.2 }, legendHoverLink: false },
                { name: "RSI-50", type: "line", data: ref50, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, showSymbol: false, silent: true, lineStyle: { type: "dashed", color: "#94a3b8", opacity: 0.6, width: 1.2 }, legendHoverLink: false },
                { name: "RSI-20", type: "line", data: ref20, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, showSymbol: false, silent: true, lineStyle: { type: "solid", color: "#22c55e", opacity: 0.7, width: 1.2 }, legendHoverLink: false },
            );
        } else if (panel === "macd") {
            const panelYAxisIndex = yAxes.length;
            yAxes.push({ scale: true, gridIndex: gIdx, splitNumber: 3, axisLabel: { show: true, fontSize: 10, width: 45 }, splitLine: { lineStyle: { type: "dashed", opacity: 0.4 } } });
            legendNames.push("ImpulseMACD", "ImpulseHisto", "Signal");
            legendSelected["ImpulseMACD"] = true;
            legendSelected["ImpulseHisto"] = true;
            legendSelected["Signal"] = true;
            series.push(
                {
                    name: "ImpulseMACD",
                    type: "line",
                    data: macd.md,
                    xAxisIndex: gIdx,
                    yAxisIndex: panelYAxisIndex,
                    itemStyle: {
                        color(params: { dataIndex: number }) {
                            return macd.mdColors[params.dataIndex] ?? "#94a3b8";
                        },
                    },
                },
                {
                    name: "ImpulseHisto",
                    type: "bar",
                    data: macd.sh,
                    xAxisIndex: gIdx,
                    yAxisIndex: panelYAxisIndex,
                    itemStyle: {
                        color(params: { dataIndex: number }) {
                            const v = macd.sh[params.dataIndex];
                            if (v === "-" || typeof v !== "number") return "#94a3b8";
                            return v >= 0 ? "#ef5350" : "#26a69a";
                        },
                        opacity: 0.7,
                    },
                },
                { name: "Signal", type: "line", data: macd.sb, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, smooth: false, showSymbol: false, color: "#7f1d1d", lineStyle: { width: 1.5 } },
            );
        } else if (panel === "kd") {
            const panelYAxisIndex = yAxes.length;
            yAxes.push({ scale: true, gridIndex: gIdx, splitNumber: 3, axisLabel: { show: true, fontSize: 10, width: 45 }, splitLine: { lineStyle: { type: "dashed", opacity: 0.4 } } });
            legendNames.push("K", "D");
            legendSelected["K"] = true;
            legendSelected["D"] = true;
            const kdMarkArea = computeKDMarkAreaData(kd.k, kd.d, dates);
            const ref80 = new Array(dates.length).fill(80) as number[];
            const ref50 = new Array(dates.length).fill(50) as number[];
            const ref20 = new Array(dates.length).fill(20) as number[];
            series.push(
                {
                    name: "K",
                    type: "line",
                    data: kd.k,
                    xAxisIndex: gIdx,
                    yAxisIndex: panelYAxisIndex,
                    smooth: false,
                    showSymbol: false,
                    color: "#0ea5e9",
                    lineStyle: { width: 2.5 },
                    markArea: { silent: true, data: kdMarkArea },
                },
                { name: "D", type: "line", data: kd.d, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, smooth: false, showSymbol: false, color: "#d946ef", lineStyle: { width: 2.5 } },
                { name: "KD-80", type: "line", data: ref80, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, showSymbol: false, silent: true, lineStyle: { type: "solid", color: "#ef4444", opacity: 0.7, width: 1.2 }, legendHoverLink: false },
                { name: "KD-50", type: "line", data: ref50, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, showSymbol: false, silent: true, lineStyle: { type: "dashed", color: "#94a3b8", opacity: 0.6, width: 1.2 }, legendHoverLink: false },
                { name: "KD-20", type: "line", data: ref20, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, showSymbol: false, silent: true, lineStyle: { type: "solid", color: "#22c55e", opacity: 0.7, width: 1.2 }, legendHoverLink: false },
            );
        } else if (panel === "dmi") {
            const panelYAxisIndex = yAxes.length;
            yAxes.push({ scale: true, gridIndex: gIdx, splitNumber: 3, axisLabel: { show: true, fontSize: 10, width: 45 }, splitLine: { lineStyle: { type: "dashed", opacity: 0.4 } } });
            legendNames.push(`+DI(${dmiParams.value.diLen})`, `-DI(${dmiParams.value.diLen})`, `ADX(${dmiParams.value.adxLen})`);
            legendSelected[`+DI(${dmiParams.value.diLen})`] = true;
            legendSelected[`-DI(${dmiParams.value.diLen})`] = true;
            legendSelected[`ADX(${dmiParams.value.adxLen})`] = true;
            const ref80dmi = new Array(dates.length).fill(80) as number[];
            const ref50dmi = new Array(dates.length).fill(50) as number[];
            const ref20dmi = new Array(dates.length).fill(20) as number[];
            const dmiMarkArea = computeDMIMarkAreaData(dmi.plus, dmi.minus, dates);
            series.push(
                {
                    name: `ADX(${dmiParams.value.adxLen})`,
                    type: "line",
                    data: dmi.adx,
                    xAxisIndex: gIdx,
                    yAxisIndex: panelYAxisIndex,
                    smooth: false,
                    showSymbol: false,
                    color: "#2196f3",
                    lineStyle: { width: 3 },
                    markArea: { silent: true, data: dmiMarkArea },
                },
                { name: `+DI(${dmiParams.value.diLen})`, type: "line", data: dmi.plus, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, smooth: false, showSymbol: false, color: "#ef5350", lineStyle: { width: 2 } },
                { name: `-DI(${dmiParams.value.diLen})`, type: "line", data: dmi.minus, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, smooth: false, showSymbol: false, color: "#00e676", lineStyle: { width: 2 } },
                { name: "DMI-80", type: "line", data: ref80dmi, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, showSymbol: false, silent: true, lineStyle: { type: "solid", color: "#ef4444", opacity: 0.7, width: 1.2 }, legendHoverLink: false },
                { name: "DMI-50", type: "line", data: ref50dmi, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, showSymbol: false, silent: true, lineStyle: { type: "dashed", color: "#94a3b8", opacity: 0.6, width: 1.2 }, legendHoverLink: false },
                { name: "DMI-20", type: "line", data: ref20dmi, xAxisIndex: gIdx, yAxisIndex: panelYAxisIndex, showSymbol: false, silent: true, lineStyle: { type: "solid", color: "#22c55e", opacity: 0.7, width: 1.2 }, legendHoverLink: false },
            );
        } else if (panel === "main_force") {
            // 主力買賣超柱狀圖 + 累計折線（左右雙 Y 軸）
            const panelYAxisIndex = yAxes.length;
            const mainForceMap = new Map(mainForceData.value.map((r) => [r.date, r]));
            const barData = dates.map((d) => mainForceMap.get(d)?.overBoughtOverSold ?? null);
            // 計算依時間序列累計值
            const sortedMf = [...mainForceData.value].sort((a, b) => a.date.localeCompare(b.date));
            const cumulativeMap = new Map<string, number>();
            let cumSum = 0;
            for (const row of sortedMf) {
                cumSum += row.overBoughtOverSold;
                cumulativeMap.set(row.date, cumSum);
            }
            const cumData = dates.map((d) => cumulativeMap.get(d) ?? null);
            yAxes.push({
                scale: true,
                gridIndex: gIdx,
                splitNumber: 3,
                axisLabel: { show: true, fontSize: 10, width: 45, formatter: (v: number) => v.toLocaleString() },
                splitLine: { lineStyle: { type: "dashed", opacity: 0.4 } },
            });
            const cumulativeYAxisIndex = yAxes.length;
            yAxes.push({
                scale: true,
                gridIndex: gIdx,
                position: "right",
                splitNumber: 3,
                axisLabel: { show: true, fontSize: 10, width: 45, align: "right", margin: 10, formatter: (v: number) => v.toLocaleString() },
                splitLine: { show: false },
            });
            legendNames.push("主力買賣超", "主力(累計)");
            legendSelected["主力買賣超"] = true;
            legendSelected["主力(累計)"] = true;
            series.push(
                {
                    name: "主力買賣超",
                    type: "bar" as const,
                    xAxisIndex: gIdx,
                    yAxisIndex: panelYAxisIndex,
                    barCategoryGap: "20%",
                    data: barData,
                    itemStyle: {
                        color(params: { value: number }) {
                            return params.value >= 0 ? "#ef4444" : "#22c55e";
                        },
                        borderRadius: [2, 2, 0, 0] as [number, number, number, number],
                    },
                },
                {
                    name: "主力(累計)",
                    type: "line" as const,
                    xAxisIndex: gIdx,
                    yAxisIndex: cumulativeYAxisIndex,
                    data: cumData,
                    showSymbol: false,
                    smooth: false,
                    lineStyle: { color: "#f59e0b", width: 2 },
                    itemStyle: { color: "#f59e0b" },
                    z: 5,
                },
            );
        } else if (panel === "large" || panel === "small") {
            const panelYAxisIndex = yAxes.length;
            const isAbove = panel === "large";
            const activeThresholds = (isAbove ? [...activeLargeThresholds.value] : [...activeSmallThresholds.value]).sort((a, b) => a - b);
            const suffix = isAbove ? "張以上" : "張以下";
            const filledData = buildForwardFilledHoldingData(dates);
            const allValues: number[] = [];

            for (const threshold of activeThresholds) {
                const levelSet = isAbove ? getLargeHolderLevels(threshold) : getSmallHolderLevels(threshold);
                const seriesName = `${threshold}${suffix}`;
                const { seriesList, allValues: segVals } = buildSegmentedAreaSeries(filledData, dates, levelSet, seriesName, gIdx, panelYAxisIndex);
                allValues.push(...segVals);
                if (!legendNames.includes(seriesName)) {
                    legendNames.push(seriesName);
                    legendSelected[seriesName] = true;
                }
                series.push(...seriesList);
            }

            // 動態 Y 軸：依實際數據範圍設定，避免視覺上過於平坦
            const minVal = allValues.length > 0 ? Math.min(...allValues) : 0;
            const maxVal = allValues.length > 0 ? Math.max(...allValues) : 100;
            const range = maxVal - minVal;
            const pad = range > 0 ? range * 0.2 : 2;
            yAxes.push({
                scale: true,
                gridIndex: gIdx,
                splitNumber: 3,
                min: Number.parseFloat((minVal - pad).toFixed(1)),
                max: Number.parseFloat((maxVal + pad).toFixed(1)),
                axisLabel: { show: true, fontSize: 10, width: 45, formatter: (v: number) => `${v.toFixed(1)}%` },
                splitLine: { lineStyle: { type: "dashed", opacity: 0.4 } },
            });
        } else if (panel === "inst_foreign" || panel === "inst_trust" || panel === "inst_hedging" || panel === "inst_dealer") {
            const panelYAxisIndex = yAxes.length;
            const INST_META: Record<string, { key: keyof InstitutionalRow; label: string; color: string; posColor: string; negColor: string }> = {
                inst_foreign: { key: "foreignInvestorNet", label: "外資", color: "#2563eb", posColor: "#ef4444", negColor: "#22c55e" },
                inst_trust: { key: "investmentTrustNet", label: "投信", color: "#16a34a", posColor: "#ef4444", negColor: "#22c55e" },
                inst_hedging: { key: "dealerHedgingNet", label: "自營商(避險)", color: "#8b5cf6", posColor: "#ef4444", negColor: "#22c55e" },
                inst_dealer: { key: "dealerSelfNet", label: "自營商", color: "#f59e0b", posColor: "#ef4444", negColor: "#22c55e" },
            };
            const meta = INST_META[panel];
            yAxes.push({
                scale: true,
                gridIndex: gIdx,
                splitNumber: 3,
                axisLabel: {
                    show: true,
                    fontSize: 10,
                    width: 45,
                    formatter: (v: number) => {
                        if (Math.abs(v) >= 10000) return `${(v / 10000).toFixed(1)}萬`;
                        return v.toLocaleString();
                    },
                },
                splitLine: { lineStyle: { type: "dashed", opacity: 0.4 } },
            });
            const instMap = new Map(institutionalData.value.map((r) => [r.date, r]));
            if (!legendNames.includes(meta.label)) legendNames.push(meta.label);
            legendSelected[meta.label] = true;
            series.push({
                name: meta.label,
                type: "bar" as const,
                xAxisIndex: gIdx,
                yAxisIndex: panelYAxisIndex,
                barCategoryGap: "20%",
                data: dates.map((d) => {
                    const row = instMap.get(d);
                    return row == null ? null : (row[meta.key] as number);
                }),
                itemStyle: {
                    color(params: { value: number }) {
                        return params.value >= 0 ? meta.posColor : meta.negColor;
                    },
                    borderRadius: [2, 2, 0, 0] as [number, number, number, number],
                },
            });
        }
    });

    // ─── 法人累計折線（第二階段：inst 面板確定全部 bar yAxis 後再補）────
    // inst_* 固定在 panelOrder 末尾，此時 yAxes 長度不再影響其他 panel 的 gIdx。
    const INST_META_ALL: Record<string, { key: keyof InstitutionalRow; label: string; color: string }> = {
        inst_foreign: { key: "foreignInvestorNet", label: "外資", color: "#2563eb" },
        inst_trust: { key: "investmentTrustNet", label: "投信", color: "#16a34a" },
        inst_hedging: { key: "dealerHedgingNet", label: "自營商(避險)", color: "#8b5cf6" },
        inst_dealer: { key: "dealerSelfNet", label: "自營商", color: "#f59e0b" },
    };
    for (const panel of activePanels) {
        if (!panel.startsWith("inst_")) continue;
        const panelIdx = activePanels.indexOf(panel);
        const gIdx = 2 + panelIdx;
        const meta = INST_META_ALL[panel];
        const cumLabel = `${meta.label}(累計)`;

        // 累計折線的 Y 軸（右側，獨立刻度）
        const cumYAxisIdx = yAxes.length;
        yAxes.push({
            scale: true,
            gridIndex: gIdx,
            position: "right",
            splitNumber: 3,
            axisLine: { show: true, lineStyle: { color: meta.color } },
            axisTick: { show: false },
            axisLabel: {
                show: true,
                fontSize: 10,
                width: 45,
                align: "right",
                margin: 10,
                color: meta.color,
                formatter: (v: number) => {
                    if (Math.abs(v) >= 10000) return `${(v / 10000).toFixed(1)}萬`;
                    return v.toLocaleString();
                },
            },
            splitLine: { show: false },
        });

        // 先計算所有歷史資料的累計值（到每個日期為止）
        const allCumMap = new Map<string, number>();
        let totalCumsum = 0;
        for (const row of institutionalData.value) {
            totalCumsum += row[meta.key] as number;
            allCumMap.set(row.date, totalCumsum);
        }

        // 計算當前顯示範圍內的累計數列（基於所有歷史累計值）
        const cumData = dates.map((d) => allCumMap.get(d) ?? null);

        if (!legendNames.includes(cumLabel)) legendNames.push(cumLabel);
        legendSelected[cumLabel] = true;
        series.push({
            name: cumLabel,
            type: "line" as const,
            xAxisIndex: gIdx,
            yAxisIndex: cumYAxisIdx,
            data: cumData,
            showSymbol: false,
            smooth: false,
            lineStyle: { color: meta.color, width: 2 },
            itemStyle: { color: meta.color },
            z: 5,
        });
    }

    // 防呆：確保每個 series 的 xAxis/yAxis 皆落在同一個 grid，避免 ECharts 拋出 grid mismatch。
    const xAxisGridByIndex = xAxes.map((axis) => axis.gridIndex ?? 0);
    const yAxisGridByIndex = (yAxes as Array<{ gridIndex?: number }>).map((axis) => axis.gridIndex ?? 0);
    for (const rawSeries of series as Array<{ xAxisIndex?: number; yAxisIndex?: number }>) {
        const xAxisIndex = rawSeries.xAxisIndex;
        const yAxisIndex = rawSeries.yAxisIndex;
        if (typeof xAxisIndex !== "number" || typeof yAxisIndex !== "number") continue;

        const xGrid = xAxisGridByIndex[xAxisIndex];
        const yGrid = yAxisGridByIndex[yAxisIndex];
        if (xGrid === undefined || yGrid === undefined || xGrid === yGrid) continue;

        const fixedYAxisIndex = yAxisGridByIndex.findIndex((gridIndex) => gridIndex === xGrid);
        if (fixedYAxisIndex >= 0) {
            rawSeries.yAxisIndex = fixedYAxisIndex;
        }
    }

    chart.setOption(
        {
            animation: true,
            animationDuration: 260,
            animationDurationUpdate: 220,
            animationEasing: "cubicOut",
            animationEasingUpdate: "cubicOut",
            legend: { data: legendNames, top: 4, selected: legendSelected, textStyle: { fontSize: 11 } },
            tooltip: {
                trigger: "none",
                axisPointer: { type: "cross" },
                formatter(params: unknown) {
                    if (!Array.isArray(params)) return "";
                    return buildTooltipLines(params as TooltipParam[]).join("<br/>");
                },
            },
            axisPointer: { link: [{ xAxisIndex: "all" }] },
            grid: grids,
            xAxis: xAxes,
            yAxis: yAxes,
            dataZoom: [
                {
                    type: "inside",
                    xAxisIndex: allXAxisIndexes,
                    start: dataZoomStart,
                    end: dataZoomEnd,
                    zoomOnMouseWheel: !isMobileView.value,
                    moveOnMouseMove: !isMobileView.value,
                    moveOnMouseWheel: false,
                    preventDefaultMouseMove: isMobileView.value,
                    throttle: isMobileView.value ? 24 : 80,
                },
                { show: !isMobileView.value, xAxisIndex: allXAxisIndexes, type: "slider", bottom: 0, start: dataZoomStart, end: dataZoomEnd },
            ],
            series,
        },
        true,
    );
}

/** 重新渲染圖表（使用快取資料）。 */
function redraw() {
    if (!cachedData) return;
    renderChart(mergeSnapshot(cachedData));
}

/** 初始化 ECharts 實例並掛載 ResizeObserver。 */
function initChart() {
    if (chartContainer.value && !chart) {
        chart = echarts.init(chartContainer.value);
        const ro = new ResizeObserver(() => chart?.resize());
        ro.observe(chartContainer.value);
    }
}

function syncMobileView() {
    isMobileView.value = window.innerWidth <= MOBILE_BREAKPOINT;
}

onMounted(async () => {
    syncMobileView();
    window.addEventListener("resize", syncMobileView);
    initChart();
    const prefs = await loadPreferences();
    if (prefs) {
        if (prefs.showBollinger !== undefined) showBollinger.value = prefs.showBollinger;
        if (prefs.showRsi !== undefined) showRsi.value = prefs.showRsi;
        if (prefs.showMacd !== undefined) showMacd.value = prefs.showMacd;
        if (prefs.showKd !== undefined) showKd.value = prefs.showKd;
        if (prefs.showDmi !== undefined) showDmi.value = prefs.showDmi;
        if (prefs.showLargeHolder !== undefined) showLargeHolder.value = prefs.showLargeHolder;
        if (prefs.showSmallHolder !== undefined) showSmallHolder.value = prefs.showSmallHolder;
        if (prefs.showMainForce !== undefined) showMainForce.value = prefs.showMainForce;
        if (prefs.showInstForeign !== undefined) showInstForeign.value = prefs.showInstForeign;
        if (prefs.showInstTrust !== undefined) showInstTrust.value = prefs.showInstTrust;
        if (prefs.showInstHedging !== undefined) showInstHedging.value = prefs.showInstHedging;
        if (prefs.showInstDealer !== undefined) showInstDealer.value = prefs.showInstDealer;
        if (prefs.panelOrder !== undefined) panelOrder.value = mergePanelOrder(prefs.panelOrder);
    }
    void applyDateRange();
    document.addEventListener("click", handleDocumentClick);

    if (dragContainer.value) {
        sortableInstance = Sortable.create(dragContainer.value, {
            swap: true,
            swapClass: "bg-cyan-100/80",
            animation: 150,
            handle: ".drag-handle",
            ghostClass: "opacity-0",
            dragClass: "cursor-grabbing",
            chosenClass: "scale-105",
            onEnd: (evt) => {
                const { oldIndex, newIndex } = evt;
                if (oldIndex === undefined || newIndex === undefined || oldIndex === newIndex) return;

                const currentActive = [...activePanelList.value];
                const temp = currentActive[oldIndex];
                currentActive[oldIndex] = currentActive[newIndex];
                currentActive[newIndex] = temp;

                const activeSet = new Set(currentActive);
                let cursor = 0;
                panelOrder.value = panelOrder.value.map((k) => {
                    if (activeSet.has(k as Exclude<IndicatorKey, "bb">)) {
                        return currentActive[cursor++];
                    }
                    return k;
                });

                redraw();
            },
        });
    }
});

onBeforeUnmount(() => {
    chart?.dispose();
    chart = null;
    sortableInstance?.destroy();
    sortableInstance = null;
    window.removeEventListener("resize", syncMobileView);
    document.removeEventListener("click", handleDocumentClick);
});

