                showSmallHolder: showSmallHolder.value,
                showMainForce: showMainForce.value,
                showInstForeign: showInstForeign.value,
                showInstTrust: showInstTrust.value,
                showInstHedging: showInstHedging.value,
                showInstDealer: showInstDealer.value,
                panelOrder: panelOrder.value,
