/**
 * 將快照資料合併進歷史資料，補上或更新今日 K 棒。
 * 僅在日K（D）週期且快照有效時執行，週K/月K 不需即時補丁。
 */
function mergeSnapshot(data: CandleResponse): CandleResponse {
    const snap = props.snapshot;
    if (selectedTimeframe.value !== "D" || !snap) {
        return data;
    }
    const today = new Date().toISOString().slice(0, 10);
    // lastUpdated 值為 unix timestamp (ex:1775799000000000) 單位為微秒，需轉為 YYYY-MM-DD
    const date = snap.lastUpdated != null ? new Date(snap.lastUpdated / 1000).toISOString().slice(0, 10) : null;
    // 如果快照日期不是今天，表示尚未有今日交易資料，不需合併
    if (today !== date) {
        return data;
    }
    const close = snap.lastPrice ?? snap.closePrice;
    const open = snap.openPrice;
    const high = snap.highPrice;
    const low = snap.lowPrice;
    const volume = snap.tradeVolume != null ? snap.tradeVolume * 1000 : null;

    if (close === null || open === null || high === null || low === null) {
        return data;
    }

    const items = [...data.data];
    const lastItem = items[items.length - 1];

    const todayCandle: CandleItem = { date: today, open, high, low, close, volume: volume ?? null, change: null };

    if (lastItem?.date === today) {
        items[items.length - 1] = todayCandle;
    } else {
        items.push(todayCandle);
    }

    return { ...data, data: items };
}

// 快照有新值時，僅更新資料部分，並保留目前的 DataZoom 拖拉位置
watch(
    () => props.snapshot,
