            return ts.length > 0 ? `散戶(${ts.join(",")})` : "散戶持股";
        }),
    },
    {
        key: "main_force" as const,
        label: "主力買賣超",
        color: "amber",
        isActive: showMainForce,
        toggle: () => {
            showMainForce.value = !showMainForce.value;
        },
        fields: [] as { key: string; label: string; min: number; max: number; step?: number }[],
        summary: computed(() => "主力買賣超"),
