const holderPanels = indicatorPanels.filter((p) => p.key === "large" || p.key === "small" || p.key === "main_force");

/** 各下拉選單的活躍指標數量 */
const activeTechCount = computed(() => [showBollinger.value, showRsi.value, showMacd.value, showKd.value, showDmi.value].filter(Boolean).length);
const activeHolderCount = computed(() => [showLargeHolder.value, showSmallHolder.value, showMainForce.value].filter(Boolean).length);
const activeInstCount = computed(() => [showInstForeign.value, showInstTrust.value, showInstHedging.value, showInstDealer.value].filter(Boolean).length);

