                                {{ panel.isActive.value ? panel.summary.value : panel.label }}
                            </button>
                            <button
                                @click="openPanel(panel.key)"
                                class="rounded-r-md border-l px-1.5 py-1.5 text-xs transition"
                                :class="openParamPanel === panel.key ? 'bg-slate-300 text-slate-700' : panel.isActive.value ? (panel.color === 'rose' ? 'border-rose-400 bg-rose-500 text-rose-100 hover:bg-rose-600' : 'border-sky-400 bg-sky-500 text-sky-100 hover:bg-sky-600') : 'border-slate-200 bg-slate-100 text-slate-500 hover:bg-slate-200'"
                                title="調整閾值"
                            >
                                ⚙
                            </button>
                            <!-- 持股閾值設定面板 -->
                            <div v-if="openParamPanel === panel.key" class="absolute left-full top-0 z-50 ml-1 min-w-52 rounded-xl border border-slate-200 bg-white p-3 shadow-xl">
                                <p class="mb-2 text-xs font-bold text-slate-600">{{ panel.label }} 閾值設定</p>
                                <div class="flex flex-wrap gap-1.5">
                                    <template v-if="panel.key === 'large'">
                                        <button
                                            v-for="t in LARGE_THRESHOLDS"
                                            :key="t"
                                            @click="toggleHoldingThreshold('large', t)"
                                            class="rounded-md border px-2.5 py-1 text-xs font-semibold transition"
                                            :style="activeLargeThresholds.has(t) ? { backgroundColor: LARGE_THRESHOLD_COLORS[t], color: '#fff', borderColor: LARGE_THRESHOLD_COLORS[t] } : {}"
                                            :class="activeLargeThresholds.has(t) ? '' : 'border-slate-200 bg-slate-50 text-slate-600 hover:bg-slate-100'"
                                        >
                                            {{ t }}張以上
                                        </button>
                                    </template>
                                    <template v-else-if="panel.key === 'small'">
                                        <button
                                            v-for="t in SMALL_THRESHOLDS"
                                            :key="t"
                                            @click="toggleHoldingThreshold('small', t)"
                                            class="rounded-md border px-2.5 py-1 text-xs font-semibold transition"
                                            :style="activeSmallThresholds.has(t) ? { backgroundColor: SMALL_THRESHOLD_COLORS[t], color: '#fff', borderColor: SMALL_THRESHOLD_COLORS[t] } : {}"
                                            :class="activeSmallThresholds.has(t) ? '' : 'border-slate-200 bg-slate-50 text-slate-600 hover:bg-slate-100'"
                                        >
                                            {{ t }}張以下
                                        </button>
                                    </template>
                                </div>
                                <button @click="openParamPanel = null" class="mt-2.5 rounded-md bg-slate-100 px-3 py-1 text-xs font-semibold text-slate-600 hover:bg-slate-200">關閉</button>
                            </div>
                        </div>
                    </div>
                </Teleport>
            </div>

            <!-- 法人指標 下拉選單 -->
            <div class="relative" @click.stop>
                <button
                    ref="instTriggerRef"
                    @click="openIndicatorDropdown(instTriggerRef, 'inst')"
                    class="flex items-center gap-1.5 rounded-md border px-3 py-1 text-xs font-semibold transition"
                    :class="openDropdown === 'inst' ? 'border-cyan-400 bg-cyan-50 text-cyan-700' : activeInstCount > 0 ? 'border-slate-400 bg-slate-700 text-white hover:bg-slate-600' : 'border-slate-200 bg-white text-slate-700 hover:bg-slate-50'"
                >
                    法人指標
                    <span v-if="activeInstCount > 0" class="rounded-full bg-blue-500 px-1.5 py-0.5 text-[10px] leading-none text-white">{{ activeInstCount }}</span>
                    <span class="text-[10px]" :class="openDropdown === 'inst' ? 'text-cyan-500' : activeInstCount > 0 ? 'text-slate-300' : 'text-slate-400'">▾</span>
                </button>
                <Teleport to="body">
                    <div v-if="openDropdown === 'inst'" ref="instDropdownRef" class="fixed z-[9000] min-w-40 rounded-xl border border-slate-200 bg-white p-2 shadow-xl" :style="teleportDropdownStyle" @click.stop>
                        <button v-for="inst in INST_PANEL_CONFIGS" :key="inst.key" @click="inst.toggle()" class="mb-1 block w-full rounded-md px-3 py-1.5 text-left text-xs font-semibold transition last:mb-0" :class="inst.isActive.value ? inst.activeClass : 'bg-slate-100 text-slate-600 hover:bg-slate-200'">
                            {{ inst.label }}
                        </button>
                    </div>
                </Teleport>
            </div>
        </div>

        <!-- Loading / error -->
        <div v-if="isLoading" class="flex h-80 items-center justify-center text-sm text-slate-500">載入歷史行情中…</div>
        <div v-else-if="errorMessage" class="flex h-80 flex-col items-center justify-center gap-2 rounded-lg bg-rose-50 p-4 text-sm text-rose-700">
            <p class="font-semibold">無法載入歷史行情</p>
            <p class="text-xs text-rose-500">{{ errorMessage }}</p>
        </div>

        <!-- Chart + 子圖拖曳把手 overlay -->
        <div v-show="!isLoading && !errorMessage" class="relative w-full" :style="{ height: `${chartHeight}px` }">
            <!-- ECharts 畫布 -->
            <div ref="chartContainer" class="chart-touch-surface absolute inset-0" />

            <!-- 左側拖曳把手：每個啟用中子圖各一個 -->
            <div ref="dragContainer" class="pointer-events-none absolute left-0 flex flex-col gap-2 z-10" :style="{ bottom: '100px' }">
                <div
                    v-for="key in activePanelList"
                    :key="key"
                    class="drag-handle pointer-events-auto flex cursor-grab flex-col items-center justify-center rounded-r border border-transparent bg-white/35 shadow-sm backdrop-blur-[1px] transition-colors duration-150 select-none opacity-45 hover:border-cyan-400 hover:bg-cyan-100/80 hover:opacity-95"
                    :style="{ width: '16px', height: `${CHART_SUB_PANEL_H}px` }"
                    :title="(PANEL_LABELS[key] ?? key) + '　拖曳調整順序'"
                >
                    <svg width="8" height="14" viewBox="0 0 8 14" fill="currentColor" class="text-slate-500">
                        <circle cx="2" cy="2" r="1.2" />
                        <circle cx="6" cy="2" r="1.2" />
                        <circle cx="2" cy="7" r="1.2" />
                        <circle cx="6" cy="7" r="1.2" />
                        <circle cx="2" cy="12" r="1.2" />
                        <circle cx="6" cy="12" r="1.2" />
                    </svg>
                </div>
            </div>
        </div>
    </div>
</template>

<style scoped>
.chart-touch-surface {
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
}
</style>
