import { createRouter, createWebHistory } from "vue-router";
import { getToken, isLoggedIn, parseUserFromToken } from "../utils/auth";

/** 應用程式使用的路由名稱常數。 */
export const appRouteNames = {
    watchlist: "watchlist",
    adminSchedules: "admin-schedules",
} as const;

const EmptyRouteView = {
    render: () => null,
};

const router = createRouter({
    history: createWebHistory(),
    routes: [
        {
            path: "/",
            name: appRouteNames.watchlist,
            component: EmptyRouteView,
        },
        {
            path: "/admin/schedules",
            name: appRouteNames.adminSchedules,
            component: EmptyRouteView,
        },
        {
            path: "/:pathMatch(.*)*",
            redirect: { name: appRouteNames.watchlist },
        },
    ],
});

router.beforeEach((to) => {
    if (to.name !== appRouteNames.adminSchedules) {
        return true;
    }

    const token = getToken();
    const currentUser = token ? parseUserFromToken(token) : null;

    if (isLoggedIn() && currentUser?.isAdmin) {
        return true;
    }

    return { name: appRouteNames.watchlist };
});

export default router;
