<script setup lang="ts">
import { computed, ref } from "vue";
import type { GroupMember, StockGroup } from "../types";
import type { StockSearchItem, SnapshotItem } from "../../stocks/types";
import { normalizeStockCode } from "../../stocks/utils/stockUtils";
import type { MemberSortKey } from "../composables/useGroupWorkspace";

const props = defineProps<{
    selectedGroup?: StockGroup;
    isSelectedSystemTemplate: boolean;
    searchKeyword: string;
    searchResults: StockSearchItem[];
    isSearching: boolean;
    memberSortKey: MemberSortKey;
    memberSortDir: "asc" | "desc";
    filteredMembers: GroupMember[];
    members: GroupMember[];
    selectedStockCode: string;
    memberSnapshots: Map<string, SnapshotItem>;
    isLoadingMembers: boolean;
    customGroups: StockGroup[];
    membersByGroup: Map<string, Set<string>>;
}>();

const emit = defineEmits<{
    "update:searchKeyword": [value: string];
    "open-mobile-member-search": [];
    "handle-search-enter": [];
    "copy-selected-template": [];
    "add-stock-to-group": [stockCode: string];
    "toggle-member-sort": [key: MemberSortKey];
    "reset-member-sort": [];
    "select-member": [member: GroupMember];
    "remove-stock": [stockCode: string];
    "toggle-custom-group-membership": [payload: { groupId: string; stockCode: string; shouldInclude: boolean }];
}>();

const mobileMemberSectionEl = ref<HTMLElement | null>(null);
const membersListEl = ref<HTMLElement | null>(null);
const activeQuickMenuStockCode = ref<string | null>(null);
const quickGroupMenuEl = ref<HTMLElement | null>(null);

const searchKeywordModel = computed({
    get: () => props.searchKeyword,
    set: (value: string) => emit("update:searchKeyword", value),
});

/** 取得成員列對應的即時快照。 */
function getMemberSnapshot(stockCode: string): SnapshotItem | undefined {
    return props.memberSnapshots.get(stockCode);
}

/** 檢查股票是否在指定群組。 */
function isInCustomGroup(groupId: string, stockCode: string): boolean {
    return props.membersByGroup.get(groupId)?.has(stockCode) ?? false;
}

/** 檢查股票是否在任何自訂群組。 */
function hasAnyCustomGroupMembership(stockCode: string): boolean {
    const code = normalizeStockCode(stockCode);
    return props.customGroups.some((g) => props.membersByGroup.get(g.id)?.has(code));
}

/** 切換快速管理選單。 */
function toggleQuickGroupMenu(stockCode: string): void {
    const code = normalizeStockCode(stockCode);
    if (activeQuickMenuStockCode.value === code) {
        activeQuickMenuStockCode.value = null;
    } else {
        activeQuickMenuStockCode.value = code;
    }
}

/** 點擊外部關閉選單。 */
function onClickOutsideQuickGroupMenu(event: MouseEvent): void {
    if (!activeQuickMenuStockCode.value) return;
    const root = quickGroupMenuEl.value;
    const target = event.target;
    if (!root || !(target instanceof Node)) return;
    if (!root.contains(target)) {
        activeQuickMenuStockCode.value = null;
    }
}

/** 切換自訂群組成員資格。 */
function onToggleCustomGroup(groupId: string, stockCode: string, checked: boolean): void {
    emit("toggle-custom-group-membership", {
        groupId,
        stockCode,
        shouldInclude: checked,
    });
}

import { onMounted, onUnmounted } from "vue";
onMounted(() => {
    document.addEventListener("click", onClickOutsideQuickGroupMenu);
});
onUnmounted(() => {
    document.removeEventListener("click", onClickOutsideQuickGroupMenu);
});

/** 回傳成員面板 DOM 節點，供父層進行手機滑動定位。 */
function getMobileMemberSectionEl(): HTMLElement | null {
    return mobileMemberSectionEl.value;
}

/** 回傳群組成員清單容器，供父層掛載 Sortable。 */
function getMembersListEl(): HTMLElement | null {
    return membersListEl.value;
}

defineExpose({
    getMobileMemberSectionEl,
    getMembersListEl,
});
</script>

<template>
    <section ref="mobileMemberSectionEl" class="member-panel w-120 border-r border-slate-200 overflow-y-auto bg-gradient-to-b from-white/95 to-slate-50/95 backdrop-blur">
        <div class="p-6 max-w-full">
            <article class="rounded-2xl border border-slate-200 bg-white/90 p-6 shadow-lg">
                <div class="member-panel-sticky-header">
                    <h2 class="text-xl font-bold text-slate-900">股票搜尋與群組成員</h2>
                    <p class="mt-1 text-sm text-slate-600">
                        目前群組：<span class="font-semibold text-slate-900">{{ props.selectedGroup?.name ?? "尚未選擇" }}</span>
                    </p>
                    <p v-if="props.selectedGroup?.description" class="mt-0.5 text-xs text-slate-400">{{ props.selectedGroup.description }}</p>
                    <div v-if="props.isSelectedSystemTemplate" class="mt-2 flex items-center gap-2">
                        <p class="text-xs text-amber-700">系統範本為唯讀，請先複製後再編輯</p>
                        <button class="rounded-md border border-amber-300 bg-amber-50 px-2.5 py-1 text-xs font-semibold text-amber-700 hover:bg-amber-100" @click="emit('copy-selected-template')">複製為自訂群組</button>
                    </div>

                    <div class="mt-4">
                        <div class="relative">
                            <input
                                v-model="searchKeywordModel"
                                @click="emit('open-mobile-member-search')"
                                class="mobile-search-input w-full rounded-lg border border-slate-300 px-3 py-2 pr-8 text-sm outline-none transition focus:border-cyan-500 focus:ring-2 focus:ring-cyan-200"
                                type="text"
                                placeholder="輸入代碼、名稱或分類關鍵字，例如 2330 / 鋼鐵 / 台商"
                                @keydown.enter.prevent="emit('handle-search-enter')"
                            />
                            <button v-if="props.searchKeyword" type="button" class="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600" tabindex="-1" @click="emit('update:searchKeyword', '')">✕</button>
                        </div>
                        <p class="mt-1 text-xs text-slate-500">支援模糊搜尋，結果最多 20 筆。按 Enter 可快速加入第一筆結果。</p>
                    </div>
                </div>

                <section class="mt-4">
                    <h3 class="mb-2 text-sm font-semibold text-slate-800">搜尋結果</h3>
                    <ul class="max-h-64 space-y-2 overflow-auto pr-1">
                        <li v-for="item in props.searchResults" :key="item.stockCode" class="rounded-lg border border-slate-200 p-3">
                            <div class="flex items-start justify-between gap-3">
                                <div>
                                    <p class="font-semibold text-slate-900">{{ item.stockCode }} · {{ item.stockName }}</p>
                                </div>
                                <button class="shrink-0 rounded-md px-2.5 py-1.5 text-xs font-semibold text-white" :class="props.isSelectedSystemTemplate ? 'cursor-not-allowed bg-slate-300' : 'bg-cyan-600 hover:bg-cyan-500'" :disabled="props.isSelectedSystemTemplate" @click="emit('add-stock-to-group', item.stockCode)">加入群組</button>
                            </div>
                        </li>
                    </ul>
                    <p v-if="props.isSearching" class="mt-2 text-xs text-slate-500">搜尋中...</p>
                </section>

                <section class="mt-6">
                    <div class="mb-2 flex items-center justify-between">
                        <h3 class="text-sm font-semibold text-slate-800">群組成員</h3>
                        <div class="flex items-center gap-1">
                            <span class="text-xs text-slate-400 mr-0.5">排序</span>
                            <button
                                v-for="sort in [
                                    { key: 'price', label: '價格' },
                                    { key: 'change', label: '漲幅' },
                                    { key: 'volume', label: '量' },
                                ] as const"
                                :key="sort.key"
                                @click="emit('toggle-member-sort', sort.key)"
                                class="flex items-center gap-0.5 rounded px-1.5 py-0.5 text-xs font-semibold transition"
                                :class="props.memberSortKey === sort.key ? 'bg-cyan-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'"
                            >
                                {{ sort.label }}
                                <span v-if="props.memberSortKey === sort.key" class="text-[10px] leading-none">{{ props.memberSortDir === "desc" ? "▼" : "▲" }}</span>
                            </button>
                            <button v-if="props.memberSortKey !== 'default'" @click="emit('reset-member-sort')" class="rounded px-1.5 py-0.5 text-xs text-slate-400 hover:text-slate-600 transition" title="清除排序">✕</button>
                        </div>
                    </div>
                    <div ref="membersListEl" class="max-h-190 space-y-2 overflow-auto pr-1">
                        <div
                            v-for="item in props.filteredMembers"
                            :key="item.stockCode"
                            class="drag-row relative flex items-center justify-between rounded-lg border p-2.5 transition-colors transition-shadow"
                            :class="[props.selectedStockCode === normalizeStockCode(item.stockCode) ? 'bg-cyan-100 border-cyan-400 shadow-sm ring-2 ring-cyan-300' : 'border-slate-200 hover:bg-slate-50', props.memberSortKey === 'default' && !props.searchKeyword.trim() ? 'cursor-grab' : 'cursor-pointer']"
                            @click="emit('select-member', item)"
                        >
                            <span v-if="props.memberSortKey === 'default' && !props.searchKeyword.trim() && !props.isSelectedSystemTemplate" class="mr-1.5 shrink-0 cursor-grab text-base leading-none opacity-25 select-none" title="拖曳排序">⠿</span>

                            <div class="flex items-center gap-2">
                                <div class="relative shrink-0">
                                    <button
                                        type="button"
                                        class="inline-flex h-6 w-6 items-center justify-center rounded-full border border-slate-200 bg-white shadow-sm transition hover:border-amber-300 hover:text-amber-500"
                                        :class="hasAnyCustomGroupMembership(item.stockCode) ? 'text-amber-500 border-amber-300 bg-amber-50' : 'text-slate-400'"
                                        title="管理自訂群組"
                                        @click.stop="toggleQuickGroupMenu(item.stockCode)"
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" class="h-3.5 w-3.5">
                                            <path
                                                fill="currentColor"
                                                :class="hasAnyCustomGroupMembership(item.stockCode) ? 'opacity-100' : 'opacity-0'"
                                                d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.08 3.32a1 1 0 00.95.69h3.49c.969 0 1.371 1.24.588 1.81l-2.824 2.053a1 1 0 00-.364 1.118l1.079 3.32c.3.922-.755 1.688-1.54 1.118l-2.823-2.052a1 1 0 00-1.176 0l-2.823 2.052c-.785.57-1.84-.196-1.54-1.118l1.079-3.32a1 1 0 00-.364-1.118L2.94 8.747c-.783-.57-.38-1.81.588-1.81h3.49a1 1 0 00.95-.69l1.08-3.32z"
                                            />
                                            <path
                                                fill="none"
                                                stroke="currentColor"
                                                stroke-width="1.5"
                                                stroke-linecap="round"
                                                stroke-linejoin="round"
                                                d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.08 3.32a1 1 0 00.95.69h3.49c.969 0 1.371 1.24.588 1.81l-2.824 2.053a1 1 0 00-.364 1.118l1.079 3.32c.3.922-.755 1.688-1.54 1.118l-2.823-2.052a1 1 0 00-1.176 0l-2.823 2.052c-.785.57-1.84-.196-1.54-1.118l1.079-3.32a1 1 0 00-.364-1.118L2.94 8.747c-.783-.57-.38-1.81.588-1.81h3.49a1 1 0 00.95-.69l1.08-3.32z"
                                            />
                                        </svg>
                                    </button>

                                    <div v-if="activeQuickMenuStockCode === normalizeStockCode(item.stockCode)" ref="quickGroupMenuEl" class="absolute left-0 top-8 z-50 w-56 rounded-xl border border-slate-200 bg-white p-2 shadow-xl" @click.stop>
                                        <p class="mb-2 px-1 text-xs font-bold uppercase tracking-wider text-slate-400">快速管理自訂群組</p>
                                        <div v-if="props.customGroups.length === 0" class="rounded-lg bg-slate-50 px-2 py-2 text-sm text-slate-500">尚未建立自訂群組</div>
                                        <div v-else class="max-h-48 space-y-1 overflow-y-auto pr-1">
                                            <label v-for="group in props.customGroups" :key="group.id" class="flex cursor-pointer items-center gap-2 rounded-lg px-2 py-1.5 text-sm text-slate-700 transition hover:bg-slate-50">
                                                <input type="checkbox" class="h-4 w-4 rounded border-slate-300 text-cyan-600 focus:ring-cyan-400" :checked="isInCustomGroup(group.id, item.stockCode)" @change="onToggleCustomGroup(group.id, item.stockCode, ($event.target as HTMLInputElement).checked)" />
                                                <span class="truncate">{{ group.name }}</span>
                                            </label>
                                        </div>
                                    </div>
                                </div>
                                <span class="text-sm text-slate-800 shrink-0">{{ item.stockCode }} · {{ item.stockName }}</span>
                            </div>

                            <template v-if="getMemberSnapshot(item.stockCode)">
                                <span class="mx-2 flex flex-1 flex-col items-end min-w-0 gap-0">
                                    <span class="flex items-center gap-1.5">
                                        <span class="text-sm font-semibold tabular-nums" :class="(getMemberSnapshot(item.stockCode)?.change ?? 0) >= 0 ? 'text-red-600' : 'text-green-600'">{{ (getMemberSnapshot(item.stockCode)?.lastPrice ?? getMemberSnapshot(item.stockCode)?.closePrice)?.toFixed(2) ?? "—" }}</span>
                                        <span class="text-xs font-bold tabular-nums text-slate-600">
                                            {{ getMemberSnapshot(item.stockCode)?.tradeVolume != null ? Math.round(getMemberSnapshot(item.stockCode)!.tradeVolume!).toLocaleString() + "張" : "" }}
                                        </span>
                                    </span>
                                    <span class="flex items-center gap-1.5">
                                        <span class="text-xs font-bold tabular-nums" :class="(getMemberSnapshot(item.stockCode)?.change ?? 0) >= 0 ? 'text-red-500' : 'text-green-500'">
                                            {{ getMemberSnapshot(item.stockCode)?.change != null ? getMemberSnapshot(item.stockCode)!.change! : "" }}
                                        </span>
                                        <span class="text-xs font-bold tabular-nums" :class="(getMemberSnapshot(item.stockCode)?.change ?? 0) >= 0 ? 'text-red-500' : 'text-green-500'">{{ "(" + ((getMemberSnapshot(item.stockCode)?.changePercent ?? 0) >= 0 ? "+" : "") + (getMemberSnapshot(item.stockCode)?.changePercent?.toFixed(2) ?? "—") + "%)" }}</span>
                                    </span>
                                </span>
                            </template>
                            <span v-else class="flex-1"></span>
                            <button class="shrink-0 rounded-md border px-2.5 py-1 text-xs font-semibold" :class="props.isSelectedSystemTemplate ? 'cursor-not-allowed border-slate-300 bg-slate-100 text-slate-400' : 'border-rose-300 bg-rose-50 text-rose-700 hover:bg-rose-100'" :disabled="props.isSelectedSystemTemplate" @click.stop="emit('remove-stock', item.stockCode)">移除</button>
                        </div>
                    </div>
                    <p v-if="props.isLoadingMembers" class="mt-2 text-xs text-slate-500">載入成員中...</p>
                    <p v-else-if="props.searchKeyword.trim() && props.members.length > 0 && props.filteredMembers.length === 0" class="mt-2 text-xs text-slate-500">此群組沒有符合搜尋關鍵字的成員</p>
                </section>
            </article>
        </div>
    </section>
</template>
