import type { ApiRequest } from "../../shared/api/httpClient";
import type { GroupMember, StockGroup } from "./types";

/** 封裝股票群組相關 API。 */
export function createGroupsApi(request: ApiRequest) {
    /** 讀取群組清單，可選擇帶入搜尋關鍵字。 */
    async function listGroups(keyword?: string): Promise<StockGroup[]> {
        const normalizedKeyword = keyword?.trim() ?? "";
        const query = normalizedKeyword ? `?keyword=${encodeURIComponent(normalizedKeyword)}` : "";
        return request<StockGroup[]>(`/api/groups${query}`);
    }

    /** 讀取指定群組的成員清單。 */
    async function listGroupMembers(groupId: string): Promise<GroupMember[]> {
        return request<GroupMember[]>(`/api/groups/${groupId}/stocks`);
    }

    /** 建立自訂群組。 */
    async function createGroup(name: string, description: string): Promise<StockGroup> {
        return request<StockGroup>("/api/groups", {
            method: "POST",
            body: JSON.stringify({ name, description }),
        });
    }

    /** 新增股票至指定群組。 */
    async function addStockToGroup(groupId: string, stockCode: string): Promise<void> {
        await request<void>(`/api/groups/${groupId}/stocks`, {
            method: "POST",
            body: JSON.stringify({ stockCode }),
        });
    }

    /** 從指定群組移除股票。 */
    async function removeStockFromGroup(groupId: string, stockCode: string): Promise<void> {
        await request<void>(`/api/groups/${groupId}/stocks/${stockCode}`, {
            method: "DELETE",
        });
    }

    /** 複製系統範本群組。 */
    async function copyGroup(groupId: string): Promise<StockGroup> {
        return request<StockGroup>(`/api/groups/${groupId}/copy`, {
            method: "POST",
        });
    }

    /** 刪除指定群組。 */
    async function deleteGroup(groupId: string): Promise<void> {
        await request<void>(`/api/groups/${groupId}`, { method: "DELETE" });
    }

    /** 更新自訂群組排序。 */
    async function updateCustomGroupOrder(groupIds: string[]): Promise<void> {
        await request<void>("/api/groups/custom-order", {
            method: "POST",
            body: JSON.stringify({ groupIds }),
        });
    }

    /** 更新指定群組的成員排序。 */
    async function updateMemberOrder(groupId: string, stockCodes: string[]): Promise<void> {
        await request<void>(`/api/groups/${groupId}/member-order`, {
            method: "POST",
            body: JSON.stringify({ stockCodes }),
        });
    }

    /** 更新群組名稱與描述。 */
    async function renameGroup(groupId: string, name: string, description: string | null): Promise<StockGroup> {
        return request<StockGroup>(`/api/groups/${groupId}/name`, {
            method: "PATCH",
            body: JSON.stringify({ name, description }),
        });
    }

    return {
        listGroups,
        listGroupMembers,
        createGroup,
        addStockToGroup,
        removeStockFromGroup,
        copyGroup,
        deleteGroup,
        updateCustomGroupOrder,
        updateMemberOrder,
        renameGroup,
    };
}
