// 從 Vue 核心套件引入 createApp 函式，用於建立 Vue 應用程式實例
import { createApp } from "vue";
// 引入 vue-toastification 插件（Toast 通知元件）及其型別定義與位置常數
import Toast, { type PluginOptions, POSITION } from "vue-toastification";
// 引入 vue-toastification 的預設 CSS 樣式（包含動畫、顏色等外觀設定）
import "vue-toastification/dist/index.css";
// 引入全域自定義 CSS 樣式（包括 Tailwind CSS 指令與自訂變數）
import "./style.css";
// 引入根元件 App.vue（整個單頁應用程式的入口元件）
import App from "./App.vue";
import router from "./router";
// 引入開發環境 API 請求日誌工具（僅在 DEV 模式下啟用，正式環境自動略過）
import { setupDevApiLogger } from "./utils/devApiLogger";

/**
 * vue-toastification 插件的全域設定選項。
 * 控制所有 Toast 通知的預設外觀與行為。
 */
const toastOptions: PluginOptions = {
    position: POSITION.TOP_RIGHT, // Toast 顯示位置：右上角
    timeout: 3000, // 自動關閉時間：3000 毫秒（3 秒）後自動消失
    closeOnClick: true, // 允許用戶點擊 Toast 來立即關閉
    pauseOnHover: true, // 滑鼠停留於 Toast 時暫停計時，防止訊息太快消失
    draggable: true, // 允許用戶拖動 Toast 元件到其他位置
};

// 在應用程式啟動時安裝 API 請求攔截器
// 開發環境：在 console 中顯示每次 fetch 請求的詳細資訊（URL、標頭、回應等）
// 正式環境：此函式內部的 if(!DEV) 分支讓其立即返回，不做任何事
setupDevApiLogger();

// 建立 Vue 應用程式實例，以 App.vue 作為根元件
// .use(Toast, toastOptions)：安裝 Toast 通知插件，讓所有元件可透過 useToast() 使用
// .mount("#app")：將應用程式掛載至 HTML 中 id="app" 的 DOM 節點（index.html 中定義）
createApp(App).use(router).use(Toast, toastOptions).mount("#app");
