<script setup lang="ts">
import { PAGE_SIZE_OPTIONS, type PaginationControls } from "../composables/usePagination";

defineProps<{ pg: PaginationControls }>();
</script>

<template>
    <div class="flex flex-wrap items-center justify-between gap-2 text-xs text-slate-500">
        <!-- 左：每頁筆數設定 -->
        <div class="flex items-center gap-2">
            <span>每頁</span>
            <input v-model="pg.pageSizeInput.value" type="number" min="1" placeholder="數量" class="w-16 rounded border border-slate-200 bg-white px-2 py-1 text-center text-xs focus:border-cyan-400 focus:outline-none" />
            <span>筆</span>
            <span class="text-slate-300">|</span>
            <button v-for="n in PAGE_SIZE_OPTIONS" :key="n" type="button" class="rounded px-2 py-0.5 transition" :class="!pg.showAll.value && pg.pageSize.value === n ? 'bg-cyan-50 font-semibold text-cyan-700' : 'hover:bg-slate-100'" @click="pg.pageSizeInput.value = String(n)">{{ n }}</button>
            <button type="button" class="rounded px-2 py-0.5 transition" :class="pg.showAll.value ? 'bg-cyan-50 font-semibold text-cyan-700' : 'hover:bg-slate-100'" @click="pg.pageSizeInput.value = ''">全部</button>
        </div>

        <!-- 右：頁碼導航 -->
        <div class="flex items-center gap-1">
            <span class="mr-1 text-slate-400">
                {{ pg.showAll.value ? `共 ${pg.totalCount.value} 筆` : `第 ${pg.currentPage.value} / ${pg.totalPages.value} 頁（共 ${pg.totalCount.value} 筆）` }}
            </span>
            <button type="button" class="rounded px-2 py-0.5 hover:bg-slate-100 disabled:opacity-30" :disabled="pg.showAll.value || pg.currentPage.value <= 1" @click="pg.currentPage.value = 1">«</button>
            <button type="button" class="rounded px-2 py-0.5 hover:bg-slate-100 disabled:opacity-30" :disabled="pg.showAll.value || pg.currentPage.value <= 1" @click="pg.currentPage.value--">‹</button>
            <button type="button" class="rounded px-2 py-0.5 hover:bg-slate-100 disabled:opacity-30" :disabled="pg.showAll.value || pg.currentPage.value >= pg.totalPages.value" @click="pg.currentPage.value++">›</button>
            <button type="button" class="rounded px-2 py-0.5 hover:bg-slate-100 disabled:opacity-30" :disabled="pg.showAll.value || pg.currentPage.value >= pg.totalPages.value" @click="pg.currentPage.value = pg.totalPages.value">»</button>
        </div>
    </div>
</template>
