import { ref } from "vue";
import { clearToken, getToken, isLoggedIn, parseUserFromToken, setToken, type AuthUser } from "../../../utils/auth";

/**
 * 管理前端登入工作階段。
 * 負責接收 OAuth redirect token、解析 JWT 與提供登出重置行為。
 */
export function useAuthSession() {
    const currentUser = ref<AuthUser | null>(null);
    const authChecked = ref(false);

    /**
     * 初始化目前頁面的登入狀態。
     *
     * 核心逻輯（SEC-2 修正）：
     * - 從 URL hash fragment（`#token=...`）讀取 JWT，而非 query string（`?token=...`）
     * - URL hash fragment 不會被剛到伺服器日誌，不會包含在 HTTP Referer 標頭中，較安全
     * - 寫入 localStorage 後立即清除 hash，避免首頁 URL 枰留 JWT
     */
    function initializeAuthSession(): AuthUser | null {
        // SEC-2：從 hash fragment 讀取 token（如 "#token=eyJhbGci..."）
        // location.hash 格式為 "#key=value&other=..."，需去除開頭 "#"
        const hash = globalThis.location.hash;
        if (hash.startsWith("#")) {
            const hashParams = new URLSearchParams(hash.slice(1)); // 切除 "#" 前綴
            const tokenFromHash = hashParams.get("token");
            if (tokenFromHash) {
                // 將 token 儲存後立即清除 hash，防止 token 殘留在 URL
                setToken(tokenFromHash);
                // replaceState 不會發生頁面重整，只清除 URL 中的 hash 陥段
                globalThis.history.replaceState({}, document.title, globalThis.location.pathname);
            }
        }

        if (isLoggedIn()) {
            const token = getToken();
            currentUser.value = token ? parseUserFromToken(token) : null;
        } else {
            currentUser.value = null;
        }

        authChecked.value = true;
        return currentUser.value;
    }

    /** 清除前端登入狀態與 JWT。 */
    function logout() {
        clearToken();
        currentUser.value = null;
    }

    return {
        currentUser,
        authChecked,
        initializeAuthSession,
        logout,
    };
}
