import { computed, onUnmounted, ref, watch } from "vue";
import type { ApiRequest } from "../../../shared/api/httpClient";
import { createStocksApi } from "../api";
import type { BasicInfo, IntradayTicker, SnapshotItem, StockCategoryGroup } from "../types";
import { createKBarData, isMarketOpen, normalizeStockCode, type DetailTabKey } from "../utils/stockUtils";
import type { GroupMember } from "../../groups/types";

/**
 * 封裝股票明細區的即時快照、Ticker、分類、基本資訊與頁籤狀態。
 */
export function useStockDetails(options: { request: ApiRequest }) {
    const stocksApi = createStocksApi(options.request);

    const selectedStock = ref<GroupMember | null>(null);
    const detailTab = ref<DetailTabKey>("overview");
    const snapshot = ref<SnapshotItem | null>(null);
    const isLoadingSnapshot = ref(false);
    const snapshotError = ref<string | null>(null);
    const ticker = ref<IntradayTicker | null>(null);
    const isLoadingTicker = ref(false);
    const tickerError = ref<string | null>(null);
    const categoryGroups = ref<StockCategoryGroup[]>([]);
    const isLoadingCategories = ref(false);
    const basicInfo = ref<BasicInfo | null>(null);
    const isLoadingBasicInfo = ref(false);

    const safeDetailTab = computed<DetailTabKey>(() => detailTab.value);
    const selectedStockCode = computed(() => normalizeStockCode(selectedStock.value?.stockCode));
    const detailContentKey = computed(() => `${selectedStockCode.value || "none"}:${safeDetailTab.value}`);
    const isAtLimitUp = computed(() => {
        const price = snapshot.value?.lastPrice ?? snapshot.value?.closePrice;
        const limitUp = ticker.value?.limitUpPrice;
        return price !== null && price !== undefined && limitUp !== null && limitUp !== undefined && price >= limitUp;
    });
    const isAtLimitDown = computed(() => {
        const price = snapshot.value?.lastPrice ?? snapshot.value?.closePrice;
        const limitDown = ticker.value?.limitDownPrice;
        return price !== null && price !== undefined && limitDown !== null && limitDown !== undefined && price <= limitDown;
    });
    const kBarData = computed(() => createKBarData(snapshot.value));

    let snapshotTimer: number | undefined;
    let stockRequestVersion = 0;

    /** 檢查回來的非同步資料是否仍屬於目前選中的股票。 */
    function isCurrentStockRequest(stockCode: string, requestVersion: number): boolean {
        return requestVersion === stockRequestVersion && selectedStockCode.value === normalizeStockCode(stockCode);
    }

    /** 設定目前顯示中的股票頁籤。 */
    function setDetailTab(tab: DetailTabKey) {
        detailTab.value = tab;
    }

    /** 選取目前顯示的股票。 */
    function selectStock(member: GroupMember | null) {
        if (!member) {
            selectedStock.value = null;
            return;
        }

        selectedStock.value = {
            stockCode: normalizeStockCode(member.stockCode),
            stockName: member.stockName,
        };
    }

    /** 讀取指定股票的即時快照。 */
    async function fetchSnapshot(stockCode: string, requestVersion = stockRequestVersion) {
        isLoadingSnapshot.value = true;
        snapshotError.value = null;
        try {
            const allSnapshots = await stocksApi.fetchAllSnapshots();
            if (!isCurrentStockRequest(stockCode, requestVersion)) {
                return;
            }
            snapshot.value = allSnapshots.get(normalizeStockCode(stockCode)) ?? null;
        } catch (error) {
            if (!isCurrentStockRequest(stockCode, requestVersion)) {
                return;
            }
            snapshotError.value = error instanceof Error ? error.message : "無法取得快照資料";
            snapshot.value = null;
        } finally {
            if (isCurrentStockRequest(stockCode, requestVersion)) {
                isLoadingSnapshot.value = false;
            }
        }
    }

    /** 啟動個股快照輪詢。 */
    function startSnapshotPolling(stockCode: string, requestVersion = stockRequestVersion) {
        stopSnapshotPolling();
        void fetchSnapshot(stockCode, requestVersion);
        snapshotTimer = globalThis.setInterval(() => {
            if (isMarketOpen()) {
                void fetchSnapshot(stockCode, requestVersion);
            }
        }, 1000);
    }

    /** 停止個股快照輪詢並清空快照狀態。 */
    function stopSnapshotPolling() {
        if (snapshotTimer !== undefined) {
            globalThis.clearInterval(snapshotTimer);
            snapshotTimer = undefined;
        }

        snapshot.value = null;
        snapshotError.value = null;
        isLoadingSnapshot.value = false;
    }

    /** 讀取指定股票的 Ticker。 */
    async function fetchTicker(stockCode: string, requestVersion = stockRequestVersion) {
        isLoadingTicker.value = true;
        tickerError.value = null;
        try {
            const nextTicker = await stocksApi.fetchTicker(stockCode);
            if (!isCurrentStockRequest(stockCode, requestVersion)) {
                return;
            }
            ticker.value = nextTicker;
        } catch (error) {
            if (!isCurrentStockRequest(stockCode, requestVersion)) {
                return;
            }
            tickerError.value = error instanceof Error ? error.message : "無法取得 Ticker 資料";
            ticker.value = null;
        } finally {
            if (isCurrentStockRequest(stockCode, requestVersion)) {
                isLoadingTicker.value = false;
            }
        }
    }

    /** 清空 Ticker 相關狀態。 */
    function clearTicker() {
        ticker.value = null;
        tickerError.value = null;
        isLoadingTicker.value = false;
    }

    /** 清空分類群組資訊。 */
    function clearCategoryGroups() {
        categoryGroups.value = [];
        isLoadingCategories.value = false;
    }

    /** 讀取指定股票的分類群組資訊。 */
    async function fetchCategoryGroups(stockCode: string, requestVersion = stockRequestVersion) {
        isLoadingCategories.value = true;
        try {
            const nextCategoryGroups = await stocksApi.fetchCategoryGroups(stockCode);
            if (!isCurrentStockRequest(stockCode, requestVersion)) {
                return;
            }
            categoryGroups.value = nextCategoryGroups;
        } catch {
            if (!isCurrentStockRequest(stockCode, requestVersion)) {
                return;
            }
            categoryGroups.value = [];
        } finally {
            if (isCurrentStockRequest(stockCode, requestVersion)) {
                isLoadingCategories.value = false;
            }
        }
    }

    /** 清空股票基本資訊。 */
    function clearBasicInfo() {
        basicInfo.value = null;
        isLoadingBasicInfo.value = false;
    }

    /** 讀取指定股票的基本資訊。 */
    async function fetchBasicInfo(stockCode: string, requestVersion = stockRequestVersion) {
        isLoadingBasicInfo.value = true;
        try {
            const nextBasicInfo = await stocksApi.fetchBasicInfo(stockCode);
            if (!isCurrentStockRequest(stockCode, requestVersion)) {
                return;
            }
            basicInfo.value = nextBasicInfo;
        } catch {
            if (!isCurrentStockRequest(stockCode, requestVersion)) {
                return;
            }
            basicInfo.value = null;
        } finally {
            if (isCurrentStockRequest(stockCode, requestVersion)) {
                isLoadingBasicInfo.value = false;
            }
        }
    }

    /** 清空整個股票明細工作區。 */
    function resetStockDetails() {
        stockRequestVersion += 1;
        selectedStock.value = null;
        detailTab.value = "overview";
        stopSnapshotPolling();
        clearTicker();
        clearCategoryGroups();
        clearBasicInfo();
    }

    watch(selectedStock, (stock) => {
        if (stock) {
            const requestVersion = stockRequestVersion + 1;
            stockRequestVersion = requestVersion;
            stopSnapshotPolling();
            clearTicker();
            clearCategoryGroups();
            clearBasicInfo();
            startSnapshotPolling(stock.stockCode, requestVersion);
            void fetchTicker(stock.stockCode, requestVersion);
            void fetchCategoryGroups(stock.stockCode, requestVersion);
            void fetchBasicInfo(stock.stockCode, requestVersion);
            return;
        }

        stockRequestVersion += 1;
        stopSnapshotPolling();
        clearTicker();
        clearCategoryGroups();
        clearBasicInfo();
    });

    onUnmounted(() => {
        stopSnapshotPolling();
    });

    return {
        selectedStock,
        detailTab,
        safeDetailTab,
        selectedStockCode,
        detailContentKey,
        snapshot,
        isLoadingSnapshot,
        snapshotError,
        ticker,
        isLoadingTicker,
        tickerError,
        categoryGroups,
        isLoadingCategories,
        basicInfo,
        isLoadingBasicInfo,
        isAtLimitUp,
        isAtLimitDown,
        kBarData,
        setDetailTab,
        selectStock,
        resetStockDetails,
        stopSnapshotPolling,
    };
}
