import { ref } from "vue";

export interface ChartPreferences {
    panelOrder?: string[];
    showBollinger?: boolean;
    showRsi?: boolean;
    showMacd?: boolean;
    showKd?: boolean;
    showDmi?: boolean;
    showLargeHolder?: boolean;
    showSmallHolder?: boolean;
    showMainForce?: boolean;
    showInstForeign?: boolean;
    showInstTrust?: boolean;
    showInstHedging?: boolean;
    showInstDealer?: boolean;
}

export function useChartPreferences(apiBaseUrl: string, getToken: () => string | null) {
    const preferencesLoaded = ref(false);

    async function loadPreferences(): Promise<ChartPreferences | null> {
        try {
            const token = getToken();
            if (!token) return null;

            const res = await fetch(`${apiBaseUrl}/api/auth/me/preferences`, {
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            });
            if (!res.ok) return null;

            const data = await res.json();
            if (data.chartPreferences) {
                const prefs = JSON.parse(data.chartPreferences) as ChartPreferences;
                return prefs;
            }
        } catch (e) {
            console.error("Failed to load chart preferences", e);
        } finally {
            preferencesLoaded.value = true;
        }
        return null;
    }

    async function savePreferences(prefs: ChartPreferences) {
        try {
            const token = getToken();
            if (!token) return;

            await fetch(`${apiBaseUrl}/api/auth/me/preferences`, {
                method: "PUT",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ chartPreferences: JSON.stringify(prefs) }),
            });
        } catch (e) {
            console.error("Failed to save chart preferences", e);
        }
    }

    return {
        preferencesLoaded,
        loadPreferences,
        savePreferences,
    };
}
