import { onUnmounted, ref } from "vue";
import * as signalR from "@microsoft/signalr";

export type IndexData = {
    symbol: string;
    name: string;
    index: number;
    direction: "up" | "down" | "neutral";
    time: number;
};

export type ConnectionStatus = "connecting" | "connected" | "reconnecting" | "disconnected";

/**
 * 透過 SignalR WebSocket 接收後端推播的指數即時行情（加權指數、櫃買報酬指數）。
 * 自動管理連線生命週期，元件 unmount 時自動斷線。
 */
export function useIndexStream(hubUrl: string) {
    const indices = ref<Map<string, IndexData>>(new Map());
    const status = ref<ConnectionStatus>("connecting");

    const connection = new signalR.HubConnectionBuilder()
        .withUrl(hubUrl, {
            // 優先使用 WebSocket，長輪詢作為 fallback
            transport: signalR.HttpTransportType.WebSockets | signalR.HttpTransportType.LongPolling,
        })
        .withAutomaticReconnect([0, 2000, 5000, 10000, 30000])
        .configureLogging(signalR.LogLevel.Warning)
        .build();

    connection.on("IndexUpdate", (data: IndexData) => {
        indices.value = new Map(indices.value).set(data.symbol, data);
    });

    connection.onreconnecting(() => {
        status.value = "reconnecting";
    });

    connection.onreconnected(() => {
        status.value = "connected";
    });

    connection.onclose(() => {
        status.value = "disconnected";
    });

    async function start() {
        try {
            await connection.start();
            status.value = "connected";
        } catch {
            status.value = "disconnected";
            // 非致命性錯誤，連線失敗時 SDK 未啟用或後端未啟動，靜默處理
        }
    }

    void start();

    onUnmounted(() => {
        void connection.stop();
    });

    return { indices, status };
}
