<script setup lang="ts">
import { computed } from "vue";
import { useIndexStream, type ConnectionStatus, type IndexData } from "../composables/useIndexStream";

const props = defineProps<{
    hubUrl: string;
}>();

const { indices, status } = useIndexStream(props.hubUrl);

const SYMBOLS = ["IX0001", "IX0043"] as const;

function getIndex(symbol: string): IndexData | undefined {
    return indices.value.get(symbol);
}

/** 根據漲跌方向回傳文字色彩 class */
function directionClass(direction: IndexData["direction"]): string {
    if (direction === "up") return "text-rose-500";
    if (direction === "down") return "text-emerald-500";
    return "text-slate-500";
}

/** 漲跌方向箭頭符號 */
function directionArrow(direction: IndexData["direction"]): string {
    if (direction === "up") return "▲";
    if (direction === "down") return "▼";
    return "—";
}

/** 格式化指數點位：加千分位，保留兩位小數 */
function formatIndex(value: number): string {
    return value.toLocaleString("zh-TW", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

/** 連線狀態對應的顯示文字與樣式 */
const statusConfig = computed<{ dot: string; label: string }>(() => {
    const map: Record<ConnectionStatus, { dot: string; label: string }> = {
        connecting: { dot: "bg-amber-400 animate-pulse", label: "連線中" },
        connected: { dot: "bg-emerald-400 animate-pulse", label: "" },
        reconnecting: { dot: "bg-amber-400 animate-pulse", label: "重連中" },
        disconnected: { dot: "bg-slate-300", label: "已斷線" },
    };
    return map[status.value];
});
</script>

<template>
    <div class="flex items-center gap-3">
        <!-- 每個指數卡片 -->
        <div v-for="symbol in SYMBOLS" :key="symbol" class="flex flex-col items-start min-w-[108px] rounded-xl border border-slate-200 bg-slate-50/80 px-3 py-1.5 shadow-sm">
            <span class="text-[10px] font-semibold uppercase tracking-wider text-slate-400 leading-none mb-0.5">
                {{ symbol }}
            </span>

            <!-- 載入中骨架 -->
            <template v-if="!getIndex(symbol)">
                <div class="h-4 w-20 animate-pulse rounded bg-slate-200 mb-0.5"></div>
                <div class="h-3 w-12 animate-pulse rounded bg-slate-100"></div>
            </template>

            <!-- 實際資料 -->
            <template v-else>
                <span class="text-base font-black tabular-nums leading-tight transition-colors duration-300" :class="directionClass(getIndex(symbol)!.direction)">
                    {{ formatIndex(getIndex(symbol)!.index) }}
                </span>
                <div class="flex items-center gap-1 mt-0.5">
                    <span class="text-[11px] font-bold leading-none transition-colors duration-300" :class="directionClass(getIndex(symbol)!.direction)">
                        {{ directionArrow(getIndex(symbol)!.direction) }}
                    </span>
                    <span class="text-[11px] text-slate-500 leading-none">
                        {{ getIndex(symbol)!.name }}
                    </span>
                </div>
            </template>
        </div>

        <!-- 連線狀態指示器 -->
        <div class="flex flex-col items-center gap-1" :title="`指數串流：${status}`">
            <div class="h-2 w-2 rounded-full" :class="statusConfig.dot"></div>
            <span v-if="statusConfig.label" class="text-[9px] text-slate-400 leading-none">
                {{ statusConfig.label }}
            </span>
        </div>
    </div>
</template>
