<script setup lang="ts">
// 從 Vue 引入 ref，建立響應式變數（響應式資料變更時自動更新 DOM）
import { ref } from "vue";
// 引入 vue-toastification 的 useToast，用於顯示操作結果的通知訊息
import { useToast } from "vue-toastification";
import { setToken } from "../utils/auth";
import { apiBaseUrl } from "../shared/config/env";

// 取得 Toast 通知實例，用於顯示成功/錯誤訊息
const toast = useToast();

// 登入模式切換狀態："google" = Google OAuth 登入；"admin" = 帳號密碼登入
// 預設顯示 Google 登入模式
const loginMode = ref<"google" | "admin">("google");

// 管理員登入表單欄位（預先填入預設測試帳號，方便開發時使用）
const email = ref(""); // 管理員 Email 帳號輸入 (admin@stockgroup.local)
const password = ref(""); // 管理員密碼輸入（預設測試密碼） (admin123)
const isLoading = ref(false); // 登入請求進行中的 loading 狀態

/**
 * 觸發 Google OAuth 登入流程。
 * 將使用者導向後端的 Google OAuth 起始端點，由後端負責重新導向至 Google 授權頁面。
 * 登入完成後 Google 會回呼後端，後端再帶著 JWT Token 重新導向回前端。
 */
function loginWithGoogle() {
    // 直接改變 window.location.href 以發起完整的頁面跳轉（非 fetch 請求）
    // 後端 /api/auth/login/google 會回傳 302 Redirect 到 Google OAuth 頁面
    globalThis.location.href = `${apiBaseUrl}/api/auth/login/google`;
}

/**
 * 執行管理員帳號密碼登入。
 * 透過 POST /api/auth/login 傳送帳號密碼，成功時儲存 JWT Token 並重新整理頁面。
 */
async function loginWithPassword() {
    // 防呆驗證：帳號或密碼任一為空時，顯示提示並停止登入
    if (!email.value || !password.value) {
        toast.error("請輸入帳號和密碼");
        return;
    }

    // 開始顯示 loading 狀態，並鎖定登入按鈕防止重複提交
    isLoading.value = true;

    try {
        // 向後端 /api/auth/login 發送 POST 請求
        const response = await fetch(`${apiBaseUrl}/api/auth/login`, {
            method: "POST", // HTTP 方法：POST
            headers: { "Content-Type": "application/json" }, // 告知後端請求主體為 JSON 格式
            body: JSON.stringify({ email: email.value, password: password.value }), // 將表單資料序列化為 JSON
        });

        // 若後端回傳非 2xx 狀態碼（如 401 帳號密碼錯誤），讀取錯誤訊息並拋出例外
        if (!response.ok) {
            // 讀取後端回傳的 JSON 錯誤訊息（格式：{ message: "..." }）
            const data = await response.json();
            // 若後端沒有提供 message，顯示通用錯誤訊息
            throw new Error(data.message || "登入失敗");
        }

        // 登入成功：從回應中取出 JWT Token
        const { token } = await response.json();

        // 將 JWT Token 儲存至 localStorage（其他頁面和元件可透過 getToken() 取得）
        setToken(token);

        // 重新整理頁面以觸發身分驗證狀態重新初始化（App.vue 的 onMounted 會重新讀取 Token）
        globalThis.location.href = "/";
    } catch (error) {
        // 顯示錯誤訊息 Toast，優先使用 Error 物件的 message，否則顯示通用訊息
        toast.error(error instanceof Error ? error.message : "登入失敗，請稍後重試");
    } finally {
        // 無論成功或失敗，都要關閉 loading 狀態（finally 確保一定會執行）
        isLoading.value = false;
    }
}
</script>

<template>
    <!-- 全螢幕置中容器：使用 Tailwind flex 讓登入卡片垂直水平置中於視窗 -->
    <div class="flex min-h-screen items-center justify-center bg-gradient-to-br from-slate-50 via-cyan-50 to-blue-50">
        <!-- 登入卡片：白色圓角框，最大寬度 sm，含陰影與 border -->
        <div class="w-full max-w-sm rounded-2xl border border-slate-200 bg-white/95 p-8 shadow-xl text-center">
            <!-- 應用程式副標題：小字金屬感大寫英文 -->
            <p class="text-xs uppercase tracking-[0.28em] text-cyan-600 font-semibold">StockGroup Console</p>
            <!-- 應用程式主標題 -->
            <h1 class="mt-3 text-3xl font-black text-slate-900">GooGod Platform</h1>
            <!-- 說明文字 -->
            <p class="mt-3 text-sm text-slate-500">登入後即可管理您的個人股票群組</p>

            <!-- 登入模式切換按鈕組，以 flex 並排顯示 -->
            <div class="mt-6 flex gap-2">
                <!-- Google 登入模式按鈕：點擊時切換 loginMode 為 "google" -->
                <button @click="loginMode = 'google'" :class="['flex-1 py-2 px-3 rounded-lg text-sm font-semibold transition', loginMode === 'google' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200']">Google 登入</button>
                <!-- 管理員登入模式按鈕：點擊時切換 loginMode 為 "admin" -->
                <button @click="loginMode = 'admin'" :class="['flex-1 py-2 px-3 rounded-lg text-sm font-semibold transition', loginMode === 'admin' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200']">管理員登入</button>
            </div>

            <!-- Google OAuth 登入按鈕：只在 loginMode 為 "google" 時顯示 -->
            <button v-if="loginMode === 'google'" @click="loginWithGoogle" class="mt-8 flex w-full items-center justify-center gap-3 rounded-xl border border-slate-300 bg-white px-5 py-3 text-sm font-semibold text-slate-700 shadow-sm transition hover:bg-slate-50 hover:shadow-md">
                <!-- Google 品牌 Logo SVG，使用官方品牌顏色 -->
                <svg class="h-5 w-5 shrink-0" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                    <!-- Google "G" logo 四個彩色路徑 -->
                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
                    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z" fill="#FBBC05" />
                    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
                </svg>
                使用 Google 帳號登入
            </button>

            <!-- 管理員帳號密碼登入表單：只在 loginMode 為 "admin" 時顯示 -->
            <div v-if="loginMode === 'admin'" class="mt-8 space-y-4">
                <!-- Email 輸入框：v-model 雙向綁定 email ref -->
                <input v-model="email" type="email" placeholder="帳號" class="w-full px-4 py-3 rounded-lg border border-slate-300 bg-slate-50 text-slate-900 placeholder-slate-500 focus:border-blue-500 focus:outline-none" />
                <!-- 密碼輸入框：隱藏輸入內容，支援 Enter 鍵送出 -->
                <input v-model="password" type="password" placeholder="密碼" class="w-full px-4 py-3 rounded-lg border border-slate-300 bg-slate-50 text-slate-900 placeholder-slate-500 focus:border-blue-500 focus:outline-none" @keyup.enter="loginWithPassword" />
                <!-- 登入按鈕：loading 時停用避免重複提交，並顯示文字變化提示使用者 -->
                <button @click="loginWithPassword" :disabled="isLoading" class="w-full px-5 py-3 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 transition disabled:opacity-50 disabled:cursor-not-allowed">
                    {{ isLoading ? "登入中..." : "登入" }}
                </button>
            </div>
        </div>
    </div>
</template>
